```java
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String PASSWORD = "bench";
    private static final String[] USERS = new String[17];
    static {
        for (int i = 1; i <= 16; i++) {
            USERS[i - 1] = "bench-" + i;
        }
        USERS[16] = "bench";
    }
    private static final AtomicInteger userCounter = new AtomicInteger(0);

    private static String jsonEscape(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n")
                .replace("\r", "\\r")
                .replace("\t", "\\t");
    }

    private static String normalizeUrl(String url) {
        if (url == null || url.isEmpty()) return url;
        if (url.startsWith("http://") || url.startsWith("https://")) return url;
        if (!url.startsWith("/")) return "/" + url;
        return url;
    }

    private static String extractJsonString(String json, String key) {
        if (json == null) return null;
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(json);
        if (m.find()) return m.group(1);
        return null;
    }

    private static Boolean extractJsonBoolean(String json, String key) {
        if (json == null) return null;
        Pattern p = Pattern.compile("\"" + key + "\"\\s*:\\s*(true|false)");
        Matcher m = p.matcher(json);
        if (m.find()) return Boolean.parseBoolean(m.group(1));
        return null;
    }

    private static int findMatchingBrace(String s, int openIndex) {
        if (openIndex < 0 || openIndex >= s.length() || s.charAt(openIndex) != '{') return -1;
        int depth = 0;
        boolean inString = false;
        boolean escaped = false;
        for (int i = openIndex; i < s.length(); i++) {
            char c = s.charAt(i);
            if (inString) {
                if (escaped) {
                    escaped = false;
                } else if (c == '\\') {
                    escaped = true;
                } else if (c == '"') {
                    inString = false;
                }
            } else {
                if (c == '"') {
                    inString = true;
                } else if (c == '{') {
                    depth++;
                } else if (c == '}') {
                    depth--;
                    if (depth == 0) return i;
                }
            }
        }
        return -1;
    }

    private static String[] findInStock(String json) {
        if (json == null) return null;
        Pattern p = Pattern.compile("\"in_stock\"\\s*:\\s*true");
        Matcher m = p.matcher(json);
        while (m.find()) {
            int inStockIdx = m.start();
            int varStart = json.lastIndexOf('{', inStockIdx);
            if (varStart < 0) continue;
            int varEnd = findMatchingBrace(json, varStart);
            if (varEnd < 0) continue;
            String varObj = json.substring(varStart, varEnd + 1);
            String variantId = extractJsonString(varObj, "id");
            if (variantId == null) continue;

            int variantsIdx = json.lastIndexOf("\"variants\"", varStart);
            if (variantsIdx < 0) continue;
            int prodStart = json.lastIndexOf('{', variantsIdx);
            if (prodStart < 0) continue;
            int prodEnd = findMatchingBrace(json, prodStart);
            if (prodEnd < 0) continue;
            String prodObj = json.substring(prodStart, prodEnd + 1);
            String productId = extractJsonString(prodObj, "id");
            if (productId != null) {
                return new String[]{productId, variantId};
            }
        }
        return null;
    }

    HttpProtocolBuilder httpProtocol = http
            .baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
            .acceptHeader("application/json, text/html, */*")
            .contentTypeHeader("application/json");

    ScenarioBuilder scn = scenario("ModelSimulation")
            .repeat(2).on(
                    exec(session -> {
                        int idx = userCounter.getAndIncrement() % USERS.length;
                        return session
                                .set("username", USERS[idx])
                                .set("workDone", false)
                                .set("reservationReady", false)
                                .remove("csrf")
                                .remove("cartId")
                                .remove("cartETag")
                                .remove("grantId")
                                .remove("productId")
                                .remove("variantId")
                                .remove("reservationId")
                                .remove("statusUrl");
                    })
                    .exec(http("GET /v2/login-form")
                            .get("/v2/login-form")
                            .check(status().is(200))
                            .check(css("input[type='hidden'][name='csrf']", "value").saveAs("loginCsrf"))
                    )
                    .exec(http("POST /v2/login")
                            .post("/v2/login")
                            .body(StringBody(session -> {
                                String username = session.getString("username");
                                String csrf = session.getString("loginCsrf");
                                return "{\"username\":\"" + jsonEscape(username) + "\",\"password\":\"" + PASSWORD + "\",\"csrf\":\"" + jsonEscape(csrf) + "\"}";
                            }))
                            .asJson()
                            .disableFollowRedirect()
                            .check(status().saveAs("loginStatus"))
                            .check(status().in(200, 302))
                            .check(header("Location").optional().saveAs("loginLocation"))
                            .check(bodyString().saveAs("loginBody"))
                    )
                    .exec(session -> {
                        int status = session.getInt("loginStatus");
                        if (status == 200) {
                            String csrf = extractJsonString(session.getString("loginBody"), "csrf");
                            if (csrf != null) {
                                session = session.set("csrf", csrf);
                            }
                        }
                        return session;
                    })
                    .doIf(session -> session.getInt("loginStatus") == 302).then(
                            exec(http("GET login redirect")
                                    .get(session -> normalizeUrl(session.getString("loginLocation")))
                                    .disableFollowRedirect()
                                    .check(status().is(200))
                                    .check(bodyString().saveAs("loginRedirectBody"))
                            )
                            .exec(session -> {
                                String csrf = extractJsonString(session.getString("loginRedirectBody"), "csrf");
                                if (csrf != null) {
                                    session = session.set("csrf", csrf);
                                }
                                return session;
                            })
                    )
                    .exec(session -> {
                        if (!session.contains("csrf") || session.getString("csrf") == null || session.getString("csrf").isEmpty()) {
                            throw new RuntimeException("Missing CSRF after login");
                        }
                        return session;
                    })
                    .exec(http("GET /v2/catalog")
                            .get("/v2/catalog")
                            .check(status().is(200))
                            .check(bodyString().saveAs("catalogBody"))
                    )
                    .exec(session -> {
                        String[] ids = findInStock(session.getString("catalogBody"));
                        if (ids == null) {
                            throw new RuntimeException("No in-stock variant found in catalog");
                        }
                        return session.set("productId", ids[0]).set("variantId", ids[1]);
                    })
                    .exec(http("GET /v2/challenge-form")
                            .get("/v2/challenge-form")
                            .check(status().is(200))
                            .check(css("form[action^='/v2/challenges/']", "action").saveAs("challengeAction"))
                            .check(css("input[name='challenge']", "value").saveAs("challengeToken"))
                    )
                    .exec(http("POST challenge")
                            .post(session -> normalizeUrl(session.getString("challengeAction")))
                            .header("X-CSRF-Token", session -> session.getString("csrf"))
                            .body(StringBody(session -> "{\"challenge\":\"" + jsonEscape(session.getString("challengeToken")) + "\"}"))
                            .asJson()
                            .disableFollowRedirect()
                            .check(status().is(302))
                            .check(header("Location").saveAs("challengeLocation"))
                    )
                    .exec(http("GET challenge redirect")
                            .get(session -> normalizeUrl(session.getString("challengeLocation")))
                            .disableFollowRedirect()
                            .check(status().is(200))
                            .check(bodyString().saveAs("challengeRedirectBody"))
                    )
                    .exec(session -> {
                        String body = session.getString("challengeRedirectBody");
                        String grantId = extractJsonString(body, "grant_id");
                        String newCsrf = extractJsonString(body, "csrf");
                        if (grantId != null) {
                            session = session.set("grantId", grantId);
                        }
                        if (newCsrf != null) {
                            session = session.set("csrf", newCsrf);
                        }
                        return session;
                    })
                    .exec(http("POST /v2/carts")
                            .post("/v2/carts")
                            .header("X-CSRF-Token", session -> session.getString("csrf"))
                            .body(StringBody(session -> {
                                String product = session.getString("productId");
                                String variant = session.getString("variantId");
                                String grant = session.contains("grantId") ? session.getString("grantId") : null;
                                StringBuilder sb = new StringBuilder();
                                sb.append("{\"product_id\":\"").append(jsonEscape(product)).append("\",\"variant_id\":\"").append(jsonEscape(variant)).append("\"");
                                if (grant != null && !grant.isEmpty()) {
                                    sb.append(",\"grant_id\":\"").append(jsonEscape(grant)).append("\"");
                                }
                                sb.append("}");
                                return sb.toString();
                            }))
                            .asJson()
                            .check(status().is(201))
                            .check(header("ETag").saveAs("cartETag"))
                            .check(bodyString().saveAs("cartBody"))
                    )
                    .exec(session -> {
                        String body = session.getString("cartBody");
                        String cartId = extractJsonString(body, "id");
                        String newCsrf = extractJsonString(body, "csrf");
                        if (cartId != null) {
                            session = session.set("cartId", cartId);
                        }
                        if (newCsrf != null) {
                            session = session.set("csrf", newCsrf);
                        }
                        return session;
                    })
                    .exec(http("GET /v2/carts/{id}")
                            .get(session -> "/v2/carts/" + session.getString("cartId"))
                            .check(status().is(200))
                            .check(header("ETag").saveAs("cartETag"))
                    )
                    .exec(http("PATCH /v2/carts/{id}")
                            .patch(session -> "/v2/carts/" + session.getString("cartId"))
                            .header("X-CSRF-Token", session -> session.getString("csrf"))
                            .header("If-Match", session -> session.getString("cartETag"))
                            .body(StringBody("{\"quantity\":1}"))
                            .asJson()
                            .check(status().saveAs("patchStatus"))
                            .check(status().in(200, 204, 412))
                            .check(header("ETag").optional().saveAs("newCartETag"))
