        return null;
      }
    }

    updateCsrf(state, poll);

    if (poll.status < 200 || poll.status >= 300) return null;

    const pb = safeJson(poll);
    if (!pb) return null;

    if (pb.status === 'ready') {
      if (pb.reservation_id !== undefined && pb.reservation_id !== null) {
        return pb.reservation_id;
      }
      return null;
    }

    if (pb.status === 'failed') return null;
  }

  return null;
}

function placeOrder(state, reservationId) {
  if (!state.cartId) return null;

  const idem = 'order-' + String(state.cartId);

  const payload = { cart_id: state.cartId };
  if (reservationId !== undefined && reservationId !== null) {
    payload.reservation_id = reservationId;
  }

  function headersFor() {
    const h = { 'Idempotency-Key': idem };
    if (state.cartEtag) h['If-Match'] = state.cartEtag;
    return csrfHeaders(state, h);
  }

  let res = req(
    'POST',
    '/v2/orders',
    payload,
    { headers: headersFor() }
  );

  if (res.status === 401) {
    const err = errCode(res);
    if (err === 'denied') return null;

    if (recoverFor(state, state.cartId, res)) {
      readCart(state);
      res = req(
        'POST',
        '/v2/orders',
        payload,
        { headers: headersFor() }
      );
    } else {
      return null;
    }
  }

  if (res.status === 412) {
    readCart(state);
    res = req(
      'POST',
      '/v2/orders',
      payload,
      { headers: headersFor() }
    );
  }

  updateCsrf(state, res);

  if (res.status === 201) {
    const b = safeJson(res);
    if (b && b.accepted === true && b.id !== undefined && b.id !== null) {
      return b.id;
    }
    return null;
  }

  if (res.status === 200) {
    const b = safeJson(res);
    if (b && b.accepted === false) {
      return null;
    }
  }

  return null;
}

export default function () {
  const state = {
    username: accountName(),
    user: null,
    csrf: null,
    cartId: null,
    cartEtag: null,
  };

  try {
    const loginOk = freshLogin(state, true);
    check(loginOk, { 'fresh login': (v) => v === true });
    if (!loginOk) return;

    const picked = getProduct(state);
    check(picked !== null, { 'catalog product': (v) => v !== null });
    if (!picked) return;

    const cart = createCart(state, picked);
    check(cart !== null, { 'cart created': (v) => v !== null });
    if (!cart) return;

    const patched = patchQuantity(state, 1);
    check(patched, { 'cart patched': (v) => v === true });
    if (!patched) return;

    const reservationId = reserve(state);
    check(reservationId !== null, { 'reservation ready': (v) => v !== null });
    if (reservationId === null) return;

    const orderId = placeOrder(state, reservationId);
    check(orderId !== null, { 'order committed': (v) => v !== null });
  } catch (e) {
    // Fail the journey through checks/audit; do not crash the k6 execution.
  }
}
