]

_started_users = 0
_completed_journeys = 0

_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))""",
    re.I | re.S,
)
_INPUT_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
_FORM_RE = re.compile(r"<form\b[^>]*>", re.I | re.S)


def _parse_attrs(tag):
    attrs = {}
    for m in _ATTR_RE.finditer(tag):
        name = m.group(1).lower()
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
        if val is None:
            val = ""
        attrs[name] = html_lib.unescape(val)
    return attrs


def extract_hidden_csrf(text):
    hidden = []
    fallback = []
    for m in _INPUT_RE.finditer(text):
        attrs = _parse_attrs(m.group(0))
        name = attrs.get("name", "").lower()
        if name != "csrf" or "value" not in attrs:
            continue
        if attrs.get("type", "").lower() == "hidden":
            hidden.append(attrs["value"])
        else:
            fallback.append(attrs["value"])
    if hidden:
        return hidden[0]
    if fallback:
        return fallback[0]
    return None


def extract_challenge_form(text):
    action = None
    for m in _FORM_RE.finditer(text):
        attrs = _parse_attrs(m.group(0))
        a = attrs.get("action", "")
        if "/v2/challenges/" in a:
            action = a
            break

    challenge = None
    for m in _INPUT_RE.finditer(text):
        attrs = _parse_attrs(m.group(0))
        if attrs.get("name", "").lower() == "challenge" and "value" in attrs:
            challenge = attrs["value"]
            break

    return action, challenge


def to_path(location):
    if not location:
        return location
    if location.startswith("http://") or location.startswith("https://"):
        p = urlparse(location)
        path = p.path or "/"
        if p.query:
            path += "?" + p.query
        return path
    if not location.startswith("/") and not location.startswith("?"):
        return "/" + location
    return location


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        global _started_users
        _started_users += 1
        self._user_index = _started_users - 1
        if self._user_index >= 2:
            raise StopUser()
        self.username = "bench-{}".format(min(self._user_index + 1, 16))
        self.profile = PROFILES[self._user_index % len(PROFILES)]
        self.csrf_token = None
        self.iterations_done = 0

    @task
    def run_flow(self):
        global _completed_journeys
        for _ in range(2):
            try:
                self._journey()
            finally:
                _completed_journeys += 1
        raise StopUser()

    def _json(self, resp):
        try:
            return resp.json()
        except Exception:
            return {}

    def _update_csrf(self, resp):
        data = self._json(resp)
        if isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]:
            self.csrf_token = data["csrf"]
            return True
        return False

    def _get_error(self, resp):
        data = self._json(resp)
        if isinstance(data, dict):
            return data.get("error")
        return None

    def _headers(self, method, extra=None):
        headers = dict(extra or {})
        if method.upper() not in ("GET", "HEAD", "OPTIONS") and self.csrf_token:
            headers.setdefault("X-CSRF-Token", self.csrf_token)
        return headers

    def _fresh_login(self):
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure("login form status {}".format(r.status_code))
                return False
            token = extract_hidden_csrf(r.text)
            if not token:
                r.failure("login csrf not found")
                return False
            r.success()

        self.csrf_token = token

        with self.client.post(
            "/v2/login",
