                        r2.failure("login redirect status {}".format(r2.status_code))
                        return False

                    data = self._json(r2)
                    if not isinstance(data, dict) or not isinstance(data.get("csrf"), str) or not data["csrf"]:
                        r2.failure("login redirect missing csrf")
                        return False

                    self.csrf_token = data["csrf"]
                    r2.success()
                    return True

            if r.status_code == 200:
                data = self._json(r)
                if not isinstance(data, dict) or not isinstance(data.get("csrf"), str) or not data["csrf"]:
                    r.failure("login missing csrf")
                    return False
                self.csrf_token = data["csrf"]
                r.success()
                return True

            r.failure("login status {}".format(r.status_code))
