    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers("POST"),
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                if not self._update_csrf(r):
                    r.failure("renew missing csrf")
                    return False
                r.success()
                return True

            if r.status_code == 401:
                r.success()
                return False

            r.failure("renew status {}".format(r.status_code))
            return False

    def _recover_cart(self, cart_id):
        with self.client.post(
            "/v2/carts/{}/recover".format(cart_id),
            json={},
            headers=self._headers("POST"),
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code in (200, 201, 204):
                self._update_csrf(r)
                r.success()
                return True
            r.failure("recover cart status {}".format(r.status_code))
            return False

    def _authed_request(
        self,
        method,
        path,
        json=None,
        headers=None,
        expected=(200,),
        allow_redirects=False,
        cart_id=None,
        max_recovery=1,
    ):
        recovery = 0
        while True:
            with self.client.request(
                method,
                path,
                json=json,
                headers=self._headers(method, headers),
                allow_redirects=allow_redirects,
                catch_response=True,
            ) as r:
                if r.status_code in expected:
                    self._update_csrf(r)
                    r.success()
                    return r

                if r.status_code == 401 and recovery < max_recovery:
                    err = self._get_error(r)
                    if err == "expired":
                        if self._renew_session():
                            if cart_id is not None and not self._recover_cart(cart_id):
                                r.failure("cart recover failed")
                                return r
                            r.success()
                            recovery += 1
                            continue

                    elif err == "session":
                        ok = self._renew_session()
                        if not ok:
                            ok = self._fresh_login()
                        if ok and (cart_id is None or self._recover_cart(cart_id)):
                            r.success()
                            recovery += 1
                            continue

                    elif err == "denied":
                        r.failure("401 denied")
                        return r

                r.failure("Unexpected {} for {} {}".format(r.status_code, method, path))
                return r

    def _do_work(self):
        retry_429 = 0
        recovered = False

        while True:
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._headers("POST"),
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code == 200:
                    data = self._json(r)
                    if isinstance(data, dict) and data.get("ok") is True:
                        self._update_csrf(r)
                        r.success()
