                    r.failure("work 429 retries exhausted")
                    return False

                if r.status_code == 401 and not recovered:
                    err = self._get_error(r)
                    if err == "expired":
                        if self._renew_session():
                            recovered = True
                            r.success()
                            continue
                    elif err == "session":
                        if self._renew_session() or self._fresh_login():
                            recovered = True
                            r.success()
