    def _extract_products(self, obj):
        products = []

        def walk(x):
            if isinstance(x, dict):
                if (
                    "id" in x
                    and "variants" in x
                    and isinstance(x.get("variants"), list)
                ):
                    products.append(x)

                if isinstance(x.get("products"), list):
                    for p in x["products"]:
                        if isinstance(p, dict):
                            products.append(p)

                if isinstance(x.get("product"), dict):
                    products.append(x["product"])

                if isinstance(x.get("data"), dict):
                    walk(x["data"])

                for k, v in x.items():
                    if k in ("products", "product", "data"):
                        continue
                    if isinstance(v, (dict, list)):
                        walk(v)

            elif isinstance(x, list):
                for item in x:
                    walk(item)

        walk(obj)

        seen = set()
        out = []
        for p in products:
            pid = p.get("id")
            if pid is None or pid in seen:
                continue
            seen.add(pid)
            out.append(p)
        return out

    def _pair_from_obj(self, obj):
        for product in self._extract_products(obj):
            pid = product.get("id")
            if pid is None:
                continue

            variants = product.get("variants")
            if not isinstance(variants, list):
                continue

            for variant in variants:
                if not isinstance(variant, dict):
                    continue
                if variant.get("in_stock") is True:
                    vid = variant.get("id")
                    if vid is not None:
                        return pid, vid
        return None

    def _find_product_variant(self):
        r = self._authed_request(
            "GET",
            "/v2/catalog",
            expected=(200,),
            allow_redirects=False,
        )
        if r.status_code == 200:
            pair = self._pair_from_obj(self._json(r))
            if pair:
                return pair

        path = "/v2/catalog/page"
        for _ in range(3):
            if not path:
                break

            r = self._authed_request(
                "GET",
                to_path(path),
                expected=(200,),
                allow_redirects=False,
            )
            if r.status_code != 200:
                break

            data = self._json(r)
            pair = self._pair_from_obj(data)
            if pair:
                return pair

            nxt = None
            if isinstance(data, dict):
                nxt = data.get("next")
                if nxt is None and isinstance(data.get("data"), dict):
                    nxt = data["data"].get("next")
            path = nxt

        return None

    def _get_grant_id(self):
        with self.client.get(
            "/v2/challenge-form",
            allow_redirects=False,
            catch_response=True,
        ) as r:
            if r.status_code != 200:
                r.failure("challenge form status {}".format(r.status_code))
                return None

            action, challenge = extract_challenge_form(r.text)
            if not action or not challenge:
                r.failure("challenge form parse failed")
                return None

            r.success()

        r = self._authed_request(
            "POST",
            action,
            json={"challenge": challenge},
            expected=(302,),
            allow_redirects=False,
        )
        if r.status_code != 302:
            return None

        loc = r.headers.get("Location")
        if not loc:
            return None

        with self.client.get(
            to_path(loc),
            allow_redirects=False,
            catch_response=True,
        ) as r2:
            if r2.status_code != 200:
                r2.failure("challenge redirect status {}".format(r2.status_code))
                return None

            data = self._json(r2)
            grant_id = None
            if isinstance(data, dict):
                grant_id = data.get("grant_id")
                if grant_id is None and isinstance(data.get("data"), dict):
                    grant_id = data["data"].get("grant_id")

            if grant_id is None:
                r2.failure("grant_id missing")
                return None

            if not self._update_csrf(r2):
                r2.failure("challenge missing csrf")
                return None

            r2.success()
            return grant_id

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id is not None:
            payload["grant_id"] = grant_id

        r = self._authed_request(
            "POST",
            "/v2/carts",
            json=payload,
            expected=(201,),
            allow_redirects=False,
        )
        if r.status_code != 201:
            return None

        data = self._json(r)
        cart_id = data.get("id") if isinstance(data, dict) else None
        if cart_id is None:
            return None

        self._update_csrf(r)
        return cart_id, r.headers.get("ETag")

    def _patch_cart(self, cart_id, etag):
        payload = {"quantity": 1}
        attempt_412 = 0
        recovery_used = False

        while True:
            headers = {"If-Match": etag} if etag else {}
            with self.client.patch(
                "/v2/carts/{}".format(cart_id),
                json=payload,
                headers=self._headers("PATCH", headers),
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code in (200, 204):
                    self._update_csrf(r)
                    r.success()
                    return True

                if r.status_code == 412:
                    if attempt_412 == 0:
                        attempt_412 += 1
                        r.success()

                        r2 = self._authed_request(
                            "GET",
                            "/v2/carts/{}".format(cart_id),
                            expected=(200,),
                            allow_redirects=False,
                            cart_id=cart_id,
                        )
                        if r2.status_code == 200:
                            etag = r2.headers.get("ETag", etag)
                            continue
                        return False

                    r.failure("412 after retry")
                    return False

                if r.status_code == 401 and not recovery_used:
                    err = self._get_error(r)
                    if err == "expired":
                        if self._renew_session() and self._recover_cart(cart_id):
                            recovery_used = True
                            r.success()
                            continue
                    elif err == "session":
                        ok = self._renew_session()
                        if not ok:
                            ok = self._fresh_login()
                        if ok and self._recover_cart(cart_id):
                            recovery_used = True
                            r.success()
                            continue
                    elif err == "denied":
                        r.failure("401 denied")
                        return False

                r.failure("PATCH status {}".format(r.status_code))
                return False

    def _reserve(self, cart_id):
        r = self._authed_request(
            "POST",
            "/v2/reservations",
            json={"cart_id": cart_id},
            expected=(202,),
            allow_redirects=False,
            cart_id=cart_id,
        )
        if r.status_code != 202:
            return None

        data = self._json(r)
        status_url = None
        if isinstance(data, dict):
            status_url = data.get("status_url")
            if status_url is None and isinstance(data.get("data"), dict):
                status_url = data["data"].get("status_url")

        if not status_url:
            return None

        self._update_csrf(r)

        for i in range(5):
            time.sleep(0.05)

            with self.client.get(
                to_path(status_url),
                headers=self._headers("GET"),
                allow_redirects=False,
                catch_response=True,
            ) as r2:
                if r2.status_code != 200:
                    r2.failure("reservation status HTTP {}".format(r2.status_code))
                    return None

                data = self._json(r2)
                status = None
                if isinstance(data, dict):
                    status = data.get("status")
                    if status is None and isinstance(data.get("data"), dict):
                        status = data["data"].get("status")

                if status == "ready":
                    reservation_id = None
                    if isinstance(data, dict):
                        reservation_id = data.get("reservation_id")
                        if reservation_id is None and isinstance(data.get("data"), dict):
                            reservation_id = data["data"].get("reservation_id")

                    if reservation_id is None:
                        r2.failure("reservation ready but missing id")
                        return None

                    r2.success()
                    return reservation_id

                if status == "failed":
                    r2.failure("reservation failed")
                    return None

                if status == "pending":
                    if i == 4:
                        r2.failure("reservation pending after max polls")
                        return None
                    r2.success()
                    continue

                r2.failure("reservation unknown status {}".format(status))
                return None

        return None

    def _checkout(self, cart_id, reservation_id, etag, idempotency_key):
        payload = {"cart_id": cart_id}
        if reservation_id is not None:
            payload["reservation_id"] = reservation_id

        headers = {"Idempotency-Key": idempotency_key}
        if etag:
            headers["If-Match"] = etag

        recovery_used = False

        while True:
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=self._headers("POST", headers),
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code == 201:
                    data = self._json(r)
                    if (
                        isinstance(data, dict)
                        and data.get("accepted") is True
                        and data.get("id") is not None
                    ):
                        self._update_csrf(r)
                        r.success()
                        return True
                    r.failure("201 but accepted/id missing")
                    return False

                if r.status_code == 200:
                    data = self._json(r)
                    if isinstance(data, dict) and data.get("accepted") is False:
                        r.failure("business failure accepted=false")
                    else:
                        r.failure("200 unexpected order response")
                    return False

                if r.status_code == 401 and not recovery_used:
                    err = self._get_error(r)
                    if err == "expired":
                        if self._renew_session() and self._recover_cart(cart_id):
                            recovery_used = True
                            r.success()
                            continue
                    elif err == "session":
                        ok = self._renew_session()
                        if not ok:
                            ok = self._fresh_login()
                        if ok and self._recover_cart(cart_id):
                            recovery_used = True
                            r.success()
                            continue
                    elif err == "denied":
                        r.failure("401 denied")
                        return False

                r.failure("order status {}".format(r.status_code))
                return False

    def _journey(self):
        if not self._fresh_login():
            return False

        self._do_work()

        pair = self._find_product_variant()
        if not pair:
            return False

        product_id, variant_id = pair

        grant_id = self._get_grant_id()
        if grant_id is None:
            return False

        cart = self._create_cart(product_id, variant_id, grant_id)
        if not cart:
            return False

        cart_id, etag = cart

        r = self._authed_request(
            "GET",
            "/v2/carts/{}".format(cart_id),
            expected=(200,),
            allow_redirects=False,
            cart_id=cart_id,
        )
        if r.status_code != 200:
            return False
        etag = r.headers.get("ETag", etag)

        if not self._patch_cart(cart_id, etag):
            return False

        r = self._authed_request(
            "GET",
            "/v2/carts/{}".format(cart_id),
            expected=(200,),
            allow_redirects=False,
            cart_id=cart_id,
        )
        if r.status_code == 200:
            etag = r.headers.get("ETag", etag)

        reservation_id = self._reserve(cart_id)
        if reservation_id is None:
            return False

        r = self._authed_request(
            "GET",
            "/v2/carts/{}".format(cart_id),
            expected=(200,),
            allow_redirects=False,
            cart_id=cart_id,
        )
        if r.status_code == 200:
            etag = r.headers.get("ETag", etag)

        idempotency_key = uuid.uuid4().hex
        return self._checkout(cart_id, reservation_id, etag, idempotency_key)


