    private static boolean isStatus(Session session, String key, int code) {
        Object v = session.get(key);
        return v != null && String.valueOf(code).equals(v.toString());
    }

    private static String extractInputValue(String html, String name) {
        if (html == null) {
            return null;
        }
        Pattern p = Pattern.compile("(?is)<input\\b[^>]*>");
        Matcher m = p.matcher(html);
        while (m.find()) {
            String tag = m.group();
            String attrName = getAttr(tag, "name");
            if (name.equals(attrName)) {
                String val = getAttr(tag, "value");
                if (val != null) {
                    return val;
                }
            }
        }
        return null;
    }

    private static String extractFormAction(String html, String contains) {
        if (html == null) {
            return null;
        }
        Pattern p = Pattern.compile("(?is)<form\\b[^>]*>");
        Matcher m = p.matcher(html);
        while (m.find()) {
            String tag = m.group();
            String action = getAttr(tag, "action");
            if (action != null && action.contains(contains)) {
                return action;
            }
        }
        return null;
    }

    private static String getAttr(String tag, String attr) {
        Pattern p = Pattern.compile("(?i)(?:^|\\s)" + Pattern.quote(attr)
                + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");
        Matcher m = p.matcher(tag);
        if (m.find()) {
            if (m.group(1) != null) {
                return m.group(1);
            }
            if (m.group(2) != null) {
                return m.group(2);
            }
            if (m.group(3) != null) {
                return m.group(3);
            }
        }
        return null;
    }

    @SuppressWarnings("unchecked")
    private static Object[] selectProductVariant(String json) {
        Object root = parseJson(json);
        if (!(root instanceof Map)) {
            return null;
        }
        Object dataObj = ((Map<String, Object>) root).get("data");
        if (!(dataObj instanceof Map)) {
            return null;
        }
        Object productsObj = ((Map<String, Object>) dataObj).get("products");
        if (!(productsObj instanceof List)) {
            return null;
        }
        List<Object> products = (List<Object>) productsObj;
        for (Object po : products) {
            if (!(po instanceof Map)) {
                continue;
            }
            Map<String, Object> product = (Map<String, Object>) po;
            Object variantsObj = product.get("variants");
            if (!(variantsObj instanceof List)) {
                continue;
            }
            List<Object> variants = (List<Object>) variantsObj;
            for (Object vo : variants) {
                if (!(vo instanceof Map)) {
                    continue;
                }
                Map<String, Object> variant = (Map<String, Object>) vo;
                Object inStock = variant.get("in_stock");
                if (Boolean.TRUE.equals(inStock)) {
                    return new Object[]{product.get("id"), variant.get("id")};
                }
            }
        }
        return null;
    }

    @SuppressWarnings("unchecked")
    private static Object getJsonField(String json, String key) {
        if (json == null || json.isEmpty()) {
            return null;
        }
        try {
            Object root = parseJson(json);
            if (root instanceof Map) {
                return ((Map<String, Object>) root).get(key);
            }
        } catch (Exception ignored) {
        }
        return null;
    }

    private static String toJsonValue(Object o) {
        if (o == null) {
            return "null";
        }
        if (o instanceof Number || o instanceof Boolean) {
            return o.toString();
        }
        return "\"" + escapeJson(String.valueOf(o)) + "\"";
    }

    private static String escapeJson(String s) {
        if (s == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    sb.append(c);
            }
        }
        return sb.toString();
    }

    private static Object parseJson(String s) {
        return new JsonParser(s).parse();
    }

    private static class JsonParser {
        private final String s;
        private int i = 0;

        JsonParser(String s) {
            this.s = s;
        }

        Object parse() {
            skipWhitespace();
            Object v = parseValue();
            skipWhitespace();
            if (i < s.length()) {
                throw new RuntimeException("Trailing data");
            }
            return v;
        }

        Object parseValue() {
            skipWhitespace();
            if (i >= s.length()) {
                throw new RuntimeException("EOF");
            }
            char c = s.charAt(i);
            if (c == '{') {
                return parseObject();
            }
            if (c == '[') {
                return parseArray();
            }
            if (c == '"') {
                return parseString();
            }
            if (c == 't') {
                expect("true");
                return Boolean.TRUE;
            }
            if (c == 'f') {
                expect("false");
                return Boolean.FALSE;
            }
            if (c == 'n') {
                expect("null");
                return null;
            }
            if (c == '-' || (c >= '0' && c <= '9')) {
                return parseNumber();
            }
            throw new RuntimeException("Unexpected char: " + c);
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            expect('{');
            skipWhitespace();
            if (peek('}')) {
                i++;
                return map;
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                expect(':');
                Object val = parseValue();
                map.put(key, val);
                skipWhitespace();
                if (peek(',')) {
                    i++;
                    continue;
                }
                expect('}');
                break;
            }
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            expect('[');
            skipWhitespace();
            if (peek(']')) {
                i++;
                return list;
            }
            while (true) {
                list.add(parseValue());
                skipWhitespace();
                if (peek(',')) {
                    i++;
                    continue;
                }
                expect(']');
                break;
            }
            return list;
        }

        String parseString() {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (i < s.length()) {
                char c = s.charAt(i++);
                if (c == '"') {
                    return sb.toString();
                }
                if (c == '\\') {
                    if (i >= s.length()) {
                        throw new RuntimeException("Bad escape");
                    }
                    char e = s.charAt(i++);
                    switch (e) {
                        case '"':
                            sb.append('"');
                            break;
                        case '\\':
                            sb.append('\\');
                            break;
                        case '/':
                            sb.append('/');
                            break;
                        case 'b':
                            sb.append('\b');
                            break;
                        case 'f':
                            sb.append('\f');
                            break;
                        case 'n':
                            sb.append('\n');
                            break;
                        case 'r':
                            sb.append('\r');
                            break;
                        case 't':
                            sb.append('\t');
                            break;
                        case 'u':
                            if (i + 4 > s.length()) {
                                throw new RuntimeException("Bad unicode");
                            }
                            int code = Integer.parseInt(s.substring(i, i + 4), 16);
                            sb.append((char) code);
                            i += 4;
