  var etag = res ? getHeader(res, 'ETag') : null;
  if (etag) {
    cart.etag = etag;
  } else {
    var fresh = getCartEtag(cart.id, auth);
    if (fresh) cart.etag = fresh;
  }

  return res;
}

function createOrder(cart, auth) {
  if (!cart.etag) {
    var etag0 = getCartEtag(cart.id, auth);
    if (etag0) cart.etag = etag0;
  }

  var idempotencyKey = 'order-' + cart.id + '-' + __VU + '-' + __ITER + '-' + Date.now();

  var headers = {
    'Content-Type': 'application/json',
    'Idempotency-Key': idempotencyKey
  };

  if (cart.etag) headers['If-Match'] = cart.etag;

  var res = authRequest('POST', BASE_URL + '/v2/orders', JSON.stringify({ cart_id: cart.id }), {
    headers: headers,
    tags: { name: 'POST /v2/orders' }
  }, auth, cart);

  var j = res ? safeJson(res.body) : null;

  check(res, {
    'order status 201': function (r) {
      return r && r.status === 201;
    }
  });

  check(!!(j && j.accepted === true), {
    'order accepted true': function (v) { return v === true; }
  });

  check(!!(j && j.id), {
    'order id present': function (v) { return v === true; }
  });

  return res;
}

export default function () {
  var username;
  if (__VU >= 1 && __VU <= 16) {
    username = 'bench-' + __VU;
  } else {
    username = 'bench';
  }

  var auth = login(username, true);
  check(!!(auth && auth.csrf), {
    'journey auth csrf present': function (v) { return v === true; }
  });

  var selected = selectProduct();
  check(!!selected, {
    'eligible in-stock product selected': function (v) { return v === true; }
  });

  if (!selected) return;

  var belongs = false;
  if (selected.product && Array.isArray(selected.product.variants)) {
    for (var i = 0; i < selected.product.variants.length; i++) {
      if (String(selected.product.variants[i].id) === String(selected.variant.id)) {
        belongs = true;
        break;
      }
    }
  }

  check(belongs, {
    'variant belongs to selected parent': function (v) { return v === true; }
  });

  var cart = createCart(selected, auth);
  check(!!(cart && cart.id), {
    'cart created for selected variant': function (v) { return v === true; }
  });

  if (!cart || !cart.id) return;

  patchCart(cart, auth);
  createOrder(cart, auth);
}
