import os
import re
import itertools
import html as html_mod

import gevent
from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

TOTAL_USERS = 2
ITERATIONS = 2
_finished_users = 0
_account_counter = itertools.count(1)


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = between(0.01, 0.05)

    def on_start(self):
        idx = next(_account_counter)
        if idx <= 16:
            self.account = f"bench-{idx}"
        else:
            self.account = "bench"
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.etag = None

    @task
    def journey(self):
        try:
            for _ in range(ITERATIONS):
                self._run_journey()
        except Exception:
            pass
        finally:
            global _finished_users
            _finished_users += 1

        while _finished_users < TOTAL_USERS:
            gevent.sleep(0.05)
        raise StopUser()

    def _run_journey(self):
        self.cart_id = None
        self.etag = None
        if not self._login():
            return

        product = self._select_product()
        if not product:
            return

        product_id, variant_id = product
        grant_id = self._get_grant_id()
        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return

        self.cart_id = cart_id
        if not self._patch_cart(cart_id, 1):
            return

        reservation_id, reserved = self._reserve(cart_id)
        if not reserved:
            return

        self._create_order(cart_id, reservation_id)

    def _json(self, resp):
        try:
            data = resp.json()
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    def _error_code(self, resp):
        data = self._json(resp)
        return data.get("error")

    def _request(
        self,
        method,
        url,
        expected=(200,),
        allow_401=False,
        allow_412=False,
        allow_429=False,
        validator=None,
        **kwargs
    ):
        kwargs.setdefault("allow_redirects", False)
        with self.client.request(method, url, catch_response=True, **kwargs) as resp:
            status = resp.status_code
            if status in expected:
                if validator is not None:
                    try:
                        ok, msg = validator(resp)
                    except Exception as e:
                        ok, msg = False, f"validator error: {e}"
                    if ok:
                        resp.success()
                    else:
                        resp.failure(msg)
                else:
                    resp.success()
            elif status == 401 and allow_401:
                err = self._error_code(resp)
                if err in ("expired", "session", None):
                    resp.success()
                else:
                    resp.failure(f"401 {err}")
            elif status == 412 and allow_412:
                resp.success()
            elif status == 429 and allow_429:
                resp.success()
            else:
                text = (resp.text or "")[:200]
                resp.failure(f"unexpected status {status}: {text}")
            return resp

    def _auth_headers(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        return headers

    def _update_csrf(self, data):
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _update_etag(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("etag")
        if etag:
            self.etag = etag

    def _recover_cart(self, cart_id):
        if not cart_id:
            return True
        for attempt in range(2):
            resp = self._request(
                "POST",
                f"/v2/carts/{cart_id}/recover",
                json={},
                expected=(200,),
                allow_401=(attempt == 0),
                headers=self._auth_headers(),
            )
            if resp.status_code == 200:
                self._update_csrf(self._json(resp))
                self._update_etag(resp)
                return True
            if resp.status_code == 401 and attempt == 0:
                if not self._login():
                    return False
                continue
            return False
        return False

    def _recover_401(self, resp, cart_id=None):
        err = self._error_code(resp)
        if err == "denied":
            return False

        if err == "expired":
            renew = self._request(
                "POST",
                "/v2/session/renew",
                json={},
                expected=(200,),
                allow_401=True,
                headers=self._auth_headers(),
            )
            if renew.status_code == 200:
                self._update_csrf(self._json(renew))
            else:
                if not self._login():
                    return False
            return self._recover_cart(cart_id)

        if err in ("session", None):
            if not self._login():
                return False
            return self._recover_cart(cart_id)

        return False

    def _get_with_recovery(self, url, expected=(200,)):
        did_401 = False
        while True:
            resp = self._request(
                "GET",
                url,
                expected=expected,
                allow_401=not did_401,
                headers=self._auth_headers(),
            )
            if resp.status_code == 401 and not did_401:
                did_401 = True
                if self._recover_401(resp, cart_id=self.cart_id):
                    continue
                return resp
            return resp

    def _extract_attr(self, tag_attrs, attr):
        pattern = (
            r"(?<![\w-])"
            + re.escape(attr)
            + r"\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))"
        )
        m = re.search(pattern, tag_attrs, re.I)
        if not m:
            return None
        val = next(g for g in m.groups() if g is not None)
        return html_mod.unescape(val)

    def _extract_input_value(self, text, name):
        for m in re.finditer(r"<input\b[^>]*>", text or "", re.I):
            tag = m.group(0)
            n = self._extract_attr(tag, "name")
            if n is not None and n.lower() == name.lower():
                v = self._extract_attr(tag, "value")
                if v is not None:
                    return v
        return None

    def _extract_challenge_form(self, text):
        for m in re.finditer(r"<form\b([^>]*)>(.*?)</form>", text or "", re.I | re.S):
            attrs = m.group(1)
            body = m.group(2)
            challenge = self._extract_input_value(body, "challenge")
            if challenge is None:
                continue
            action = self._extract_attr(attrs, "action")
            if action:
                return action, challenge

        challenge = self._extract_input_value(text, "challenge")
        if challenge is None:
            return None, None
        m = re.search(r"<form\b([^>]*)>", text or "", re.I)
        if m:
            action = self._extract_attr(m.group(1), "action")
            if action:
                return action, challenge
        return None, None

    def _login(self):
        self.client.cookies.clear()
        self.csrf = None

        def login_form_validator(resp):
            return (
                self._extract_input_value(resp.text, "csrf") is not None,
                "login form missing csrf",
            )

        form_resp = self._request(
            "GET",
            "/v2/login-form",
            expected=(200,),
            validator=login_form_validator,
        )
        if form_resp.status_code != 200:
            return False

        csrf = self._extract_input_value(form_resp.text, "csrf")
        if not csrf:
            return False

        def login_post_validator(resp):
            if resp.status_code == 200:
                data = self._json(resp)
                return bool(data.get("csrf")), "login response missing csrf"
            if resp.status_code == 302:
                return bool(resp.headers.get("Location")), "login redirect missing Location"
            return False, "unexpected login response"

        login_resp = self._request(
            "POST",
            "/v2/login",
            json={"username": self.account, "password": self.password, "csrf": csrf},
            expected=(200, 302),
            validator=login_post_validator,
        )

        if login_resp.status_code == 302:
            loc = login_resp.headers.get("Location")
            if not loc:
                return False

            def csrf_validator(resp):
                data = self._json(resp)
                return bool(data.get("csrf")), "response missing csrf"

            loc_resp = self._request(
                "GET",
                loc,
                expected=(200,),
                validator=csrf_validator,
            )
            if loc_resp.status_code == 200:
                data = self._json(loc_resp)
                self._update_csrf(data)
                return self.csrf is not None
            return False

        if login_resp.status_code == 200:
            data = self._json(login_resp)
            self._update_csrf(data)
            return self.csrf is not None

        return False

    def _is_in_stock(self, variant):
        val = variant.get("in_stock")
        if val is True or val == 1:
            return True
        if isinstance(val, str) and val.lower() == "true":
            return True
        return False

    def _find_variant_in_json(self, obj):
        if isinstance(obj, dict):
            variants = obj.get("variants")
            if isinstance(variants, list):
                for v in variants:
                    if isinstance(v, dict) and self._is_in_stock(v):
                        pid = obj.get("id")
                        vid = v.get("id")
                        if pid is not None and vid is not None:
                            return pid, vid
            for value in obj.values():
                found = self._find_variant_in_json(value)
                if found:
                    return found
        elif isinstance(obj, list):
            for item in obj:
                found = self._find_variant_in_json(item)
                if found:
                    return found
        return None

    def _select_product(self):
        resp = self._get_with_recovery("/v2/catalog")
        if resp.status_code == 200:
            data = self._json(resp)
            found = self._find_variant_in_json(data)
            if found:
                return found

        url = "/v2/catalog/page"
        for _ in range(3):
            resp = self._get_with_recovery(url, expected=(200, 404, 405))
            if resp.status_code != 200:
                return None

            data = self._json(resp)
            found = self._find_variant_in_json(data)
            if found:
                return found

            nxt = None
            if isinstance(data, dict):
                nxt = data.get("next")
                if not nxt and isinstance(data.get("data"), dict):
                    nxt = data.get("data").get("next")
            if not nxt:
                break
            url = nxt

        return None

    def _get_grant_id(self):
        for attempt in range(2):
            resp = self._request(
                "GET",
                "/v2/challenge-form",
                expected=(200, 404, 405),
                allow_401=(attempt == 0),
                headers=self._auth_headers(),
            )
            if resp.status_code == 401 and attempt == 0:
                if self._recover_401(resp, cart_id=self.cart_id):
                    continue
                return None
            if resp.status_code != 200:
                return None

            action, challenge = self._extract_challenge_form(resp.text)
            if not action or not challenge:
                return None

            challenge_resp = self._request(
                "POST",
                action,
                json={"challenge": challenge},
                expected=(302, 404, 405),
                allow_401=(attempt == 0),
                headers=self._auth_headers(),
            )
            if challenge_resp.status_code == 401 and attempt == 0:
                if self._recover_401(challenge_resp, cart_id=self.cart_id):
                    continue
                return None
            if challenge_resp.status_code != 302:
                return None

            loc = challenge_resp.headers.get("Location")
            if not loc:
                return None

            def grant_validator(resp):
                data = self._json(resp)
                return bool(data.get("grant_id")), "grant response missing grant_id"

            grant_resp = self._request(
                "GET",
                loc,
                expected=(200,),
                allow_401=(attempt == 0),
                validator=grant_validator,
            )
            if grant_resp.status_code == 401 and attempt == 0:
                if self._recover_401(grant_resp, cart_id=self.cart_id):
                    continue
                return None
            if grant_resp.status_code == 200:
                data = self._json(grant_resp)
                self._update_csrf(data)
                return data.get("grant_id")
            return None

        return None

    def _cart_validator(self, resp):
        data = self._json(resp)
        return bool(data.get("id")), "cart response missing id"

    def _create_cart(self, product_id, variant_id, grant_id=None):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id

        did_401 = False
        while True:
            resp = self._request(
                "POST",
                "/v2/carts",
                json=payload,
                expected=(201,),
                allow_401=not did_401,
                headers=self._auth_headers(),
                validator=self._cart_validator,
            )
            if resp.status_code == 201:
                data = self._json(resp)
                self._update_csrf(data)
                self._update_etag(resp)
                return data.get("id")

            if resp.status_code == 401 and not did_401:
                did_401 = True
                if self._recover_401(resp, cart_id=None):
                    if grant_id:
                        new_grant = self._get_grant_id()
                        if new_grant:
                            grant_id = new_grant
                            payload["grant_id"] = grant_id
                        else:
                            payload.pop("grant_id", None)
                    continue
                return None

            return None

    def _get_cart(self, cart_id):
        did_401 = False
        while True:
            resp = self._request(
                "GET",
                f"/v2/carts/{cart_id}",
                expected=(200,),
                allow_401=not did_401,
                headers=self._auth_headers(),
            )
            if resp.status_code == 200:
                self._update_csrf(self._json(resp))
                self._update_etag(resp)
                return resp
            if resp.status_code == 401 and not did_401:
                did_401 = True
                if self._recover_401(resp, cart_id=cart_id):
                    continue
                return resp
            return resp

    def _patch_cart(self, cart_id, quantity=1):
        payload = {"quantity": quantity}
        if not self.etag:
            self._get_cart(cart_id)

        did_401 = False
        did_412 = False
        while True:
            headers = self._auth_headers()
            if self.etag:
                headers["If-Match"] = self.etag

            resp = self._request(
                "PATCH",
                f"/v2/carts/{cart_id}",
                json=payload,
                expected=(200, 204),
                allow_401=not did_401,
                allow_412=not did_412,
                headers=headers,
            )
            if resp.status_code in (200, 204):
                self._update_csrf(self._json(resp))
                self._update_etag(resp)
                return True

            if resp.status_code == 412 and not did_412:
                did_412 = True
                self._get_cart(cart_id)
                continue

            if resp.status_code == 401 and not did_401:
                did_401 = True
                if self._recover_401(resp, cart_id=cart_id):
                    continue
                return False

            return False

    def _reserve(self, cart_id):
        did_401 = False
        while True:
            resp = self._request(
                "POST",
                "/v2/reservations",
                json={"cart_id": cart_id},
                expected=(202, 404, 405),
                allow_401=not did_401,
                headers=self._auth_headers(),
            )

            if resp.status_code == 202:
                data = self._json(resp)
                self._update_csrf(data)
                status_url = data.get("status_url")
                if not status_url:
                    return None, False

                poll_401 = False
                for i in range(5):
                    if i > 0:
                        gevent.sleep(0.05)

                    poll = self._request(
                        "GET",
                        status_url,
                        expected=(200, 202),
                        allow_401=not poll_401,
                        headers=self._auth_headers(),
                    )

                    if poll.status_code == 401 and not poll_401:
                        poll_401 = True
                        if self._recover_401(poll, cart_id=cart_id):
                            poll = self._request(
                                "GET",
                                status_url,
                                expected=(200, 202),
                                allow_401=False,
                                headers=self._auth_headers(),
                            )
                        else:
                            return None, False

                    if poll.status_code not in (200, 202):
                        return None, False

                    pdata = self._json(poll)
                    self._update_csrf(pdata)
                    status = pdata.get("status")

                    if status == "ready":
                        rid = pdata.get("reservation_id")
                        return rid, bool(rid)
                    if status == "failed":
                        return None, False
                    if status is None and pdata.get("reservation_id"):
                        return pdata.get("reservation_id"), True

                return None, False

            if resp.status_code == 401 and not did_401:
                did_401 = True
                if self._recover_401(resp, cart_id=cart_id):
                    continue
                return None, False

            if resp.status_code in (404, 405):
                return None, True

            return None, False

    def _order_validator(self, resp):
        data = self._json(resp)
        if data.get("accepted") is True and data.get("id"):
            return True, ""
        return False, f"order not accepted: {data}"

    def _create_order(self, cart_id, reservation_id=None):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        idem_key = f"order-{cart_id}"
        did_401 = False
        did_412 = False

        while True:
            headers = self._auth_headers()
            headers["Idempotency-Key"] = idem_key
            if self.etag:
                headers["If-Match"] = self.etag

            resp = self._request(
                "POST",
                "/v2/orders",
                json=payload,
                expected=(201,),
                allow_401=not did_401,
                allow_412=not did_412,
                headers=headers,
                validator=self._order_validator,
            )

            if resp.status_code == 201:
                data = self._json(resp)
                self._update_csrf(data)
                if data.get("accepted") is True and data.get("id"):
                    return True
                return False

            if resp.status_code == 412 and not did_412:
                did_412 = True
                self._get_cart(cart_id)
                continue

            if resp.status_code == 401 and not did_401:
                did_401 = True
                if self._recover_401(resp, cart_id=cart_id):
                    continue
                return False

            return False


class ShopShape(LoadTestShape):
    def tick(self):
        if _finished_users >= TOTAL_USERS:
            return None
        if self.get_run_time() > 180:
            return None
        return TOTAL_USERS, 1
