import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl())
            .disableFollowRedirect()
            .disableCaching()
            .acceptHeader("application/json,text/html,*/*");

    private static String baseUrl() {
        String base = System.getenv("BASE_URL");
        if (base == null || base.isEmpty()) {
            base = "http://127.0.0.1:8000";
        }
        return base;
    }

    public ModelSimulation() {
        ScenarioBuilder scn = scenario("ModelSimulation")
                .repeat(2).on(
                        exec(session -> {
                            long uid = session.userId();
                            String username = "bench-" + (Math.floorMod(uid, 16L) + 1L);
                            return session
                                    .set("username", username)
                                    .set("pageCount", 0)
                                    .set("found", false)
                                    .remove("productId")
                                    .remove("variantId")
                                    .remove("nextUrl")
                                    .remove("cartId")
                                    .remove("etag")
                                    .remove("grant_id")
                                    .remove("reservation_id")
                                    .remove("csrf")
                                    .remove("statusUrl")
                                    .remove("resStatus")
                                    .remove("workDone")
                                    .remove("workTries");
                        })
                        .exec(login())
                        .exitHereIfFailed()
                        .exec(initialCatalogPage())
                        .exitHereIfFailed()
                        .exec(session -> parseCatalogPage(session))
                        .asLongAs(session -> {
                            String next = session.getString("nextUrl");
                            return !session.getBoolean("found")
                                    && next != null
                                    && !next.isEmpty()
                                    && session.getInt("pageCount") < 3;
                        }).on(
                                exec(nextCatalogPage())
                                        .exitHereIfFailed()
                                        .exec(session -> parseCatalogPage(session))
                        )
                        .exec(session -> {
                            if (!session.getBoolean("found")) {
                                throw new IllegalStateException("No eligible product found within 3 catalog pages");
                            }
                            if (session.getString("productId") == null || session.getString("variantId") == null) {
                                throw new IllegalStateException("Eligible product missing productId or variantId");
                            }
                            return session;
                        })
                        .exec(challenge())
                        .exitHereIfFailed()
                        .exec(createCart())
                        .exitHereIfFailed()
                        .exec(session -> parseCart(session))
                        .exec(getCart())
                        .exitHereIfFailed()
                        .exec(patchCart())
                        .exitHereIfFailed()
                        .exec(getCart())
                        .exitHereIfFailed()
                        .exec(reserveAndPoll())
                        .exitHereIfFailed()
                        .exec(createOrder())
                        .exitHereIfFailed()
                        .exec(session -> {
                            if (session.getString("orderId") == null) {
                                throw new IllegalStateException("Order id missing");
                            }
                            return session;
                        })
                        .exec(workSample())
                );

        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }

    private static ChainBuilder login() {
        return exec(
                http("GET login form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(css("input[name=csrf]", "value").saveAs("loginCsrf"))
        ).exitHereIfFailed()
                .exec(
                        http("POST login")
                                .post("/v2/login")
                                .asJson()
                                .body(StringBody(session -> {
                                    String username = session.getString("username");
                                    String csrf = session.getString("loginCsrf");
                                    return "{\"username\":\"" + escapeJson(username)
