    private static String escapeJson(String s) {
        if (s == null) {
            return "";
        }
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static String extractString(String body, String key) {
        if (body == null) {
            return null;
        }
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return unescapeJson(m.group(1));
        }
        return null;
    }

    private static String extractNext(String body) {
        if (body == null) {
            return null;
        }
        Pattern p = Pattern.compile("\"next\"\\s*:\\s*(?:\"((?:\\\\.|[^\"\\\\])*)\"|null)");
        Matcher m = p.matcher(body);
        if (m.find()) {
            String s = m.group(1);
            return s == null ? null : unescapeJson(s);
        }
        return null;
    }

    private static String normalizeNextUrl(String next) {
        if (next == null) {
            return null;
        }
        next = next.trim();
        if (next.isEmpty() || "null".equalsIgnoreCase(next)) {
            return null;
        }
        if (next.startsWith("http://") || next.startsWith("https://")) {
            return next;
        }
        if (next.startsWith("/")) {
            return next;
        }
        if (next.startsWith("?")) {
            return "/v2/catalog/page" + next;
        }
        if (next.startsWith("catalog/")) {
            return "/v2/" + next;
        }
        if (next.startsWith("page")) {
            return "/v2/catalog/" + next;
        }
        return "/" + next;
    }

    private static String extractProductId(String body) {
        if (body == null) {
            return null;
        }
        int variantsIdx = body.indexOf("\"variants\"");
        String before = variantsIdx >= 0 ? body.substring(0, variantsIdx) : body;
        Pattern p = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"");
        Matcher m = p.matcher(before);
        String last = null;
        while (m.find()) {
            last = m.group(1);
        }
        if (last != null) {
            return unescapeJson(last);
        }
        m = p.matcher(body);
        if (m.find()) {
            return unescapeJson(m.group(1));
        }
        return null;
    }

    private static String extractInStockVariantId(String body) {
        if (body == null) {
            return null;
        }
        String variants = extractVariantsArray(body);
        if (variants == null) {
            return null;
        }
        Pattern p1 = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"[^{}]*\"in_stock\"\\s*:\\s*true");
        Matcher m = p1.matcher(variants);
        if (m.find()) {
            return unescapeJson(m.group(1));
        }
        Pattern p2 = Pattern.compile("\"in_stock\"\\s*:\\s*true[^{}]*\"id\"\\s*:\\s*\"([^\"]+)\"");
        m = p2.matcher(variants);
        if (m.find()) {
            return unescapeJson(m.group(1));
        }
        return null;
    }

    private static String extractVariantsArray(String body) {
        int idx = body.indexOf("\"variants\"");
        if (idx < 0) {
            return null;
        }
        int start = body.indexOf('[', idx);
        if (start < 0) {
            return null;
        }
        int depth = 0;
        boolean inString = false;
        boolean escaped = false;
        for (int i = start; i < body.length(); i++) {
            char c = body.charAt(i);
            if (inString) {
                if (escaped) {
                    escaped = false;
                } else if (c == '\\') {
                    escaped = true;
                } else if (c == '"') {
                    inString = false;
                }
            } else {
                if (c == '"') {
                    inString = true;
                } else if (c == '[' || c == '{') {
                    depth++;
                } else if (c == ']' || c == '}') {
                    depth--;
                    if (depth == 0 && c == ']') {
                        return body.substring(start, i + 1);
                    }
                }
            }
        }
        return body.substring(start);
    }

    private static String unescapeJson(String s) {
        if (s == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                char n = s.charAt(++i);
                switch (n) {
                    case '"':
                        sb.append('"');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    case '/':
                        sb.append('/');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'u':
                        if (i + 4 < s.length()) {
                            String hex = s.substring(i + 1, i + 5);
                            try {
                                sb.append((char) Integer.parseInt(hex, 16));
                            } catch (NumberFormatException e) {
                                sb.append("\\u").append(hex);
                            }
                            i += 4;
                        } else {
                            sb.append('\\').append(n);
                        }
                        break;
                    default:
                        sb.append(n);
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
