            tag = m.group(0)
            attr = re.search(r'action\s*=\s*["\']([^"\']+)["\']', tag, re.I)
            if attr and contains in attr.group(1):
                return attr.group(1)
        m = re.search(r'action\s*=\s*["\']([^"\']+)["\']', html, re.I)
        return m.group(1) if m else None

    def _extract_products(self, data):
        if not isinstance(data, dict):
            if isinstance(data, list):
                return data
            return []
        if "products" in data and isinstance(data["products"], list):
            return data["products"]
        if "data" in data and isinstance(data["data"], dict):
            d = data["data"]
            if "products" in d and isinstance(d["products"], list):
                return d["products"]
            if "product" in d and isinstance(d["product"], dict):
                return [d["product"]]
        if "product" in data and isinstance(data["product"], dict):
            return [data["product"]]
        if "id" in data and "variants" in data:
            return [data]
        return []

    def _extract_next(self, data):
        if not isinstance(data, dict):
            return None
        if data.get("next"):
            return data["next"]
        if isinstance(data.get("data"), dict):
            return data["data"].get("next")
        return None

    def _find_eligible(self, products):
        for product in products:
            if not isinstance(product, dict):
                continue
            pid = product.get("id")
            variants = product.get("variants")
            if pid is None or not isinstance(variants, list):
                continue
            for v in variants:
                if not isinstance(v, dict):
                    continue
                vid = v.get("id")
                if vid is not None and v.get("in_stock"):
                    return pid, vid
        return None
