        if r.status_code == 401:
            r.success()
            return False
        r.failure("session renew status %s" % r.status_code)
        return False

    def _recover_cart(self, cart_id):
        r = self._raw(
            "POST", "/v2/carts/%s/recover" % cart_id, "POST /v2/carts/[id]/recover", json={}
        )
        if r.status_code in (200, 201, 204):
            self._capture_csrf(r)
            r.success()
            return True
        r.failure("cart recover status %s" % r.status_code)
