    # ---------------- helpers ----------------

    def _safe_json(self, r):
        try:
            return r.json()
        except Exception:
            return None

    def _lookup(self, data, key):
        if isinstance(data, dict):
            if key in data:
                return data[key]
            for container in ("data", "payload", "result"):
                nested = data.get(container)
                if isinstance(nested, dict) and key in nested:
                    return nested[key]
        return None

    def _capture_csrf(self, r):
        token = self._lookup(self._safe_json(r), "csrf")
        if isinstance(token, str) and token:
            self.csrf_token = token

    @staticmethod
    def _truthy(value):
        if value is True:
            return True
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        if isinstance(value, str):
            return value.strip().lower() in ("true", "1", "yes")
