    def _extract_csrf(self, html):
        candidates = []
        for attrs in self._tag_attrs(html, _INPUT_RE):
            if (attrs.get("name") or "").lower() != "csrf":
                continue
            value = attrs.get("value")
            if value:
                candidates.append(attrs)
        if not candidates:
            return None
        for attrs in candidates:
            if (attrs.get("type") or "").lower() == "hidden":
                return attrs["value"]
        return candidates[0]["value"]

    def _parse_challenge(self, html):
        action = None
        for attrs in self._tag_attrs(html, _FORM_RE):
            candidate = attrs.get("action")
            if candidate and "/v2/challenges/" in candidate:
                action = candidate
                break
        challenge = None
        for attrs in self._tag_attrs(html, _INPUT_RE):
            if (attrs.get("name") or "").lower() != "challenge":
                continue
            value = attrs.get("value")
            if value:
                challenge = value
                break
        return action, challenge

    def _walk_products(self, node, depth=0):
        if depth > 5:
            return
        if isinstance(node, dict):
            if "id" in node and isinstance(node.get("variants"), list):
                yield node
            for value in node.values():
                for found in self._walk_products(value, depth + 1):
                    yield found
        elif isinstance(node, list):
            for value in node:
                for found in self._walk_products(value, depth + 1):
                    yield found

    def _pick_product(self, data):
        for node in self._walk_products(data):
            product_id = node.get("id")
            variants = node.get("variants")
