            return item
        cursor = self._next_cursor(data)
        if not cursor:
            r.failure("catalog: no eligible product and no next cursor")
            return None
        url = urljoin(r.request.url, cursor)
        r.success()

        for page in range(3):
            pr = self._send("GET", url, "GET /v2/catalog/page")
            if pr.status_code != 200:
