            return False
        for attempt in range(2):
            headers = {"If-Match": etag} if etag else {}
            r = self._send(
                "PATCH",
                "/v2/carts/%s" % cart_id,
                "PATCH /v2/carts/[id]",
                cart_id=cart_id,
                json={"quantity": 1},
                headers=headers,
            )
            if r.status_code in (200, 204):
                self._capture_csrf(r)
                r.success()
                return True
            if r.status_code == 412 and attempt == 0:
                r.success()
                ok, etag = self._cart_etag(cart_id)
                if not ok:
                    return False
                continue
            r.failure("cart patch status %s" % r.status_code)
            return False
        return False

    def _reserve(self, cart_id):
        r = self._send(
            "POST",
            "/v2/reservations",
            "POST /v2/reservations",
            cart_id=cart_id,
            json={"cart_id": cart_id},
        )
        if r.status_code != 202:
            r.failure("reservation create status %s" % r.status_code)
            return None
        status_url = self._lookup(self._safe_json(r), "status_url")
        if not status_url:
            r.failure("reservation create: status_url missing")
            return None
        self._capture_csrf(r)
        poll_url = urljoin(r.request.url, status_url)
        r.success()

        for attempt in range(5):
            if attempt > 0:
                time.sleep(0.05)
            pr = self._send("GET", poll_url, "GET reservation status", cart_id=cart_id)
            if pr.status_code != 200:
                pr.failure("reservation poll status %s" % pr.status_code)
                return None
            payload = self._safe_json(pr)
            status = self._lookup(payload, "status")
            if status == "ready":
                reservation_id = self._lookup(payload, "reservation_id")
                if not reservation_id:
                    pr.failure("reservation ready without reservation_id")
                    return None
                self._capture_csrf(pr)
                pr.success()
                return reservation_id
            if status == "pending":
                if attempt == 4:
                    pr.failure("reservation still pending after 5 polls")
                    return None
                pr.success()
                continue
            if status == "failed":
                pr.failure("reservation status failed")
                return None
            pr.failure("reservation unknown status %r" % (status,))
            return None
        return None

    def _place_order(self, cart_id, reservation_id):
        ok, etag = self._cart_etag(cart_id)
        if not ok:
            return False
        headers = {"Idempotency-Key": "cart-%s" % cart_id}
        if etag:
            headers["If-Match"] = etag
        r = self._send(
            "POST",
            "/v2/orders",
            "POST /v2/orders",
            cart_id=cart_id,
            json={"cart_id": cart_id, "reservation_id": reservation_id},
            headers=headers,
        )
        if r.status_code == 201:
            payload = self._safe_json(r)
            accepted = self._lookup(payload, "accepted")
            order_id = self._lookup(payload, "id")
            if accepted is True and order_id is not None:
                self._capture_csrf(r)
                r.success()
                return True
            r.failure("order create: invalid success payload")
            return False
        if r.status_code == 200:
            if self._lookup(self._safe_json(r), "accepted") is False:
                r.failure("order create: business failure accepted=false")
            else:
                r.failure("order create: unexpected 200 response")
            return False
        r.failure("order create status %s" % r.status_code)
        return False
