import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const QUANTITY = Number(__ENV.QUANTITY || 2) || 2;
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function vuNumber() {
  return (typeof __VU === 'number' && __VU > 0) ? __VU : 1;
}

function usernameForVu() {
  const vu = vuNumber();
  return 'bench-' + (((vu - 1) % 16) + 1);
}

function absoluteUrl(loc) {
  if (!loc) return BASE_URL;
  loc = String(loc);
  if (loc.indexOf('http://') === 0 || loc.indexOf('https://') === 0) return loc;
  if (loc.charAt(0) === '/') return BASE_URL + loc;
  if (loc.indexOf('//') === 0) return 'http:' + loc;
  return BASE_URL + '/' + loc;
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const lower = String(name).toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === lower) return res.headers[k];
  }
  return null;
}

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (e) {
    try {
      return JSON.parse(res.body);
    } catch (e2) {
      return null;
    }
  }
}

function decodeHtml(s) {
  if (s === undefined || s === null) return '';
  return String(s)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&#x2F;/gi, '/');
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>]+))/g;
  let m;
  while ((m = re.exec(tag)) !== null) {
    const key = m[1].toLowerCase();
    const val = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4];
    attrs[key] = decodeHtml(val);
  }
  return attrs;
}

function extractInputValue(html, name) {
  if (!html) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let fallback = null;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const attrs = parseAttrs(m[0]);
    if (attrs.name === name) {
      const val = attrs.value || '';
      if (val) return val;
      if (fallback === null) fallback = val;
    }
  }
  return fallback;
}

function extractFormAction(html, actionIncludes) {
  if (!html) return null;
  const formRe = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRe.exec(html)) !== null) {
    const attrs = parseAttrs(m[0]);
    const action = attrs.action;
    if (action && (!actionIncludes || action.indexOf(actionIncludes) !== -1)) {
      return decodeHtml(action);
    }
  }
  return null;
}

function getCsrfFromResponse(res) {
  if (!res) return null;
  const j = safeJson(res);
  if (j) {
    if (typeof j.csrf === 'string' && j.csrf) return j.csrf;
    if (j.data && typeof j.data.csrf === 'string' && j.data.csrf) return j.data.csrf;
  }
  if (res.body && res.body.indexOf('csrf') !== -1) {
    const v = extractInputValue(res.body, 'csrf');
    if (v) return v;
  }
  return null;
}

function getEtag(res) {
  return getHeader(res, 'ETag');
}

function rawRequest(method, path, body, headers, tags) {
  const url = absoluteUrl(path);
  return http.request(method, url, body === undefined ? null : body, {
    headers: headers || {},
    redirects: 0,
    tags: tags || {},
  });
}

function clearCookies() {
  try {
    const jar = http.cookieJar();
    if (jar && typeof jar.clear === 'function') {
      jar.clear(BASE_URL);
    }
  } catch (e) {}
}

function login() {
  const formRes = rawRequest('GET', '/v2/login-form', null, {}, { name: 'login-form' });
  check(formRes, { 'login form 200': r => r.status === 200 });

  const csrfFromForm = extractInputValue(formRes.body, 'csrf');
  const payload = JSON.stringify({
    username: usernameForVu(),
    password: PASSWORD,
    csrf: csrfFromForm || '',
  });

  let loginRes = rawRequest('POST', '/v2/login', payload, { 'Content-Type': 'application/json' }, { name: 'login' });
  if (loginRes.status >= 300 && loginRes.status < 400) {
    const loc = getHeader(loginRes, 'Location');
    if (loc) {
      loginRes = rawRequest('GET', absoluteUrl(loc), null, {}, { name: 'login-redirect' });
    }
  }

  const authenticated = loginRes.status === 200;
  const csrf = getCsrfFromResponse(loginRes);
  check(loginRes, { 'login authenticated': r => r.status === 200 });
  check(csrf, { 'csrf extracted from login': v => !!v });

  return { csrf: csrf, res: loginRes, ok: authenticated };
}

function authRequest(method, path, bodyObj, extraHeaders, state, tags) {
  const url = absoluteUrl(path);
  const baseHeaders = {};
  for (const k in extraHeaders) baseHeaders[k] = extraHeaders[k];

  if (method !== 'GET' && method !== 'HEAD') {
    baseHeaders['X-CSRF-Token'] = state.csrf;
  }

  let payload = null;
  if (bodyObj !== undefined && bodyObj !== null) {
    payload = JSON.stringify(bodyObj);
    if (!baseHeaders['Content-Type']) baseHeaders['Content-Type'] = 'application/json';
  }

  let res = http.request(method, url, payload, { headers: baseHeaders, redirects: 0, tags: tags || {} });

  let retry429 = 0;
  while (res.status === 429 && retry429 < 4) {
    const ra = getHeader(res, 'Retry-After');
    let delay = 1;
    if (ra) {
      const m = String(ra).match(/\d+/);
      if (m) delay = Number(m[0]);
    }
    if (!isFinite(delay) || delay < 0) delay = 1;
    sleep(delay);
    res = http.request(method, url, payload, { headers: baseHeaders, redirects: 0, tags: tags || {} });
    retry429++;
  }

  if (res.status === 401) {
    const ej = safeJson(res);
    const err = ej && ej.error;

    if (err === 'expired' || err === 'session') {
      if (err === 'session') {
        const loginOut = login();
        if (loginOut.csrf) state.csrf = loginOut.csrf;
      } else {
        const renewRes = http.request('POST', BASE_URL + '/v2/session/renew', JSON.stringify({}), {
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
          redirects: 0,
          tags: { name: 'session-renew' },
        });
        const c = getCsrfFromResponse(renewRes);
        if (c) state.csrf = c;
      }

      if (state.cartId) {
        const recRes = http.request('POST', BASE_URL + '/v2/carts/' + state.cartId + '/recover', JSON.stringify({}), {
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf },
          redirects: 0,
          tags: { name: 'cart-recover' },
        });
        const c2 = getCsrfFromResponse(recRes);
        if (c2) state.csrf = c2;
        const e2 = getEtag(recRes);
        if (e2) state.etag = e2;
      }

      const retryHeaders = {};
      for (const k in extraHeaders) retryHeaders[k] = extraHeaders[k];
      if (method !== 'GET' && method !== 'HEAD') {
        retryHeaders['X-CSRF-Token'] = state.csrf;
      }
      if (payload !== null && !retryHeaders['Content-Type']) {
        retryHeaders['Content-Type'] = 'application/json';
      }
      res = http.request(method, url, payload, { headers: retryHeaders, redirects: 0, tags: tags || {} });
    } else {
      check(null, { '401 error is expiry/session': () => false });
    }
  }

  return res;
}

function readCart(state) {
  const res = authRequest('GET', '/v2/carts/' + state.cartId, null, {}, state, { name: 'cart-read' });
  check(res, { 'cart read 200': r => r.status === 200 });

  const e = getEtag(res);
  if (e) state.etag = e;
  const c = getCsrfFromResponse(res);
  if (c) state.csrf = c;

  return res;
}

function tryGetGrantId(state) {
  const formRes = rawRequest('GET', '/v2/challenge-form', null, {}, { name: 'challenge-form' });
  if (formRes.status >= 500) {
    check(formRes, { 'challenge form not 500': () => false });
    return null;
  }
  if (formRes.status !== 200) return null;

  const action = extractFormAction(formRes.body, '/v2/challenges/');
  const challenge = extractInputValue(formRes.body, 'challenge');
  const parsed = action && challenge;
  check(parsed, { 'challenge form parsed': v => !!v });
  if (!parsed) return null;

  const postRes = authRequest(
    'POST',
    action,
    { challenge: challenge },
    { 'Content-Type': 'application/json' },
    state,
    { name: 'challenge-post' }
  );
  check(postRes, { 'challenge post not 500': r => r.status < 500 });

  let finalRes = postRes;
  const loc = getHeader(postRes, 'Location');
  if (loc) {
    finalRes = rawRequest('GET', absoluteUrl(loc), null, {}, { name: 'challenge-redirect' });
  }
  check(finalRes, { 'challenge final not 500': r => r.status < 500 });

  const j = safeJson(finalRes);
  let grant = null;
