```python
import os
import re
import time
import uuid
from html import unescape as html_unescape

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
EXPECTED_USERS = int(os.environ.get("USERS", "2"))
ITERATIONS = int(os.environ.get("ITERATIONS", "2"))
QUANTITY = int(os.environ.get("QUANTITY", "2"))

_slots_taken = 0
_slots_done = 0

_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))"""
)


def _attrs(tag):
    result = {}
    for m in _ATTR_RE.finditer(tag):
        name = m.group(1).lower()
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
        result[name] = html_unescape(val or "")
    return result


def _extract_input_value(text, input_name):
    if not text:
        return None
    target = input_name.lower()
    for m in re.finditer(r"<input\b[^>]*>", text, re.I):
        attrs = _attrs(m.group(0))
        if attrs.get("name", "").lower() == target:
            return attrs.get("value")
    return None


def _json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def _error_code(resp):
    data = _json(resp)
    if isinstance(data, dict):
        return data.get("error")
    return None


def _etag(resp):
    for key in ("ETag", "Etag", "etag"):
        value = resp.headers.get(key)
        if value:
            return value
    return None


def _products_from(data):
    if not isinstance(data, dict):
        return []
    for source in (data, data.get("data")):
        if isinstance(source, dict):
            products = source.get("products")
            if isinstance(products, list):
                return products
            product = source.get("product")
            if isinstance(product, dict):
                return [product]
    if "variants" in data and "id" in data:
        return [data]
    return []


def _next_url(data):
    if not isinstance(data, dict):
        return None
    for source in (data, data.get("data")):
        if isinstance(source, dict):
            nxt = source.get("next")
            if nxt:
                return nxt
    return None


def _choose_variant(products):
    for product in products:
        if not isinstance(product, dict):
            continue
        product_id = product.get("id")
        if product_id is None:
            continue
        variants = product.get("variants") or []
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if not isinstance(variant, dict):
                continue
            variant_id = variant.get("id")
            if variant_id is None:
                continue
            in_stock = variant.get("in_stock")
            if in_stock is True or in_stock == 1:
                return str(product_id), str(variant_id)
    return None


def _abs_path(location):
    if location.startswith("http://") or location.startswith("https://"):
        return location
    if location.startswith("/"):
        return location
    return "/" + location


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0, 0)

    def on_start(self):
        global _slots_taken
        if _slots_taken >= EXPECTED_USERS:
            self.dead = True
            return
        _slots_taken += 1
        self.dead = False
        self.slot_id = _slots_taken
        self.username = ("bench-%d" % self.slot_id) if 1 <= self.slot_id <= 16 else "bench"

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure("login form status %s" % r.status_code)
                return None
            csrf = _extract_input_value(r.text, "csrf")
            if not csrf:
                r.failure("missing login csrf")
                return None
            r.success()

        payload = {"username": self.username, "password": "bench", "csrf": csrf}
        with self.client.post(
            "/v2/login",
            json=payload,
            name="/v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302:
                location = r.headers.get("Location")
                if not location:
                    r.failure("302 missing Location")
                    return None
                r.success()
                with self.client.get(
                    _abs_path(location),
                    name="/v2/login-location",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure("login location status %s" % r2.status_code)
                        return None
                    data = _json(r2)
                    if not isinstance(data, dict) or not data.get("csrf"):
                        r2.failure("login location missing csrf")
                        return None
                    new_csrf = data["csrf"]
                    r2.success()
                return new_csrf

            if r.status_code == 200:
                data = _json(r)
                if not isinstance(data, dict) or not data.get("csrf"):
                    r.failure("login missing csrf")
                    return None
                new_csrf = data["csrf"]
                r.success()
                return new_csrf

            r.failure("login status %s" % r.status_code)
            return None

    def _renew(self, csrf):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": csrf},
            name="/v2/session/renew",
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                data = _json(r)
                new_csrf = data.get("csrf") if isinstance(data, dict) else None
                r.success()
                return new_csrf or csrf
            if r.status_code == 401:
                r.success()
                return None
            r.failure("renew status %s" % r.status_code)
            return None

    def _recover_cart(self, cart_id, csrf):
        with self.client.post(
            "/v2/carts/%s/recover" % cart_id,
            json={},
            headers={"X-CSRF-Token": csrf},
            name="/v2/carts/{id}/recover",
            catch_response=True,
        ) as r:
            if 200 <= r.status_code < 300:
                data = _json(r)
                new_csrf = data.get("csrf") if isinstance(data, dict) else None
                r.success()
                return new_csrf or csrf
            r.failure("recover status %s" % r.status_code)
            return None

    def _fresh_login_and_recover(self, cart_id):
        new_csrf = self._login()
        if not new_csrf:
            return None
        if cart_id:
            return self._recover_cart(cart_id, new_csrf)
        return new_csrf

    def _handle_401(self, cart_id, csrf, error):
        if error == "expired":
            renewed = self._renew(csrf)
            if renewed:
                if cart_id:
                    return self._recover_cart(cart_id, renewed)
                return renewed
            if cart_id:
                return self._fresh_login_and_recover(cart_id)
            return self._login()
        if error == "session":
            if cart_id:
                return self._fresh_login_and_recover(cart_id)
            return self._login()
        return None

    def _get_cart(self, cart_id, csrf):
        recovered = False
        for _ in range(2):
            with self.client.get(
                "/v2/carts/%s" % cart_id,
                name="/v2/carts/{id}",
                catch_response=True,
            ) as r:
                if r.status_code == 200:
                    etag = _etag(r)
                    if not etag:
                        r.failure("missing cart ETag")
                        return None, csrf, None
                    data = _json(r)
                    r.success()
                    return etag, csrf, data if isinstance(data, dict) else {}
                if r.status_code == 401 and not recovered:
                    err = _error_code(r)
                    if err in ("expired", "session"):
                        r.success()
                        new_csrf = self._handle_401(cart_id, csrf, err)
                        if new_csrf:
                            csrf = new_csrf
                            recovered = True
                            continue
                    r.failure("GET cart 401 %s" % err)
                    return None, csrf, None
                r.failure("GET cart status %s" % r.status_code)
                return None, csrf, None
        return None, csrf, None

    def _patch_cart(self, cart_id, csrf, etag, quantity):
        payload = {"quantity": quantity}
        conflict_retried = False
        recovered = False
        for _ in range(4):
            headers = {"If-Match": etag, "X-CSRF-Token": csrf}
            with self.client.patch(
                "/v2/carts/%s" % cart_id,
                json=payload,
                headers=headers,
                name="/v2/carts/{id} PATCH",
                catch_response=True,
            ) as r:
                if 200 <= r.status_code < 300:
                    data = _json(r)
                    new_csrf = data.get("csrf") if isinstance(data, dict) else None
                    r.success()
                    return True, new_csrf or csrf
                if r.status_code == 412:
                    if conflict_retried:
                        r.failure("repeated 412")
                        return False, csrf
                    r.success()
                    etag2, csrf2, _ = self._get_cart(cart_id, csrf)
                    if not etag2:
                        return False, csrf2
                    etag = etag2
                    csrf = csrf2
                    conflict_retried = True
                    continue
                if r.status_code == 401:
                    err = _error_code(r)
                    if err in ("expired", "session") and not recovered:
                        r.success()
                        new_csrf = self._handle_401(cart_id, csrf, err)
                        if new_csrf:
                            csrf = new_csrf
                            etag2, csrf2, _ = self._get_cart(cart_id, csrf)
                            if not etag2:
                                return False, csrf2
                            etag = etag2
                            csrf = csrf2
                            recovered = True
                            continue
                    r.failure("PATCH 401 %s" % err)
                    return False, csrf
                r.failure("PATCH status %s" % r.status_code)
                return False, csrf
        return False, csrf

    def _create_cart(self, product_id, variant_id, csrf):
        payload = {"product_id": product_id, "variant_id": variant_id}
        recovered = False
        for _ in range(2):
            with self.client.post(
                "/v2/carts",
                json=payload,
                headers={"X-CSRF-Token": csrf},
                name="/v2/carts",
                catch_response=True,
            ) as r:
                if r.status_code == 201:
                    data = _json(r)
                    if not isinstance(data, dict):
                        data = {}
                    cart_id = data.get("id")
                    new_csrf = data.get("csrf")
                    etag = _etag(r)
                    if cart_id is None:
                        r.failure("missing cart id")
                        return None
                    r.success()
                    return {"id": str(cart_id), "csrf": new_csrf or csrf, "etag": etag}
                if r.status_code == 401:
                    err = _error_code(r)
                    if err in ("expired", "session") and not recovered:
                        r.success()
                        new_csrf = self._handle_401(None, csrf, err)
                        if new_csrf:
                            csrf = new_csrf
                            recovered = True
                            continue
                    r.failure("cart create 401 %s" % err)
                    return None
                r.failure("cart create status %s" % r.status_code)
                return None
        return None

    def _find_product_variant(self):
        urls = ["/v2/catalog"]
        pages = 0
        first_had_products = False
        while urls and pages < 3:
            url = urls.pop(0)
            pages += 1
            name = "/v2/catalog" if pages == 1 else "/v2/catalog/page"
            with self.client.get(url, name=name, catch_response=True) as r:
                if r.status_code == 404:
                    r.success()
                    break
                if r.status_code != 200:
                    r.failure("catalog status %s" % r.status_code)
                    return None
                data = _json(r)
                products = _products_from(data)
                if pages == 1 and products:
                    first_had_products = True
                choice = _choose_variant(products)
                if choice:
                    r.success()
                    return choice
                nxt = _next_url(data)
                if nxt:
                    urls.append(nxt)
                elif not first_had_products and pages == 1:
                    urls.append("/v2/catalog/page")
                r.success()
        return None

    def _place_order(self, cart_id, csrf, etag, idem_key):
        payload = {"cart_id": cart_id}
        headers = {
            "X-CSRF-Token": csrf,
            "Idempotency-Key": idem_key,
            "If-Match": etag,
        }
        recovered = False
        for _ in range(2):
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                name="/v2/orders",
                catch_response=True,
            ) as r:
                if r.status_code == 201:
                    data = _json(r)
                    accepted = data.get("accepted") if isinstance(data, dict) else None
                    if accepted is True:
                        r.success()
                        return True, csrf
                    r.failure("order 201 accepted not true")
                    return False, csrf
                if r.status_code == 200:
                    r.failure("order status 200 (accepted:false)")
                    return False, csrf
                if r.status_code == 401:
                    err = _error_code(r)
                    if err in ("expired", "session") and not recovered:
                        r.success()
                        new_csrf = self._handle_401(cart_id, csrf, err)
                        if new_csrf:
                            csrf = new_csrf
                            etag2, csrf2, _ = self._get_cart(cart_id, csrf)
                            if not etag2:
                                return False, csrf2
                            csrf = csrf2
                            etag = etag2
                            headers = {
                                "X-CSRF-Token": csrf,
                                "Idempotency-Key": idem_key,
                                "If-Match": etag,
                            }
                            recovered = True
                            continue
                    r.failure("order 401 %s" % err)
                    return False, csrf
                r.failure("order status %s" % r.status_code)
                return False, csrf
        return False, csrf

    def _journey(self):
        csrf = self._login()
        if not csrf:
            return False

        choice = self._find_product_variant()
        if not choice:
            return False
        product_id, variant_id = choice

        cart = self._create_cart(product_id, variant_id, csrf)
        if not cart:
            return False
        cart_id = cart["id"]
        csrf = cart["csrf"]
        etag = cart["etag"]

        if not etag:
            etag, csrf, _ = self._get_cart(cart_id, csrf)
            if not etag:
                return False

        ok, csrf = self._patch_cart(cart_id, csrf, etag, QUANTITY)
        if not ok:
            return False

        etag, csrf, _ = self._get_cart(cart_id, csrf)
        if not etag:
            return False

        idem_key = "order-%s-%s" % (cart_id, uuid.uuid4().hex)
        ok, _ = self._place_order(cart_id, csrf, etag, idem_key)
        return ok

    @task
    def journey_task(self):
        global _slots_done
        if getattr(self, "dead", False):
            raise StopUser()
        try:
            for _ in range(ITERATIONS):
                try:
                    self._journey()
                except StopUser:
                    raise
                except Exception:
                    pass
        finally:
            _slots_done += 1
        raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start = time.time()

    def tick(self):
        if _slots_done >= EXPECTED_USERS:
            return None
        if time.time() - self.start > 60:
            return None
        current = max(1, EXPECTED_USERS - _slots_done)
        return (current, current)
