import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.core.session.Session;

import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
            .disableFollowRedirect()
            .acceptHeader("application/json,text/html;q=0.9,*/*;q=0.8")
            .userAgentHeader("gatling-model-simulation");

    private final ScenarioBuilder scn = scenario("ModelSimulation")
            .feed(userFeeder())
            .repeat(2).on(
                    clearJourneyState(),
                    login(),
                    getCatalogAndPickVariant(),
                    createCart(),
                    prepareOrderKey(),
                    orderAttempt("POST /v2/orders"),
                    doIf(session -> intAttr(session, "orderStatus") == 401)
                            .then(
                                    recoverSessionAndCart(),
                                    orderAttempt("POST /v2/orders retry"),
                                    validateOrder()
                            )
                            .orElse(
                                    validateOrder()
                            )
            );

    public ModelSimulation() {
        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }

    private Iterator<Map<String, Object>> userFeeder() {
        List<Map<String, Object>> users = new ArrayList<>();

        Map<String, Object> u1 = new HashMap<>();
        u1.put("username", "bench-1");
        users.add(u1);

        Map<String, Object> u2 = new HashMap<>();
        u2.put("username", "bench-2");
        users.add(u2);

        return users.iterator();
    }

    private ChainBuilder clearJourneyState() {
        return exec(session -> session
                .remove("cartId")
                .remove("cartEtag")
                .remove("idemKey")
                .remove("productId")
                .remove("variantId")
                .remove("cartStatus")
                .remove("cartError")
                .remove("cartCsrf")
                .remove("orderStatus")
                .remove("orderAccepted")
                .remove("orderId")
                .remove("orderError")
                .remove("orderCsrf")
                .remove("renewStatus")
                .remove("renewCsrf")
                .remove("renewError")
                .remove("recoverStatus")
                .remove("recoverCsrf")
                .remove("recoverEtag")
                .remove("loginStatus")
                .remove("loginLocation")
                .remove("loginCsrf")
                .remove("loginRedirectCsrf")
                .remove("csrf")
        );
    }

    private ChainBuilder login() {
        return exec(http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name=csrf]", "value").saveAs("csrf")))
                .exec(http("POST /v2/login")
                        .post("/v2/login")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "${csrf}")
                        .body(StringBody("{\"username\":\"${username}\",\"password\":\"bench\",\"csrf\":\"${csrf}\"}")).asJson()
                        .check(status().in(200, 302).saveAs("loginStatus"))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(jsonPath("$.csrf").optional().saveAs("loginCsrf")))
                .exec(session -> updateCsrf(session, "loginCsrf"))
                .doIf(session -> intAttr(session, "loginStatus") == 302
                        && session.getString("loginLocation") != null
                        && !session.getString("loginLocation").isEmpty())
                .then(exec(http("GET /v2/login redirect")
                                .get("${loginLocation}")
                                .check(status().is(200))
                                .check(jsonPath("$.csrf").optional().saveAs("loginRedirectCsrf")))
                        .exec(session -> updateCsrf(session, "loginRedirectCsrf")))
                .exec(session -> {
                    String csrf = session.getString("csrf");
                    if (csrf == null || csrf.isEmpty()) {
                        throw new RuntimeException("No CSRF after login");
                    }
                    return session
                            .remove("loginStatus")
                            .remove("loginLocation")
                            .remove("loginCsrf")
                            .remove("loginRedirectCsrf");
                });
    }

    private ChainBuilder getCatalogAndPickVariant() {
        return exec(http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                .check(jsonPath("$.data.products[0].variants[?(@.in_stock==true)][0].id").saveAs("variantId")))
                .exec(session -> {
                    if (session.getString("productId") == null || session.getString("variantId") == null) {
                        throw new RuntimeException("No in-stock product/variant found");
                    }
                    return session;
                });
    }

    private ChainBuilder createCart() {
        return exec(http("POST /v2/carts")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "${csrf}")
                .body(StringBody("{\"product_id\":\"${productId}\",\"variant_id\":\"${variantId}\"}")).asJson()
                .check(status().in(201, 401).saveAs("cartStatus"))
                .check(jsonPath("$.id").optional().saveAs("cartId"))
                .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                .check(header("ETag").optional().saveAs("cartEtag"))
                .check(jsonPath("$.error").optional().saveAs("cartError")))
                .exec(session -> updateCsrf(session, "cartCsrf"))
                .exec(session -> {
                    int status = intAttr(session, "cartStatus");
                    if (status == 401) {
                        String error = session.getString("cartError");
                        if (!isExpiryError(error)) {
                            throw new RuntimeException("Unexpected cart 401 error=" + error);
                        }
                    } else if (status != 201) {
                        throw new RuntimeException("Cart creation failed status=" + status);
                    }
                    return session;
                })
                .doIf(session -> intAttr(session, "cartStatus") == 401)
                .then(
                        recoverSessionAndCart(),
                        exec(http("POST /v2/carts retry")
                                .post("/v2/carts")
                                .header("Content-Type", "application/json")
                                .header("X-CSRF-Token", "${csrf}")
                                .body(StringBody("{\"product_id\":\"${productId}\",\"variant_id\":\"${variantId}\"}")).asJson()
                                .check(status().is(201))
                                .check(jsonPath("$.id").saveAs("cartId"))
                                .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                                .check(header("ETag").optional().saveAs("cartEtag"))),
                        exec(session -> updateCsrf(session, "cartCsrf"))
                )
                .exec(session -> {
                    String cartId = session.getString("cartId");
                    if (cartId == null || cartId.isEmpty()) {
                        throw new RuntimeException("No cart id after cart creation");
                    }
                    return session;
                });
    }

    private ChainBuilder prepareOrderKey() {
        return exec(session -> {
            String cartId = session.getString("cartId");
            return session.set("idemKey", "order-" + cartId + "-" + session.userId());
        });
    }

    private ChainBuilder orderAttempt(String name) {
        return exec(http(name)
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "${csrf}")
                .header("Idempotency-Key", "${idemKey}")
                .header("If-Match", "${cartEtag}")
                .body(StringBody("{\"cart_id\":\"${cartId}\"}")).asJson()
                .check(status().in(200, 201, 401).saveAs("orderStatus"))
                .check(jsonPath("$.accepted").optional().saveAs("orderAccepted"))
                .check(jsonPath("$.id").optional().saveAs("orderId"))
                .check(jsonPath("$.csrf").optional().saveAs("orderCsrf"))
                .check(jsonPath("$.error").optional().saveAs("orderError")))
                .exec(session -> updateCsrf(session, "orderCsrf"))
                .exec(session -> {
                    int status = intAttr(session, "orderStatus");
                    if (status == 401) {
                        String error = session.getString("orderError");
                        if (!isExpiryError(error)) {
                            throw new RuntimeException("Unexpected order 401 error=" + error);
                        }
                    } else if (status != 200 && status != 201) {
                        throw new RuntimeException("Unexpected order status=" + status);
                    }
                    return session;
                });
    }

    private ChainBuilder recoverSessionAndCart() {
        return exec(http("POST /v2/session/renew")
                .post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "${csrf}")
                .body(StringBody("{}")).asJson()
                .check(status().in(200, 401).saveAs("renewStatus"))
                .check(jsonPath("$.csrf").optional().saveAs("renewCsrf"))
                .check(jsonPath("$.error").optional().saveAs("renewError")))
                .exec(session -> updateCsrf(session, "renewCsrf"))
