function abs(url) {
  if (!url) return BASE;
  if (/^https?:\/\//i.test(url)) return url;
  if (String(url).startsWith('/')) return BASE + url;
  return BASE + '/' + url;
}

function hasHeader(headers, name) {
  const target = name.toLowerCase();
  return Object.keys(headers || {}).some((k) => k.toLowerCase() === target);
