function extractProducts(obj) {
  if (!obj) return [];
  if (obj.data && Array.isArray(obj.data.products)) return obj.data.products;
  if (Array.isArray(obj.products)) return obj.products;
  if (obj.data && Array.isArray(obj.data.product)) return obj.data.product;
  if (obj.data && obj.data.product) return [obj.data.product];
  if (obj.product) return [obj.product];
