  check(order, { 'order accepted': (o) => !!(o && o.ok === true) });
  check(state, { 'exactly one cart': (s) => s.cartCreates === 1 });
  check(state, { 'exactly one order': (s) => s.orders === 1 });
  check(state, { 'expiry recognized': (s) => s.expiryRecognized === true });
  check(state, {
