    if not base.startswith("http://") and not base.startswith("https://"):
        base = "http://" + base
    return base


def _parse_attrs(tag):
    attrs = {}
    for m in re.finditer(r'([:\w-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))', tag):
        name = m.group(1).lower()
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
        if val is None:
            val = ""
        attrs[name] = val
    return attrs


def _find_input_value(html, name):
    matches = []
    for tag in re.findall(r'<input\b[^>]*>', html or "", re.I | re.S):
        attrs = _parse_attrs(tag)
        if attrs.get("name", "").lower() == name.lower():
            val = attrs.get("value")
            if val is not None:
                matches.append(attrs)
    for attrs in matches:
        if attrs.get("type", "").lower() == "hidden":
            return attrs.get("value")
    if matches:
        return matches[0].get("value")
    return None


def _extract_csrf(html):
    candidates = []
    for form in re.findall(r'<form\b[^>]*>.*?</form>', html or "", re.I | re.S):
        m = re.match(r'<form\b[^>]*>', form, re.I | re.S)
        attrs = _parse_attrs(m.group(0)) if m else {}
        action = attrs.get("action", "").lower()
        val = _find_input_value(form, "csrf")
        if val:
            candidates.append((action, val))
    for action, val in candidates:
        if "login" in action:
