            name="login",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = self._safe_json(resp)
                if not isinstance(data, dict) or not data.get("csrf"):
                    resp.failure("login missing csrf")
                    return False
                self._capture_csrf(resp)
                resp.success()
                return True

            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 missing Location")
                    return False
                resp.success()
                location = self._normalize_url(location)
                with self.client.get(
                    location,
                    name="login-location",
                    allow_redirects=False,
                    catch_response=True,
                ) as resp2:
                    if resp2.status_code != 200:
                        resp2.failure("login-location %s" % resp2.status_code)
                        return False
                    data = self._safe_json(resp2)
                    if not isinstance(data, dict) or not data.get("csrf"):
                        resp2.failure("login-location missing csrf")
                        return False
                    self._capture_csrf(resp2)
                    resp2.success()
                    return True

            resp.failure("login unexpected %s" % resp.status_code)
            return False

    def _renew_session(self):
        if not self.csrf:
            return False
        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            name="session-renew",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 201, 204):
                self._capture_csrf(resp)
                resp.success()
                return True
            if resp.status_code == 401:
                err = self._error(resp)
                if err in ("expired", "session"):
                    resp.success()
                    return False
                resp.failure("session-renew 401 %s" % err)
                return False
            resp.failure("session-renew unexpected %s" % resp.status_code)
            return False

    def _recover_cart(self, cart_id):
        if not cart_id:
            return True
        for attempt in range(2):
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            with self.client.post(
                "/v2/carts/%s/recover" % cart_id,
                json={},
                headers=headers,
                name="cart-recover",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if 200 <= resp.status_code < 300:
                    self._capture_csrf(resp)
                    resp.success()
                    return True
                if resp.status_code == 401:
                    err = self._error(resp)
                    if err == "expired" and attempt == 0:
                        resp.success()
                        ok = self._renew_session()
                        if not ok:
                            self._fresh_login()
                        continue
                    if err == "session" and attempt == 0:
                        resp.success()
                        self._fresh_login()
                        continue
                    resp.failure("cart-recover 401 %s" % err)
                    return False
                resp.failure("cart-recover unexpected %s" % resp.status_code)
                return False
        return False

    def _recover(self, err, cart_id):
        if err == "expired":
            ok = self._renew_session()
            if not ok:
                self._fresh_login()
            if cart_id:
                self._recover_cart(cart_id)
        elif err == "session":
            self._fresh_login()
            if cart_id:
                self._recover_cart(cart_id)

    def _get_grant_id(self):
        for attempt in range(2):
            with self.client.get(
                "/v2/challenge-form",
                name="challenge-form",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and attempt == 0:
                        resp.success()
                        self._recover(err, self.cart_id)
                        continue
                    resp.failure("challenge-form 401 %s" % err)
                    return None
                if resp.status_code != 200:
                    resp.failure("challenge-form %s" % resp.status_code)
                    return None
                action, challenge = _extract_challenge(resp.text or "")
                if not action or not challenge:
                    resp.failure("challenge-form missing fields")
                    return None
                resp.success()

            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            with self.client.post(
                self._normalize_url(action),
                json={"challenge": challenge},
                headers=headers,
                name="challenge-submit",
                allow_redirects=False,
                catch_response=True,
            ) as resp2:
                if resp2.status_code == 401:
                    err = self._error(resp2)
                    if err in ("expired", "session") and attempt == 0:
                        resp2.success()
                        self._recover(err, self.cart_id)
                        continue
                    resp2.failure("challenge-submit 401 %s" % err)
                    return None
                if resp2.status_code != 302:
                    resp2.failure("challenge-submit %s" % resp2.status_code)
                    return None
                location = resp2.headers.get("Location")
                if not location:
                    resp2.failure("challenge-submit missing Location")
                    return None
                resp2.success()

            location = self._normalize_url(location)
            with self.client.get(
                location,
                name="challenge-claim",
                allow_redirects=False,
                catch_response=True,
            ) as resp3:
                if resp3.status_code == 401:
                    err = self._error(resp3)
                    if err in ("expired", "session") and attempt == 0:
                        resp3.success()
                        self._recover(err, self.cart_id)
                        continue
                    resp3.failure("challenge-claim 401 %s" % err)
                    return None
                if resp3.status_code != 200:
                    resp3.failure("challenge-claim %s" % resp3.status_code)
                    return None
                data = self._safe_json(resp3)
                grant_id = data.get("grant_id") if isinstance(data, dict) else None
                if grant_id is None or grant_id == "":
                    resp3.failure("challenge-claim missing grant_id")
                    return None
                self._capture_csrf(resp3)
                resp3.success()
                return grant_id
        return None

    def _extract_products(self, data):
        def pick(obj):
            if not isinstance(obj, dict):
                return []
            if isinstance(obj.get("products"), list):
                return obj["products"]
            if isinstance(obj.get("product"), dict):
                return [obj["product"]]
            if "id" in obj and "variants" in obj:
                return [obj]
            return []

        products = pick(data)
        if products:
            return products
        inner = data.get("data") if isinstance(data, dict) else None
        products = pick(inner)
        if products:
            return products
        if isinstance(inner, list):
            return inner
        return []

    def _extract_next(self, data):
        if not isinstance(data, dict):
            return None
        if "next" in data:
            return data.get("next")
        inner = data.get("data")
        if isinstance(inner, dict) and "next" in inner:
            return inner.get("next")
        return None

    def _select_product(self, products):
        for product in products or []:
            if not isinstance(product, dict):
                continue
            product_id = product.get("id")
            if product_id is None:
                continue
            variants = product.get("variants")
            if not isinstance(variants, list):
                continue
            for variant in variants:
                if not isinstance(variant, dict):
                    continue
                in_stock = variant.get("in_stock")
                if in_stock is True or in_stock == 1:
                    variant_id = variant.get("id")
                    if variant_id is not None:
                        return product_id, variant_id
                if isinstance(in_stock, str) and in_stock.lower() == "true":
                    variant_id = variant.get("id")
                    if variant_id is not None:
                        return product_id, variant_id
        return None

    def _catalog_get(self, url, name, fail_if_empty=True, allow_next=True):
        attempts = 0
        while True:
            with self.client.get(
                url,
                name=name,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and attempts < 2:
                        resp.success()
                        self._recover(err, None)
                        attempts += 1
                        continue
                    resp.failure("catalog 401 %s" % err)
                    return None, None, False

                if resp.status_code != 200:
                    resp.failure("catalog %s" % resp.status_code)
                    return None, None, False

                data = self._safe_json(resp)
                selected = self._select_product(self._extract_products(data))
                next_url = self._extract_next(data)

                if selected:
                    resp.success()
                    return selected, next_url, True
                if next_url and allow_next:
                    resp.success()
                    return None, next_url, True
                if fail_if_empty:
                    msg = "too many catalog pages" if next_url else "no in-stock product"
                    resp.failure(msg)
                    return None, None, False
                resp.success()
                return None, next_url, True

    def _get_catalog_product(self):
        selected, next_url, ok = self._catalog_get(
            "/v2/catalog", "catalog", fail_if_empty=False, allow_next=True
        )
        if selected:
            return selected
        if not ok:
            return None

        url = "/v2/catalog/page"
        seen = set()
        for i in range(3):
            selected, next_url, ok = self._catalog_get(
                url,
                "catalog-page-%d" % (i + 1),
                fail_if_empty=True,
                allow_next=(i < 2),
            )
            if selected:
                return selected
            if not ok:
                return None
            if not next_url:
                return None
            next_norm = self._normalize_url(next_url)
            if next_norm in seen:
                return None
            seen.add(next_norm)
            url = next_norm
        return None

    def _create_cart(self, product_id, variant_id):
        grant_id = self._get_grant_id()
        recovery_count = 0
        challenge_retried = False

        while True:
            payload = {"product_id": product_id, "variant_id": variant_id}
            if grant_id is not None:
                payload["grant_id"] = grant_id
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            with self.client.post(
                "/v2/carts",
                json=payload,
                headers=headers,
                name="cart-create",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 201:
                    data = self._safe_json(resp)
                    cart_id = data.get("id") if isinstance(data, dict) else None
                    if cart_id is None or cart_id == "":
                        resp.failure("cart missing id")
                        return None
                    self._capture_csrf(resp)
                    self._capture_etag(resp)
                    self.cart_id = cart_id
                    resp.success()
                    return cart_id

                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and recovery_count < 2:
                        resp.success()
                        had_grant = grant_id is not None
                        self._recover(err, None)
                        if had_grant:
                            new_grant = self._get_grant_id()
                            if new_grant is not None:
                                grant_id = new_grant
                        recovery_count += 1
                        continue
                    resp.failure("cart 401 %s" % err)
                    return None

                if resp.status_code in (400, 403, 422, 428) and not challenge_retried:
                    err = self._error(resp)
                    if err == "denied":
                        resp.failure("cart denied")
                        return None
                    resp.success()
                    challenge_retried = True
                    new_grant = self._get_grant_id()
                    if new_grant is not None:
                        grant_id = new_grant
                    continue

                resp.failure("cart unexpected %s" % resp.status_code)
                return None

    def _refresh_cart(self, cart_id):
        attempts = 0
        while True:
            with self.client.get(
                "/v2/carts/%s" % cart_id,
                name="cart-get",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and attempts < 2:
                        resp.success()
                        self._recover(err, cart_id)
                        attempts += 1
                        continue
                    resp.failure("cart-get 401 %s" % err)
                    return False
                if resp.status_code != 200:
                    resp.failure("cart-get %s" % resp.status_code)
                    return False
                etag = resp.headers.get("ETag") or resp.headers.get("etag")
                if not etag:
                    resp.failure("cart-get missing ETag")
                    return False
                self.cart_etag = etag
                self._capture_csrf(resp)
                resp.success()
                return True

    def _patch_quantity(self, cart_id, quantity):
        recovery_count = 0
        precondition_retried = False
        while True:
            headers = {}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            with self.client.patch(
                "/v2/carts/%s" % cart_id,
                json={"quantity": quantity},
                headers=headers,
                name="cart-patch",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in (200, 201, 204):
                    self._capture_csrf(resp)
                    self._capture_etag(resp)
                    resp.success()
                    return True

                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and recovery_count < 2:
                        resp.success()
                        self._recover(err, cart_id)
                        recovery_count += 1
                        continue
                    resp.failure("cart-patch 401 %s" % err)
                    return False

                if resp.status_code == 412 and not precondition_retried:
                    resp.success()
                    precondition_retried = True
                    if not self._refresh_cart(cart_id):
                        return False
                    continue

                resp.failure("cart-patch unexpected %s" % resp.status_code)
                return False

    def _reserve(self, cart_id):
        recovery_count = 0
        while True:
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            with self.client.post(
                "/v2/reservations",
                json={"cart_id": cart_id},
                headers=headers,
                name="reservation-create",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 202:
                    data = self._safe_json(resp)
                    status_url = data.get("status_url") if isinstance(data, dict) else None
                    if not status_url:
                        resp.failure("reservation missing status_url")
                        return None
                    self._capture_csrf(resp)
                    resp.success()
                    break
                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and recovery_count < 2:
                        resp.success()
                        self._recover(err, cart_id)
                        recovery_count += 1
                        continue
                    resp.failure("reservation 401 %s" % err)
                    return None
                resp.failure("reservation unexpected %s" % resp.status_code)
                return None

        status_url = self._normalize_url(status_url)
        for i in range(5):
            time.sleep(0.05)
            recovery_count = 0
            while True:
                with self.client.get(
                    status_url,
                    name="reservation-status-%d" % (i + 1),
                    allow_redirects=False,
                    catch_response=True,
                ) as resp:
                    if resp.status_code == 401:
                        err = self._error(resp)
                        if err in ("expired", "session") and recovery_count < 2:
                            resp.success()
                            self._recover(err, cart_id)
                            recovery_count += 1
                            continue
                        resp.failure("reservation-status 401 %s" % err)
                        return None

                    if resp.status_code != 200:
                        resp.failure("reservation-status %s" % resp.status_code)
                        return None

                    data = self._safe_json(resp)
                    status = data.get("status") if isinstance(data, dict) else None
                    status = str(status).lower() if status is not None else None

                    if status == "ready":
                        reservation_id = data.get("reservation_id")
                        if reservation_id is None or reservation_id == "":
                            resp.failure("reservation ready missing id")
                            return None
                        self._capture_csrf(resp)
                        resp.success()
                        return reservation_id

                    if status == "failed":
                        resp.failure("reservation failed")
                        return None

                    if status == "pending":
                        if i == 4:
                            resp.failure("reservation pending too long")
                            return None
                        resp.success()
                        break

                    resp.failure("reservation bad status %s" % status)
                    return None
        return None

    def _checkout(self, cart_id, reservation_id):
        idempotency_key = "order-%s-%s" % (cart_id, uuid.uuid4())
        recovery_count = 0
        precondition_retried = False

        while True:
            headers = {"Idempotency-Key": idempotency_key}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            payload = {"cart_id": cart_id, "reservation_id": reservation_id}
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                name="order-create",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 401:
                    err = self._error(resp)
                    if err in ("expired", "session") and recovery_count < 2:
                        resp.success()
                        self._recover(err, cart_id)
                        recovery_count += 1
                        continue
                    resp.failure("order 401 %s" % err)
                    return False

                if resp.status_code in (200, 201):
                    data = self._safe_json(resp)
                    accepted = data.get("accepted") if isinstance(data, dict) else None
                    if accepted is not True:
                        resp.failure("order business failure")
                        return False
                    self._capture_csrf(resp)
                    resp.success()
                    return True

                if resp.status_code == 412 and not precondition_retried:
                    resp.success()
                    precondition_retried = True
                    if not self._refresh_cart(cart_id):
                        return False
                    continue

                resp.failure("order unexpected %s" % resp.status_code)
                return False

    def _journey(self, iteration):
        self.cart_id = None
        self.cart_etag = None

        if not self._fresh_login():
            return

        selected = self._get_catalog_product()
        if not selected:
            return
        product_id, variant_id = selected

        cart_id = self._create_cart(product_id, variant_id)
        if not cart_id:
            return

        if not self._patch_quantity(cart_id, 1):
            return

        reservation_id = self._reserve(cart_id)
        if not reservation_id:
            return

        self._checkout(cart_id, reservation_id)

    @task
    def run_journeys(self):
        try:
            for i in range(ITERATIONS):
                self._journey(i)
        except Exception:
            ShopUser.completed_users += 1
            raise StopUser()
        ShopUser.completed_users += 1
        raise StopUser()


class ShopShape(LoadTestShape):
    start_time = None

    def tick(self):
        if ShopShape.start_time is None:
            ShopShape.start_time = time.time()

        if ShopUser.completed_users >= USERS:
            return None

        if time.time() - ShopShape.start_time > 180:
            return None

        remaining = USERS - ShopUser.completed_users
        if remaining <= 0:
            return None
        return (remaining, remaining)
