import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static String cfg(String key, String def) {
    String[] names = new String[] {
        key,
        key.toUpperCase(),
        key.replace('.', '_'),
        key.replace('.', '_').toUpperCase(),
        "PROFILE_" + key.toUpperCase(),
        "PROFILE_" + key.toUpperCase().replace('.', '_')
    };
    for (String name : names) {
      String v = System.getProperty(name);
      if (v == null) v = System.getenv(name);
      if (v != null && !v.isEmpty()) return v;
    }
    return def;
  }

  private static int cfgInt(String key, int def) {
    try {
      return Integer.parseInt(cfg(key, Integer.toString(def)).trim());
    } catch (Exception e) {
      return def;
    }
  }

  private static double cfgDouble(String key, double def) {
    try {
      return Double.parseDouble(cfg(key, Double.toString(def)).trim());
    } catch (Exception e) {
      return def;
    }
  }

  private static String extractCsrf(String body) {
    if (body == null) return null;

    Matcher m = Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"").matcher(body);
    if (m.find()) return m.group(1);

    m = Pattern.compile("<input[^>]*name=[\"']?csrf[\"']?[^>]*value=[\"']([^\"']+)[\"']",
        Pattern.CASE_INSENSITIVE).matcher(body);
    if (m.find()) return m.group(1);

    m = Pattern.compile("<input[^>]*value=[\"']([^\"']+)[\"'][^>]*name=[\"']?csrf[\"']?",
        Pattern.CASE_INSENSITIVE).matcher(body);
    if (m.find()) return m.group(1);

    return null;
  }

  private static String[] extractProductVariant(String json) {
    if (json == null) return null;

    Pattern productPattern = Pattern.compile(
        "\"id\"\\s*:\\s*(\"([^\"]*)\"|([0-9]+))\\s*,\\s*\"variants\"\\s*:\\s*\\[(.*?)\\]",
        Pattern.DOTALL);
    Matcher pm = productPattern.matcher(json);

    while (pm.find()) {
      String productId = pm.group(2) != null ? pm.group(2) : pm.group(3);
      String variants = pm.group(4);

      Pattern variantPattern = Pattern.compile(
          "\"id\"\\s*:\\s*(\"([^\"]*)\"|([0-9]+))\\s*,\\s*\"in_stock\"\\s*:\\s*(true|false)",
          Pattern.DOTALL);
      Matcher vm = variantPattern.matcher(variants);
      while (vm.find()) {
        String variantId = vm.group(2) != null ? vm.group(2) : vm.group(3);
        boolean inStock = Boolean.parseBoolean(vm.group(4));
        if (inStock) return new String[] { productId, variantId };
      }

      Pattern variantPattern2 = Pattern.compile(
          "\"in_stock\"\\s*:\\s*(true|false)\\s*,\\s*\"id\"\\s*:\\s*(\"([^\"]*)\"|([0-9]+))",
          Pattern.DOTALL);
      Matcher vm2 = variantPattern2.matcher(variants);
      while (vm2.find()) {
        boolean inStock = Boolean.parseBoolean(vm2.group(1));
        String variantId = vm2.group(3) != null ? vm2.group(3) : vm2.group(4);
        if (inStock) return new String[] { productId, variantId };
      }
    }

    return null;
  }

  public ModelSimulation() {
    String baseEnv = System.getenv("BASE_URL");
    final String baseUrl = (baseEnv == null || baseEnv.isEmpty())
        ? "http://127.0.0.1:8000"
        : baseEnv;

    final int users = Math.max(1, cfgInt("users", 2));
    final int iterations = Math.max(1, cfgInt("iterations", 2));
    final int maxPolls = 5;

    double pollInterval = cfgDouble("poll_interval", 0.05);
    long pollIntervalMs = pollInterval > 10.0
        ? Math.round(pollInterval)
        : Math.round(pollInterval * 1000.0);
    final long effectivePollIntervalMs = Math.max(50L, pollIntervalMs);

    HttpProtocolBuilder httpProtocol = http
        .baseUrl(baseUrl)
