    ChainBuilder loginForm = exec(
        http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(status().is(200))
            .check(css("input[name=csrf]", "value").saveAs("csrf"))
    );

    ChainBuilder login = exec(
        http("POST /v2/login")
            .post("/v2/login")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
            .asJson()
            .check(status().in(200, 302).saveAs("loginStatus"))
            .check(header("Location").optional().saveAs("loginLocation"))
            .check(bodyString().saveAs("loginBody"))
    )
    .doIf(session -> session.getInt("loginStatus") == 302).then(
