            .get("#{loginLocation}")
            .check(status().is(200))
            .check(bodyString().saveAs("loginBody"))
        )
    )
    .exec(session -> {
      String csrf = extractCsrf(session.getString("loginBody"));
      if (csrf == null) return session.markAsFailed();
      return session.set("csrf", csrf);
