        .doIf(session -> !session.getBoolean("jobReady")).then(exec(session -> session.markAsFailed()));

    ScenarioBuilder scn = scenario("Reservation")
        .exec(session -> {
          long uid = session.userId();
          return session.set("username", "bench-" + ((uid % 16) + 1));
        })
        .repeat(iterations).on(journey);

    setUp(scn.injectOpen(atOnceUsers(users))).protocols(httpProtocol);
  }
}
