```javascript
import http from 'k6/http';
import { sleep, check } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

const profiles = [
  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true }
];

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s'
    }
  },
  thresholds: {
    checks: ['rate==1']
  }
};

function params(headers) {
  return { redirects: 0, headers: headers || {} };
}

function parseJson(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const target = name.toLowerCase();
  for (const k in res.headers) {
    if (Object.prototype.hasOwnProperty.call(res.headers, k) && k.toLowerCase() === target) {
      return res.headers[k];
    }
  }
  return null;
}

function updateCsrf(state, res) {
  const data = parseJson(res);
  if (data) {
    if (data.csrf) state.csrf = data.csrf;
    else if (data.data && data.data.csrf) state.csrf = data.data.csrf;
  }
  return data;
}

function errorCode(res) {
  const data = parseJson(res);
  if (!data) return null;
  if (data.error) return data.error;
  if (data.data && data.data.error) return data.data.error;
  return null;
}

function resolveUrl(url, base) {
  if (!url) return url;
  if (/^https?:\/\//i.test(url)) return url;
  const b = base || BASE_URL;
  if (url.charAt(0) === '/') return BASE_URL + url;
  if (url.charAt(0) === '?') {
    const q = b.indexOf('?');
    return (q === -1 ? b : b.substring(0, q)) + url;
  }
  const schemeIdx = b.indexOf('://');
  if (schemeIdx !== -1) {
    const pathStart = b.indexOf('/', schemeIdx + 3);
    if (pathStart === -1) return b + '/' + url;
    const lastSlash = b.lastIndexOf('/');
    if (lastSlash < pathStart) return b + '/' + url;
    return b.substring(0, lastSlash + 1) + url;
  }
  return BASE_URL + '/' + url;
}

function parseAttrs(tag) {
  const attrs = {};
  tag = tag.replace(/\/\s*>$/, '>');
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(tag)) !== null) {
    const name = m[1].toLowerCase();
    let value = '';
    if (m[2] !== undefined) value = m[2];
    else if (m[3] !== undefined) value = m[3];
    else if (m[4] !== undefined) value = m[4];
    if (!(name in attrs)) attrs[name] = value;
  }
  return attrs;
}

function extractInputValue(body, inputName) {
  if (!body) return null;
  const tags = body.match(/<input\b[^>]*>/gi) || [];
  const target = inputName.toLowerCase();
  let first = null;
  let fallback = null;
  for (let i = 0; i < tags.length; i++) {
    const attrs = parseAttrs(tags[i]);
    if (attrs.name && attrs.name.toLowerCase() === target) {
      if (attrs.disabled !== undefined) continue;
      const v = attrs.value !== undefined ? attrs.value : '';
      if (first === null) first = v;
      const type = (attrs.type || '').toLowerCase();
      if (type === 'hidden') return v;
      if (fallback === null) fallback = v;
    }
  }
  if (fallback !== null) return fallback;
  return first;
}

function extractCsrfFromLogin(body) {
  if (!body) return null;
  const forms = body.match(/<form\b[^>]*>[\s\S]*?<\/form>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const open = forms[i].match(/<form\b[^>]*>/i);
    if (!open) continue;
    const attrs = parseAttrs(open[0]);
    const action = (attrs.action || '').toLowerCase();
    if (action.indexOf('/v2/login') !== -1) {
      const v = extractInputValue(forms[i], 'csrf');
      if (v) return v;
    }
  }
  for (let i = 0; i < forms.length; i++) {
    const v = extractInputValue(forms[i], 'csrf');
    if (v) return v;
  }
  return extractInputValue(body, 'csrf');
}

function extractFormAction(body) {
  if (!body) return null;
  const forms = body.match(/<form\b[^>]*>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const attrs = parseAttrs(forms[i]);
    if (attrs.action) return attrs.action;
  }
  return null;
}

function login(state) {
  state.csrf = null;
  const formRes = http.get(BASE_URL + '/v2/login-form', params());
  check(formRes, { 'login form loaded': r => r.status === 200 });
  if (formRes.status !== 200) return false;

  const csrf = extractCsrfFromLogin(formRes.body);
  check(csrf, { 'login csrf extracted': v => !!v });
  if (!csrf) return false;

  const loginRes = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({ username: state.username, password: 'bench', csrf: csrf }),
    params({ 'Content-Type': 'application/json' })
  );

  let finalRes = loginRes;
  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loc, { 'login redirect location': v => !!v });
    if (!loc) return false;
    finalRes = http.get(resolveUrl(loc, BASE_URL + '/v2/login'), params());
  }

  updateCsrf(state, finalRes);
  const ok = (finalRes.status === 200 || loginRes.status === 200) && !!state.csrf;
  check(finalRes, { 'login completed': r => (r.status === 200 || loginRes.status === 200) && !!state.csrf });
  return ok;
}

function renewSession(state) {
  if (!state.csrf) return false;
  const res = http.post(
    BASE_URL + '/v2/session/renew',
    '{}',
    params({ 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf })
  );
  if (res.status === 200) {
    updateCsrf(state, res);
    return !!state.csrf;
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId || !state.csrf) return false;
  const res = http.post(
    BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover',
    '{}',
    params({ 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf })
  );
  if (res.status >= 200 && res.status < 300) {
    updateCsrf(state, res);
    const et = getHeader(res, 'ETag');
    if (et) state.cartETag = et;
    return true;
  }
  return false;
}

function withAuthRetry(state, doRequest, opts) {
  let res = doRequest();
  if (res.status !== 401) return res;

  const code = errorCode(res);
  if (code === 'denied') return res;

  if (code === 'expired') {
    if (!renewSession(state)) return res;
  } else if (code === 'session') {
    if (!login(state)) return res;
  } else {
    return res;
  }

  if (state.cartId && (!opts || opts.recoverCart !== false)) {
    recoverCart(state);
  }

  return doRequest();
}

function collectProducts(data) {
  const out = [];
  if (!data) return out;
  if (data.data && Array.isArray(data.data.products)) out.push.apply(out, data.data.products);
  if (data.product) out.push(data.product);
  if (data.data && data.data.product) out.push(data.data.product);
  if (Array.isArray(data.products)) out.push.apply(out, data.products);
  if (data.data && Array.isArray(data.data.items)) out.push.apply(out, data.data.items);
  return out;
}

function getNext(data) {
  if (!data) return null;
  if (data.next !== undefined) return data.next;
  if (data.data && data.data.next !== undefined) return data.data.next;
  return null;
}

function fetchProductVariant() {
  let url = BASE_URL + '/v2/catalog';
  let pages = 0;

  while (url && pages < 3) {
    const res = http.get(url, params());
    check(res, { 'catalog loaded': r => r.status === 200 });
    if (res.status !== 200) return null;

    const data = parseJson(res);
    const products = collectProducts(data);

    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      if (!p || !p.variants) continue;
      for (let j = 0; j < p.variants.length; j++) {
        const v = p.variants[j];
        const inStock = v && (
          v.in_stock === true ||
          v.in_stock === 1 ||
          v.in_stock === 'true' ||
          v.in_stock === '1'
        );
        if (inStock && p.id !== undefined && v.id !== undefined) {
          return { product_id: p.id, variant_id: v.id };
        }
      }
    }

    const next = getNext(data);
    pages++;
    if (next) url = resolveUrl(next, url);
    else url = null;
  }

  return null;
}

function getGrant(state) {
  if (!state.csrf) return null;

  const formRes = withAuthRetry(
    state,
    () => http.get(BASE_URL + '/v2/challenge-form', params()),
    { recoverCart: false }
  );
  if (formRes.status !== 200) return null;

  const action = extractFormAction(formRes.body);
  const challenge = extractInputValue(formRes.body, 'challenge');
  if (!action || !challenge) return null;

  const actionUrl = resolveUrl(action, BASE_URL + '/v2/challenge-form');
  const challengeRes = withAuthRetry(
    state,
    () => http.post(
      actionUrl,
      JSON.stringify({ challenge: challenge }),
      params({ 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf })
    ),
    { recoverCart: false }
  );
  if (challengeRes.status !== 302) return null;

  const loc = getHeader(challengeRes, 'Location');
  if (!loc) return null;

  const grantRes = http.get(resolveUrl(loc, actionUrl), params());
  if (grantRes.status !== 200) return null;

  const data = updateCsrf(state, grantRes);
  if (data && data.grant_id) return data.grant_id;
  return null;
}

function createCart(state, pv, grantId) {
  const body = {
    product_id: pv.product_id,
    variant_id: pv.variant_id
  };
  if (grantId) body.grant_id = grantId;

  const doPost = () => http.post(
    BASE_URL + '/v2/carts',
    JSON.stringify(body),
    params({ 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf })
  );

  const res = withAuthRetry(state, doPost, { recoverCart: false });
  updateCsrf(state, res);

  if (res.status !== 201) return null;

  const data = parseJson(res);
  if (!data || !data.id) return null;

  state.cartId = data.id;
  state.cartETag = getHeader(res, 'ETag') || state.cartETag;
  state.idempotencyKey = 'cart-' + state.cartId + '-' + Date.now() + '-' + Math.random();
  return data;
}

function patchCartQuantity(state, quantity) {
  const doPatch = () => {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    };
    if (state.cartETag) headers['If-Match'] = state.cartETag;
    return http.patch(
      BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId),
      JSON.stringify({ quantity: quantity }),
      params(headers)
    );
  };

  let res = withAuthRetry(state, doPatch, { recoverCart: true });
  updateCsrf(state, res);

  if (res.status === 412) {
    const getRes = withAuthRetry(
      state,
      () => http.get(BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId), params()),
      { recoverCart: true }
    );
    const et = getHeader(getRes, 'ETag');
    if (et) state.cartETag = et;
    updateCsrf(state, getRes);

    res = withAuthRetry(state, doPatch, { recoverCart: true });
    updateCsrf(state, res);
  }

  const finalEt = getHeader(res, 'ETag');
  if (finalEt) state.cartETag = finalEt;
  return res;
}

function refreshCartETag(state) {
  if (!state.cartId) return null;

  const res = withAuthRetry(
    state,
    () => http.get(BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId), params()),
    { recoverCart: true }
  );

  updateCsrf(state, res);
  if (res.status === 200) {
    const et = getHeader(res, 'ETag');
    if (et) state.cartETag = et;
  }
  return res;
}

function createReservation(state) {
  const doPost = () => http.post(
    BASE_URL + '/v2/reservations',
    JSON.stringify({ cart_id: state.cartId }),
    params({ 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf })
  );

  const res = withAuthRetry(state, doPost, { recoverCart: true });
  updateCsrf(state, res);

  if (res.status !== 202) return null;

  const data = parseJson(res);
  if (!data || !data.status_url) return null;

  state.jobStatusUrl = data.status_url;
  return { status_url: data.status_url, csrf: data.csrf };
}

function getJobStatus(data) {
  if (!data) return null;
  if (data.status !== undefined) return String(data.status).toLowerCase();
  if (data.data && data.data.status !== undefined) return String(data.data.status).toLowerCase();
  if (data.job && data.job.status !== undefined) return String(data.job.status).toLowerCase();
  return null;
}

function getReservationId(data) {
  if (!data) return null;
  if (data.reservation_id) return data.reservation_id;
  if (data.data && data.data.reservation_id) return data.data.reservation_id;
  if (data.job && data.job.reservation_id) return data.job.reservation_id;
  return null;
}

function pollReservation(state, statusUrl, profile) {
  const interval = Math.max(Number(profile.poll_interval || 0.05), 0.05);
  const maxPolls = Math.max(1, Math.min(Number(profile.job_polls || 5), 5));
  const pollUrl = resolveUrl(statusUrl, BASE_URL + '/v2/reservations');

  for (let i = 0; i < maxPolls; i++) {
    if (i > 0) sleep(interval);

    const res = withAuthRetry(
      state,
      () => http.get(pollUrl, params()),
      { recoverCart: true }
    );
    updateCsrf(state, res);

    if (res.status !== 200 && res.status !== 202) return null;

    const data = parseJson(res);
    if (!data) return null;

    const status = getJobStatus(data);
    if (status === 'ready') {
      const rid = getReservationId(data);
      if (rid) {
        state.reservationId = rid;
        return rid;
      }
      return null;
    }
    if (status === 'failed') return null;
    if (status !== 'pending') return null;
  }

  return null;
}

function placeOrder(state) {
  if (!state.reservationId || !state.cartId) return null;

  refreshCartETag(state);

  if (!state.idempotencyKey) {
    state.idempotencyKey = 'cart-' + state.cartId + '-' + Date.now() + '-' + Math.random();
  }

  const doPost = () => {
    const headers = {
      'Content-Type': 'application/json',
      'Idempotency-Key': state.idempotencyKey,
      'X-CSRF-Token': state.csrf
    };
    if (state.cartETag) headers['If-Match'] = state.cartETag;

    return http.post(
      BASE_URL + '/v2/orders',
      JSON.stringify({
        cart_id: state.cartId,
        reservation_id: state.reservationId
      }),
      params(headers)
    );
  };

  let res = withAuthRetry(state, doPost, { recoverCart: true });
  updateCsrf(state, res);

  if (res.status === 412) {
    refreshCartETag(state);
    res = withAuthRetry(state, doPost, { recoverCart: true });
    updateCsrf(state, res);
  }

  return res;
}

export default function () {
  const username = 'bench-' + (((__VU - 1) % 16) + 1);
  const profile = profiles[((__VU - 1) % profiles.length)] || profiles[0];

  http.cookieJar().clear(BASE_URL);

  const state = {
    username: username,
    csrf: null,
    cartId: null,
    cartETag: null,
    reservationId: null,
    idempotencyKey: null,
    jobStatusUrl: null
  };

  const loggedIn = login(state);
  if (!loggedIn) return;

  const pv = fetchProductVariant();
  check(pv, { 'in-stock product found': v => !!v });
  if (!pv) return;

  const grantId = getGrant(state);
  const cart = createCart(state, pv, grantId);
  check(cart, { 'cart created': c => !!c && !!c.id });
  if (!cart) return;

  const patchRes = patchCartQuantity(state, 1);
  check(patchRes, { 'cart quantity set': r => !!r && (r.status === 200 || r.status === 204) });

  refreshCartETag(state);

  const reservation = createReservation(state);
  check(reservation, { 'reservation job created': r => !!r && !!r.status_url });
  if (!reservation) return;

  const reservationId = pollReservation(state, reservation.status_url, profile);
  check(reservationId, { 'reservation ready': id => !!id });
  if (!reservationId) return;

  const orderRes = placeOrder(state);
  check(orderRes, {
    'order accepted 201': r => {
      if (!r || r.status !== 201) return false;
      const d = parseJson(r);
      return !!d && d.accepted === true;
    }
  });
}
