import os
import time
import itertools
from html.parser import HTMLParser
from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inputs = []
        self.forms = []

    def handle_starttag(self, tag, attrs):
        attrs_dict = {k.lower(): v for k, v in attrs}
        if tag.lower() == "form":
            self.forms.append(attrs_dict)
        elif tag.lower() == "input":
            self.inputs.append(attrs_dict)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def parse_html(html):
    parser = FormParser()
    parser.feed(html)
    return parser


def get_input_value(parser, name):
    name_lower = name.lower()
    for inp in parser.inputs:
        if inp.get("name", "").lower() == name_lower:
            return inp.get("value")
    return None


def get_form_action(parser, contains):
    for form in parser.forms:
        action = form.get("action", "")
        if contains in action:
            return action
    return None


class ShopUser(HttpUser):
    wait_time = between(0, 0)
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    _counter = itertools.count()

    def on_start(self):
        idx = next(ShopUser._counter)
        self.username = f"bench-{idx % 16 + 1}"
        self.password = "bench"
        self.csrf = None

    def _authed_request(self, method, url, expected, json=None, headers=None,
                        cart_id=None, idempotency_key=None, if_match=None):
        h = {}
        if headers:
            h.update(headers)
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if if_match:
            h["If-Match"] = if_match
        if idempotency_key:
            h["Idempotency-Key"] = idempotency_key

        resp = self.client.request(
            method, url, json=json, headers=h, allow_redirects=False,
            catch_response=True
        )
        if resp.status_code == 401:
            try:
                data = resp.json()
            except Exception:
                data = {}
            error = data.get("error")
            if error in ("expired", "session"):
                recovered = False
                if error == "expired":
                    recovered = self.renew()
                else:
                    recovered = self.fresh_login()
                if recovered:
                    resp.success()
                    if cart_id:
                        self.recover_cart(cart_id)
                    h["X-CSRF-Token"] = self.csrf
                    resp = self.client.request(
                        method, url, json=json, headers=h,
                        allow_redirects=False, catch_response=True
                    )
                else:
                    resp.failure(f"401 {error} recovery failed")
                    raise StopUser()
            elif error == "denied":
                resp.failure("401 denied")
                raise StopUser()
            else:
                resp.failure(f"401 {error}")
                raise StopUser()

        if resp.status_code not in expected:
            resp.failure(f"{method} {url} -> {resp.status_code}: {resp.text[:200]}")
            raise StopUser()
        return resp

    def renew(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        resp = self.client.post(
            "/v2/session/renew", json={}, headers=headers,
            allow_redirects=False, catch_response=True
        )
        if resp.status_code != 200:
            resp.failure(f"renew -> {resp.status_code}")
            return False
        try:
            data = resp.json()
        except Exception:
            resp.failure("renew invalid json")
            return False
        self.csrf = data.get("csrf", self.csrf)
        resp.success()
        return True

    def fresh_login(self):
        try:
            self.login()
            return True
        except StopUser:
            return False

    def recover_cart(self, cart_id):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        resp = self.client.post(
            f"/v2/carts/{cart_id}/recover", json={}, headers=headers,
            allow_redirects=False, catch_response=True
        )
        if resp.status_code != 200:
            resp.failure(f"cart recover -> {resp.status_code}")
            return False
        try:
            data = resp.json()
        except Exception:
            data = {}
        self.csrf = data.get("csrf", self.csrf)
        resp.success()
        return True

    def login(self):
        resp = self.client.get(
            "/v2/login-form", allow_redirects=False, catch_response=True
        )
        if resp.status_code != 200:
            resp.failure(f"login-form -> {resp.status_code}")
            raise StopUser()
        parser = parse_html(resp.text)
        csrf = get_input_value(parser, "csrf")
        if not csrf:
            resp.failure("csrf missing")
            raise StopUser()
        resp.success()

        payload = {"username": self.username, "password": self.password, "csrf": csrf}
        resp = self.client.post(
            "/v2/login", json=payload, allow_redirects=False, catch_response=True
        )
        if resp.status_code == 302:
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("302 missing Location")
                raise StopUser()
            resp.success()
            resp2 = self.client.get(
                loc, allow_redirects=False, catch_response=True
            )
            if resp2.status_code != 200:
                resp2.failure(f"login redirect -> {resp2.status_code}")
                raise StopUser()
            try:
                data = resp2.json()
            except Exception:
                resp2.failure("login redirect invalid json")
                raise StopUser()
            self.csrf = data.get("csrf", csrf)
            resp2.success()
        elif resp.status_code == 200:
            try:
                data = resp.json()
            except Exception:
                resp.failure("login invalid json")
                raise StopUser()
            self.csrf = data.get("csrf", csrf)
            resp.success()
        else:
            resp.failure(f"login -> {resp.status_code}")
            raise StopUser()

    def _find_in_stock(self, data):
