            if attempt > 0:
                time.sleep(interval)
            resp = self.client.get(
                status_url, allow_redirects=False, catch_response=True
            )

            if resp.status_code == 401:
                try:
                    data = resp.json()
                except Exception:
                    data = {}
                error = data.get("error")
                if error in ("expired", "session"):
                    recovered = False
                    if error == "expired":
                        recovered = self.renew()
                    else:
                        recovered = self.fresh_login()
                    if recovered:
                        resp.success()
                        if cart_id:
                            self.recover_cart(cart_id)
                        resp = self.client.get(
                            status_url, allow_redirects=False,
                            catch_response=True
                        )
                    else:
                        resp.failure(f"poll 401 {error} recovery failed")
                        raise StopUser()
                else:
                    resp.failure(f"poll 401 {error}")
                    raise StopUser()

            if resp.status_code not in (200, 202):
                resp.failure(f"status poll -> {resp.status_code}")
                raise StopUser()
            try:
                data = resp.json()
            except Exception:
                resp.failure("status poll invalid json")
                raise StopUser()

            status = data.get("status")
            if status == "ready":
                reservation_id = data.get("reservation_id")
                if not reservation_id:
                    res_obj = data.get("reservation")
                    if isinstance(res_obj, dict):
                        reservation_id = res_obj.get("id")
                if not reservation_id:
                    resp.failure("ready but no reservation_id")
                    raise StopUser()
                self.csrf = data.get("csrf", self.csrf)
                resp.success()
                return reservation_id
            elif status == "failed":
                resp.failure("reservation job failed")
                raise StopUser()
            elif status in ("pending", "processing", "queued"):
                if attempt == 4:
                    resp.failure("reservation not ready after 5 polls")
                    raise StopUser()
                resp.success()
                continue
            else:
                resp.failure(f"unknown reservation status: {status}")
                raise StopUser()

        raise StopUser()

    def checkout(self, cart_id, reservation_id, etag):
        payload = {"cart_id": cart_id, "reservation_id": reservation_id}
        idem = f"cart-{cart_id}-order"
        resp = self._authed_request(
            "POST", "/v2/orders", {200, 201}, json=payload,
