                raise StopUser()
            if data.get("accepted") is False:
                resp.failure("order business failure accepted:false")
                raise StopUser()
            if data.get("accepted") is True:
                self.csrf = data.get("csrf", self.csrf)
                resp.success()
                return
            resp.failure("order 200 without accepted")
            raise StopUser()
        if resp.status_code != 201:
            resp.failure(f"order -> {resp.status_code}")
            raise StopUser()
        try:
            data = resp.json()
        except Exception:
            resp.failure("order invalid json")
            raise StopUser()
        if not data.get("accepted"):
            resp.failure("order not accepted")
            raise StopUser()
        self.csrf = data.get("csrf", self.csrf)
        resp.success()

    def journey(self):
        self.login()
        product_id, variant_id = self.get_product()
        grant_id = self.get_grant_id()
        cart_id, etag = self.create_cart(product_id, variant_id, grant_id)
        etag = self.patch_cart(cart_id, etag)
        status_url = self.create_reservation(cart_id)
        reservation_id = self.poll_reservation(status_url, cart_id)
        self.checkout(cart_id, reservation_id, etag)

    @task
    def run_iterations(self):
        try:
            for _ in range(2):
                self.journey()
        except StopUser:
            raise
        except Exception:
            raise StopUser()
        raise StopUser()


class ReservationShape(LoadTestShape):
    def tick(self):
