import os
import json
import time
import itertools
from html.parser import HTMLParser

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser


# ---------------------------------------------------------------------------
# HTML helpers (tolerant to attribute variants / decoys)
# ---------------------------------------------------------------------------
class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inputs = []
        self.forms = []

    def handle_starttag(self, tag, attrs):
        d = {k.lower(): (v if v is not None else "") for k, v in attrs}
        t = tag.lower()
        if t == "form":
            self.forms.append(d)
        elif t == "input":
            self.inputs.append(d)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def parse_html(html):
    p = _FormParser()
    try:
        p.feed(html or "")
    except Exception:
        pass
    return p


def get_input_value(parser, name):
    target = name.lower()
    for inp in parser.inputs:
        if inp.get("name", "").lower() == target:
            return inp.get("value")
    return None


def get_form_action(parser, needle):
    for form in parser.forms:
        action = form.get("action", "")
        if needle in action:
            return action
    return None


def safe_json(text):
    try:
        return json.loads(text)
    except Exception:
        return None


# ---------------------------------------------------------------------------
# User
# ---------------------------------------------------------------------------
class ShopUser(HttpUser):
    wait_time = between(0, 0)
    network_timeout = 5.0
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    TOTAL_JOURNEYS = 4            # 2 users * 2 iterations
    ITERATIONS_PER_USER = 2

    account_counter = itertools.count()
    journeys_started = 0
    journeys_completed = 0

    def on_start(self):
        idx = next(ShopUser.account_counter)
        self.username = "bench-%d" % (idx % 16 + 1)
        self.password = "bench"
        self.csrf = None

    # ------------------------------------------------------------------ csrf
    def _set_csrf_from(self, text, fallback):
        data = safe_json(text)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        else:
            self.csrf = fallback

    # --------------------------------------------------------------- login
    def login(self):
        r = self.client.get("/v2/login-form", allow_redirects=False, catch_response=True)
        if r.status_code != 200:
            r.failure("login-form -> %s" % r.status_code)
            raise StopUser()
        csrf = get_input_value(parse_html(r.text), "csrf")
        if not csrf:
            r.failure("login-form missing csrf")
            raise StopUser()
        r.success()

        payload = {"username": self.username, "password": self.password, "csrf": csrf}
        r = self.client.post("/v2/login", json=payload, allow_redirects=False, catch_response=True)

        if r.status_code == 302:
            loc = r.headers.get("Location")
            if not loc:
                r.failure("login 302 without Location")
                raise StopUser()
            r.success()
            r2 = self.client.get(loc, allow_redirects=False, catch_response=True)
            if r2.status_code != 200:
                r2.failure("login redirect -> %s" % r2.status_code)
                raise StopUser()
            self._set_csrf_from(r2.text, csrf)
            r2.success()
        elif r.status_code == 200:
            self._set_csrf_from(r.text, csrf)
            r.success()
        else:
            r.failure("login -> %s" % r.status_code)
            raise StopUser()

    # --------------------------------------------------- recovery primitives
    def renew(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        r = self.client.post("/v2/session/renew", json={}, headers=headers,
                             allow_redirects=False, catch_response=True)
        if r.status_code != 200:
            r.failure("session/renew -> %s" % r.status_code)
            return False
        data = safe_json(r.text) or {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        r.success()
        return True

    def fresh_login(self):
        try:
            self.login()
            return True
        except StopUser:
            return False

    def recover_cart(self, cart_id):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        r = self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                             headers=headers, allow_redirects=False, catch_response=True)
        if r.status_code != 200:
            r.failure("cart recover -> %s" % r.status_code)
            return False
        data = safe_json(r.text) or {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        r.success()
        return True

    # ------------------------------------------------------ authed request
    def _authed(self, method, url, expected, json_body=None, cart_id=None,
                idempotency_key=None, if_match=None):
        def fire():
            h = {}
            if self.csrf:
                h["X-CSRF-Token"] = self.csrf
            if if_match:
                h["If-Match"] = if_match
            if idempotency_key:
                h["Idempotency-Key"] = idempotency_key
            return self.client.request(method, url, json=json_body, headers=h,
                                       allow_redirects=False, catch_response=True)

        resp = fire()

        if resp.status_code == 401:
            err = (safe_json(resp.text) or {}).get("error")
            if err in ("expired", "session"):
                resp.success()  # expected expiry, already recovered below
                ok = self.renew() if err == "expired" else self.fresh_login()
                if not ok:
                    raise StopUser()
                if cart_id:
                    self.recover_cart(cart_id)
                resp = fire()
            elif err == "denied":
                resp.failure("401 denied")
                raise StopUser()
            else:
                resp.failure("401 %s" % err)
                raise StopUser()

        if resp.status_code not in expected:
            resp.failure("%s %s -> %s" % (method, url, resp.status_code))
            raise StopUser()
        return resp

    # ---------------------------------------------------------- catalog
    def _find_in_stock(self, data):
        if not isinstance(data, dict):
            return None
        products = None
        inner = data.get("data")
        if isinstance(inner, dict) and isinstance(inner.get("products"), list):
            products = inner["products"]
        elif isinstance(data.get("products"), list):
            products = data["products"]
        if products:
            for p in products:
                for v in p.get("variants", []):
                    if v.get("in_stock"):
                        return (p.get("id"), v.get("id"))
        for path in (("product",), ("data", "product")):
            node = data
            for k in path:
                node = node.get(k) if isinstance(node, dict) else None
            if isinstance(node, dict):
                for v in node.get("variants", []):
                    if v.get("in_stock"):
                        return (node.get("id"), v.get("id"))
        return None

    def get_product(self):
        r = self.client.get("/v2/catalog", allow_redirects=False, catch_response=True)
        if r.status_code != 200:
            r.failure("catalog -> %s" % r.status_code)
            raise StopUser()
        data = safe_json(r.text) or {}
        found = self._find_in_stock(data)
        if found:
            r.success()
            return found
        r.success()

        url = "/v2/catalog/page"
        for _ in range(3):
            if not url:
                break
            pr = self.client.get(url, allow_redirects=False, catch_response=True)
            if pr.status_code != 200:
                pr.failure("catalog/page -> %s" % pr.status_code)
                raise StopUser()
            pdata = safe_json(pr.text) or {}
            found = self._find_in_stock(pdata)
            if found:
                pr.success()
                return found
            pr.success()
            nxt = pdata.get("next")
            url = nxt if nxt else None

        # no in-stock product found anywhere
        fr = self.client.get("/v2/catalog", allow_redirects=False, catch_response=True)
        fr.failure("no in-stock product found")
        raise StopUser()

    # -------------------------------------------------------- challenge
    def get_grant_id(self):
        r = self.client.get("/v2/challenge-form", allow_redirects=False, catch_response=True)
        if r.status_code == 404:
            r.success()
            return None
        if r.status_code != 200:
            r.failure("challenge-form -> %s" % r.status_code)
            raise StopUser()
        parser = parse_html(r.text)
        action = get_form_action(parser, "/v2/challenges/")
        challenge = get_input_value(parser, "challenge")
        if not action or not challenge:
            r.failure("challenge form incomplete")
            raise StopUser()
        r.success()

        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        r2 = self.client.post(action, json={"challenge": challenge}, headers=headers,
                              allow_redirects=False, catch_response=True)
        if r2.status_code != 302:
            r2.failure("challenge POST -> %s" % r2.status_code)
            raise StopUser()
        loc = r2.headers.get("Location")
        if not loc:
            r2.failure("challenge 302 without Location")
            raise StopUser()
        r2.success()

        r3 = self.client.get(loc, allow_redirects=False, catch_response=True)
        if r3.status_code != 200:
            r3.failure("challenge GET -> %s" % r3.status_code)
            raise StopUser()
        data = safe_json(r3.text) or {}
        grant_id = data.get("grant_id")
        if not grant_id:
            r3.failure("grant_id missing")
            raise StopUser()
        if data.get("csrf"):
            self.csrf = data["csrf"]
        r3.success()
        return grant_id

    # ------------------------------------------------------------- cart
    def create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        resp = self._authed("POST", "/v2/carts", {201}, json_body=payload)
        data = safe_json(resp.text) or {}
        cart_id = data.get("id")
        if not cart_id:
            resp.failure("cart id missing")
            raise StopUser()
        if data.get("csrf"):
            self.csrf = data["csrf"]
        etag = resp.headers.get("ETag") or resp.headers.get("Etag")
        resp.success()
        return cart_id, etag

    def patch_cart(self, cart_id, etag):
        g = self.client.get("/v2/carts/%s" % cart_id, allow_redirects=False, catch_response=True)
        if g.status_code != 200:
            g.failure("cart GET -> %s" % g.status_code)
            raise StopUser()
        etag = g.headers.get("ETag") or etag
        g.success()

        payload = {"quantity": 1}
        resp = self._authed("PATCH", "/v2/carts/%s" % cart_id, {200, 204, 412},
                            json_body=payload, cart_id=cart_id, if_match=etag)
        if resp.status_code == 412:
            resp.success()
            g2 = self.client.get("/v2/carts/%s" % cart_id, allow_redirects=False,
                                 catch_response=True)
            if g2.status_code != 200:
                g2.failure("cart re-read -> %s" % g2.status_code)
                raise StopUser()
            new_etag = g2.headers.get("ETag") or etag
            g2.success()
            resp = self._authed("PATCH", "/v2/carts/%s" % cart_id, {200, 204},
                                json_body=payload, cart_id=cart_id, if_match=new_etag)

        if resp.status_code not in (200, 204):
            resp.failure("cart PATCH -> %s" % resp.status_code)
            raise StopUser()
        data = safe_json(resp.text) or {}
        if data.get("csrf"):
            self.csrf = data["csrf"]
        new_etag = resp.headers.get("ETag") or etag
        resp.success()
        return new_etag

    # -------------------------------------------------------- reservations
    def create_reservation(self, cart_id):
        resp = self._authed("POST", "/v2/reservations", {202},
                            json_body={"cart_id": cart_id}, cart_id=cart_id)
        data = safe_json(resp.text) or {}
        status_url = data.get("status_url")
        if not status_url:
            resp.failure("status_url missing")
            raise StopUser()
        if data.get("csrf"):
            self.csrf = data["csrf"]
        resp.success()
        return status_url

    def poll_reservation(self, status_url, cart_id):
        # >= 50ms apart; at most 5 polls
        interval = 0.06
        for attempt in range(5):
            if attempt > 0:
                time.sleep(interval)

            resp = self.client.get(status_url, allow_redirects=False, catch_response=True)

            if resp.status_code == 401:
                err = (safe_json(resp.text) or {}).get("error")
                if err in ("expired", "session"):
                    resp.success()
                    ok = self.renew() if err == "expired" else self.fresh_login()
                    if not ok:
                        raise StopUser()
                    if cart_id:
                        self.recover_cart(cart_id)
                    resp = self.client.get(status_url, allow_redirects=False,
                                           catch_response=True)
                elif err == "denied":
                    resp.failure("401 denied")
                    raise StopUser()
                else:
                    resp.failure("401 %s" % err)
                    raise StopUser()

            if resp.status_code not in (200, 202):
                resp.failure("status poll -> %s" % resp.status_code)
                raise StopUser()

            data = safe_json(resp.text) or {}
            status = data.get("status")

            if status == "ready":
                rid = data.get("reservation_id")
                if not rid:
                    res_obj = data.get("reservation")
                    if isinstance(res_obj, dict):
                        rid = res_obj.get("id")
                if not rid:
                    resp.failure("ready without reservation_id")
                    raise StopUser()
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                resp.success()
                return rid

            if status in ("failed", "rejected", "error", "cancelled"):
                resp.failure("reservation job %s" % status)
                return None  # expected negative control outcome

            if status in ("pending", "processing", "queued"):
                if attempt == 4:
                    resp.failure("reservation not ready after 5 polls")
                    return None
                resp.success()
                continue

            resp.failure("unknown reservation status: %s" % status)
            raise StopUser()

        return None

    # ------------------------------------------------------------ orders
    def checkout(self, cart_id, reservation_id, etag):
        payload = {"cart_id": cart_id, "reservation_id": reservation_id}
        idem = "cart-%s-order" % cart_id
        resp = self._authed("POST", "/v2/orders", {200, 201, 412}, json_body=payload,
                            cart_id=cart_id, idempotency_key=idem, if_match=etag)

        if resp.status_code == 412:
            resp.success()
            g = self.client.get("/v2/carts/%s" % cart_id, allow_redirects=False,
                                catch_response=True)
            if g.status_code != 200:
                g.failure("cart re-read -> %s" % g.status_code)
                raise StopUser()
            new_etag = g.headers.get("ETag") or etag
            g.success()
            resp = self._authed("POST", "/v2/orders", {200, 201}, json_body=payload,
                                cart_id=cart_id, idempotency_key=idem, if_match=new_etag)

        data = safe_json(resp.text) or {}
        if resp.status_code == 200:
            if data.get("accepted") is False:
                resp.failure("order accepted:false")
                raise StopUser()
            if data.get("accepted") is not True:
                resp.failure("order 200 without accepted")
                raise StopUser()
            if data.get("csrf"):
                self.csrf = data["csrf"]
            resp.success()
            return
        if resp.status_code == 201:
            if data.get("accepted") is not True:
                resp.failure("order 201 not accepted")
                raise StopUser()
            if data.get("csrf"):
                self.csrf = data["csrf"]
            resp.success()
            return
        resp.failure("order -> %s" % resp.status_code)
        raise StopUser()

    # ----------------------------------------------------------- journey
    def journey(self):
        self.login()
        product_id, variant_id = self.get_product()
        grant_id = self.get_grant_id()
        cart_id, etag = self.create_cart(product_id, variant_id, grant_id)
        etag = self.patch_cart(cart_id, etag)
        status_url = self.create_reservation(cart_id)
        reservation_id = self.poll_reservation(status_url, cart_id)
        if reservation_id is None:
            # job failed / never became ready -> never checkout
            return
        self.checkout(cart_id, reservation_id, etag)

    # --------------------------------------------------------------- task
    @task
    def run(self):
        for _ in range(ShopUser.ITERATIONS_PER_USER):
            if ShopUser.journeys_started >= ShopUser.TOTAL_JOURNEYS:
                raise StopUser()
            ShopUser.journeys_started += 1
            try:
                self.journey()
            except StopUser:
                raise
            except Exception:
                raise StopUser()
            finally:
                ShopUser.journeys_completed += 1
        raise StopUser()


# ---------------------------------------------------------------------------
# Shape: exactly one, stops when the contracted workload is fully executed
# ---------------------------------------------------------------------------
class ReservationShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._start = time.time()

    def tick(self):
        if ShopUser.journeys_completed >= ShopUser.TOTAL_JOURNEYS:
            return None
        if time.time() - self._start > 180:
            return None
        return (2, 2)
