import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const PASSWORD = 'bench';
const JSON_HEADERS = { 'Content-Type': 'application/json' };

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function getHeader(headers, name) {
  if (!headers) return null;
  const target = name.toLowerCase();
  for (const k in headers) {
    if (k.toLowerCase() === target) return headers[k];
  }
  return null;
}

function absoluteUrl(loc) {
  if (!loc) return null;
  if (loc.charAt(0) === '/') return BASE_URL + loc;
  if (/^https?:\/\//i.test(loc)) {
    if (loc.indexOf(BASE_URL) === 0) return loc;
    const path = loc.replace(/^https?:\/\/[^\/]+/i, '');
    return BASE_URL + (path.charAt(0) === '/' ? path : '/' + path);
  }
  return BASE_URL + (loc.charAt(0) === '/' ? loc : '/' + loc);
}

function attrValue(tag, attr) {
  const re = new RegExp("(?:^|\\s)" + attr + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i");
  const m = tag.match(re);
  if (!m) return null;
  return m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
}

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function extractInputValue(html, name) {
  if (!html) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const n = attrValue(tag, 'name');
    if (n && n.toLowerCase() === name.toLowerCase()) {
      const v = attrValue(tag, 'value');
      if (v !== null) return decodeEntities(v);
    }
  }
  return null;
}

function extractCsrfFromHtml(html) {
  return extractInputValue(html, 'csrf');
}

function extractFormAction(html) {
  if (!html) return null;
  const formRe = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRe.exec(html)) !== null) {
    const a = attrValue(m[0], 'action');
    if (a) return a;
  }
  return null;
}

function selectFromCatalogJson(j) {
  if (!j) return null;
  const products = j.data && j.data.products ? j.data.products : [];
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const variants = p && p.variants ? p.variants : [];
    for (let k = 0; k < variants.length; k++) {
      const v = variants[k];
      if (v && v.in_stock === true && p.id !== undefined && v.id !== undefined) {
        return { product: p.id, variant: v.id };
      }
    }
  }
  return null;
}

function selectFromPageJson(j) {
  if (!j) return null;
  let products = [];
  if (j.data && j.data.product) products = [j.data.product];
  else if (j.product) products = [j.product];
  else if (j.data && j.data.products) products = j.data.products;
  else if (j.products) products = j.products;

  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const variants = p && p.variants ? p.variants : [];
    for (let k = 0; k < variants.length; k++) {
      const v = variants[k];
      if (v && v.in_stock === true && p.id !== undefined && v.id !== undefined) {
        return { product: p.id, variant: v.id };
      }
    }
  }
  return null;
}

function pageNext(j) {
  if (!j) return null;
  if (j.next !== undefined) return j.next;
  if (j.data && j.data.next !== undefined) return j.data.next;
  return null;
}

export default function () {
  const user = 'bench-' + __VU;

  let csrf = null;
  let grantId = null;
  let cartId = null;
  let etag = null;

  function withToken(headers, token) {
    const h = Object.assign({}, headers || {});
    if (token) h['X-CSRF-Token'] = token;
    return h;
  }

  function csrfHeaders(base) {
    return withToken(base || {}, csrf);
  }

  function absorbCsrf(j) {
    if (j && j.csrf) csrf = j.csrf;
  }

  function absorbEtag(res) {
    const e = getHeader(res.headers, 'ETag');
    if (e) etag = e;
  }

  function getErr(res) {
    const j = safeJson(res);
    return j && j.error ? j.error : null;
  }

  function renew() {
    const res = http.post(BASE_URL + '/v2/session/renew', JSON.stringify({}), {
      headers: csrfHeaders(JSON_HEADERS),
      redirects: 0,
      tags: { name: 'session-renew' },
    });
    if (res.status === 200) {
      absorbCsrf(safeJson(res));
      return true;
    }
    return false;
  }

  function recoverCart() {
    if (!cartId) return true;
    const res = http.post(
      BASE_URL + '/v2/carts/' + encodeURIComponent(cartId) + '/recover',
      JSON.stringify({}),
      {
        headers: csrfHeaders(JSON_HEADERS),
        redirects: 0,
        tags: { name: 'cart-recover' },
      }
    );
    absorbCsrf(safeJson(res));
    absorbEtag(res);
    return res.status === 200 || res.status === 201 || res.status === 204;
  }

  function getCartEtag() {
    if (!cartId) return false;
    const res = http.get(BASE_URL + '/v2/carts/' + encodeURIComponent(cartId), {
      headers: csrfHeaders({}),
      redirects: 0,
      tags: { name: 'cart-read' },
    });
    absorbCsrf(safeJson(res));
    absorbEtag(res);
    return res.status === 200 && !!etag;
  }

  function performLogin(formCsrf) {
    let localCsrf = formCsrf;
    let localGrant = null;
    let acquired = false;

    const loginRes = http.post(
      BASE_URL + '/v2/login',
      JSON.stringify({
        username: user,
        password: PASSWORD,
        csrf: formCsrf,
      }),
      {
        headers: JSON_HEADERS,
        redirects: 0,
        tags: { name: 'login' },
      }
    );

    check(loginRes, {
      'login status is success or redirect': (r) =>
        r.status === 200 || (r.status >= 300 && r.status < 400),
    });

    if (loginRes.status >= 300 && loginRes.status < 400) {
      const loc = getHeader(loginRes.headers, 'Location');
      check(loc, { 'login redirect location present': (v) => !!v });
      if (!loc) return { csrf: null, grant: null };

      const redirectRes = http.get(absoluteUrl(loc), {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      check(redirectRes, {
        'login redirect response ok': (r) =>
          r.status === 200 || (r.status >= 300 && r.status < 400),
      });

      const rj = safeJson(redirectRes);
      if (rj && rj.csrf) {
        localCsrf = rj.csrf;
        acquired = true;
      }
      if (rj && rj.grant_id) {
        localGrant = rj.grant_id;
        acquired = true;
      }

