        const challenge = extractInputValue(redirectRes.body, 'challenge');
        const action = extractFormAction(redirectRes.body);

        if (challenge && action) {
          const challengeRes = http.post(
            absoluteUrl(action),
            JSON.stringify({ challenge: challenge }),
            {
              headers: withToken(JSON_HEADERS, localCsrf),
              redirects: 0,
              tags: { name: 'challenge' },
            }
          );

          check(challengeRes, {
            'challenge post redirects': (r) => r.status >= 300 && r.status < 400,
          });

          const challengeLoc = getHeader(challengeRes.headers, 'Location');
          check(challengeLoc, { 'challenge redirect location present': (v) => !!v });

          if (challengeLoc) {
            const claimRes = http.get(absoluteUrl(challengeLoc), {
              redirects: 0,
              tags: { name: 'challenge-redirect' },
            });
            check(claimRes, { 'challenge claim ok': (r) => r.status === 200 });

            const cj = safeJson(claimRes);
            if (cj && cj.csrf) {
              localCsrf = cj.csrf;
              acquired = true;
            }
            if (cj && cj.grant_id) {
              localGrant = cj.grant_id;
              acquired = true;
            }
            check(localGrant, { 'grant id present': (v) => !!v });
          }
        }
      }

      check(acquired, { 'login session acquired after redirect': (v) => v === true });
      if (!acquired) return { csrf: null, grant: null };
    } else if (loginRes.status === 200) {
      const lj = safeJson(loginRes);
      if (lj && lj.csrf) {
        localCsrf = lj.csrf;
        acquired = true;
      }
      check(acquired, { 'login csrf present': (v) => v === true });
      if (!acquired) return { csrf: null, grant: null };
    } else {
      return { csrf: null, grant: null };
    }

    return { csrf: localCsrf, grant: localGrant };
  }

  function freshLogin() {
    http.cookieJar().clear(BASE_URL);

    const formRes = http.get(BASE_URL + '/v2/login-form', {
      redirects: 0,
      tags: { name: 'login-form-fresh' },
    });
    check(formRes, { 'fresh login form ok': (r) => r.status === 200 });

    const formCsrf = extractCsrfFromHtml(formRes.body);
    check(formCsrf, { 'fresh login form csrf present': (v) => !!v });
    if (!formCsrf) return false;

    const sess = performLogin(formCsrf);
    if (sess.csrf) {
      csrf = sess.csrf;
      grantId = sess.grant;
      return true;
    }
    return false;
  }

  http.cookieJar().clear(BASE_URL);

  const formRes = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  check(formRes, { 'login form ok': (r) => r.status === 200 });

  const formCsrf = extractCsrfFromHtml(formRes.body);
  check(formCsrf, { 'login form csrf present': (v) => !!v });
  if (!formCsrf) return;

  const sess = performLogin(formCsrf);
  csrf = sess.csrf;
  grantId = sess.grant;
  if (!csrf) return;

  let selected = null;

  const catalogRes = http.get(BASE_URL + '/v2/catalog', {
    headers: csrfHeaders({}),
    redirects: 0,
    tags: { name: 'catalog' },
  });
  check(catalogRes, { 'catalog ok': (r) => r.status === 200 });

  const catalogJson = safeJson(catalogRes);
  absorbCsrf(catalogJson);
  selected = selectFromCatalogJson(catalogJson);

  if (!selected) {
    let nextUrl = BASE_URL + '/v2/catalog/page';
    for (let i = 0; i < 3 && !selected; i++) {
      const pageRes = http.get(absoluteUrl(nextUrl), {
        headers: csrfHeaders({}),
        redirects: 0,
        tags: { name: 'catalog-page' + i },
      });
      check(pageRes, { ['catalog page ' + i + ' ok']: (r) => r.status === 200 });

