  check(selected, { 'catalog product/variant selected': (v) => !!v });
  if (!selected) return;

  let cartRes = null;
  let cartAttempts = 0;

  while (cartAttempts < 2) {
    const cartBody = {
      product_id: selected.product,
      variant_id: selected.variant,
    };
