    cartRes = http.post(BASE_URL + '/v2/carts', JSON.stringify(cartBody), {
      headers: csrfHeaders(JSON_HEADERS),
      redirects: 0,
      tags: { name: 'cart-create' },
    });

    if (cartRes.status === 401 && cartAttempts === 0) {
      const err = getErr(cartRes);
      let recovered = false;

      if (err === 'expired') {
        const ok = renew();
        check(ok, { 'renew before cart retry': (v) => v === true });
