          recoverCart();
          recovered = true;
        } else {
          recovered = freshLogin();
        }
      } else if (err === 'session') {
        recovered = freshLogin();
        if (recovered) recoverCart();
      } else {
        break;
      }

      if (recovered) {
        cartAttempts++;
        continue;
      }
    }
    break;
  }

  check(cartRes, { 'cart create status 201': (r) => r && r.status === 201 });

  const cartJson = safeJson(cartRes);
  absorbCsrf(cartJson);
  cartId = cartJson && cartJson.id !== undefined ? cartJson.id : null;
  absorbEtag(cartRes);

  check(cartId, { 'cart id present': (v) => !!v });
  grantId = null;
  if (!cartId) return;

  if (!etag) {
    getCartEtag();
  }

  let orderRes = null;
  let orderAttempts = 0;
  let etagRetry = false;

  while (orderAttempts < 2) {
    const orderBody = { cart_id: cartId };
    const headers = csrfHeaders(JSON_HEADERS);
    headers['Idempotency-Key'] = String(cartId);
    if (etag) headers['If-Match'] = etag;

    orderRes = http.post(BASE_URL + '/v2/orders', JSON.stringify(orderBody), {
      headers: headers,
      redirects: 0,
      tags: { name: 'order-create' },
    });

    if (orderRes.status === 412 && !etagRetry) {
      etagRetry = true;
      getCartEtag();
      orderAttempts++;
      continue;
    }

    if (orderRes.status === 401 && orderAttempts === 0) {
      const err = getErr(orderRes);
      let recovered = false;

      if (err === 'expired') {
        const ok = renew();
        check(ok, { 'renew before order retry': (v) => v === true });
        if (ok) {
          recoverCart();
          recovered = true;
        } else {
          recovered = freshLogin();
          if (recovered) recoverCart();
        }
      } else if (err === 'session') {
        recovered = freshLogin();
        if (recovered) recoverCart();
      } else {
        break;
      }

      if (recovered) {
        orderAttempts++;
        continue;
      }
    }
    break;
  }

  const orderJson = safeJson(orderRes);
  absorbCsrf(orderJson);

  check(orderRes, {
    'order status is 201': (r) => r && r.status === 201,
    'order accepted true': (r) => {
      const j = safeJson(r);
      return !!(j && j.accepted === true);
    },
  });
}
