```python
import os
import re
from urllib.parse import urljoin

from locust import HttpUser, task, LoadTestShape, constant
from locust.exception import StopUser

USER_COUNT = 2
ITERATIONS_PER_USER = 2
DONE_ITERATIONS = [0]
STOPPING = [False]
OWNER_COUNTER = [0]


def _parse_attrs(tag):
    attrs = {}
    pattern = r"""([:\w-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))"""
    for match in re.finditer(pattern, tag, re.I | re.S):
        name = match.group(1).lower()
        value = match.group(2)
        if value is None:
            value = match.group(3)
        if value is None:
            value = match.group(4)
        attrs[name] = value
    return attrs


def _extract_input_value(html, wanted_name):
    if not html:
        return None
    html = re.sub(r"<!--.*?-->", "", html, flags=re.S)
    for tag in re.findall(r"<input\b[^>]*>", html, re.I | re.S):
        attrs = _parse_attrs(tag)
        if attrs.get("name", "").lower() == wanted_name.lower():
            value = attrs.get("value")
            if value is not None:
                return value
    return None


def _extract_form_action(html):
    if not html:
        return None
    html = re.sub(r"<!--.*?-->", "", html, flags=re.S)
    for tag in re.findall(r"<form\b[^>]*>", html, re.I | re.S):
        attrs = _parse_attrs(tag)
        action = attrs.get("action")
        if action:
            return action
    return None


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = constant(0.1)

    def on_start(self):
        OWNER_COUNTER[0] += 1
        owner_number = OWNER_COUNTER[0]
        self.username = f"bench-{owner_number}" if owner_number <= 16 else "bench"
        self.login_csrf = ""
        self.csrf = ""
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self._started = False

    @task
    def run_journeys(self):
        if self._started:
            return
        self._started = True

        for _ in range(ITERATIONS_PER_USER):
            try:
                self._journey()
            except Exception:
                pass
            finally:
                DONE_ITERATIONS[0] += 1

        while not STOPPING[0]:
            self.wait()

        raise StopUser()

    def _journey(self):
        self.client.cookies.clear()
        self.login_csrf = ""
        self.csrf = ""
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None

        if not self._get_login_form():
            return
        if not self._login():
            return

        product_id, variant_id = self._get_catalog()
        if not product_id or not variant_id:
            return

        self._get_grant()
        if not self._create_cart(product_id, variant_id):
            return
        self._create_order()

    def _absolute_url(self, location):
        location = (location or "").strip()
        if not location:
            return self.host
        if location.startswith("http://") or location.startswith("https://"):
            return location
        base = self.host.rstrip("/")
        if location.startswith("/"):
            return base + location
        return urljoin(base + "/", location)

    def _headers(self, csrf=True, etag=None, idempotency_key=None):
        headers = {}
        if csrf and self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if etag:
            headers["If-Match"] = etag
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key
        return headers

    def _json(self, response):
        try:
            return response.json()
        except Exception:
            return None

    def _update_csrf(self, response):
        token = None
        body = self._json(response)
        if isinstance(body, dict):
            token = body.get("csrf")
        if not token:
            match = re.search(r'"csrf"\s*:\s*"([^"]+)"', response.text or "")
            if match:
                token = match.group(1)
        if not token:
            token = _extract_input_value(response.text or "", "csrf")
        if token:
            self.csrf = token
        return token

    def _error_code(self, response):
        body = self._json(response)
        if isinstance(body, dict):
            error = body.get("error")
            if isinstance(error, dict):
                error = error.get("code") or error.get("error")
            if isinstance(error, str):
                return error
        match = re.search(r'"error"\s*:\s*"([^"]+)"', response.text or "")
        if match:
            return match.group(1)
        return None

    def _expected_expiry(self, response):
        if response.status_code != 401:
            return False
        return self._error_code(response) in ("expired", "session")

    def _get_login_form(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            if response.status_code != 200:
                response.failure(f"login-form status {response.status_code}")
                return False
            token = _extract_input_value(response.text, "csrf")
            if not token:
                response.failure("login-form missing csrf")
                return False
            self.login_csrf = token
            response.success()
            return True

    def _get_login_redirect(self, location):
        with self.client.get(
            self._absolute_url(location),
            name="/v2/login redirect",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            if response.status_code != 200:
                response.failure(f"login redirect status {response.status_code}")
                return False
            self._update_csrf(response)
            body = self._json(response)
            if isinstance(body, dict):
                if body.get("csrf"):
                    self.csrf = body["csrf"]
                if body.get("grant_id"):
                    self.grant_id = body["grant_id"]
            if not self.csrf:
                token = _extract_input_value(response.text or "", "csrf")
                if token:
                    self.csrf = token
            if not self.csrf:
                response.failure("login redirect missing csrf")
                return False
            response.success()
            return True

    def _login(self):
        payload = {
            "username": self.username,
            "password": "bench",
            "csrf": self.login_csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            name="/v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("login 302 missing Location")
                    return False
                ok = self._get_login_redirect(location)
                if ok:
                    response.success()
                else:
                    response.failure("login redirect failed")
                return ok

            if response.status_code != 200:
                response.failure(f"login status {response.status_code}")
                return False

            self._update_csrf(response)
            if not self.csrf:
                response.failure("login missing csrf")
                return False
            response.success()
            return True

    def _choose_product(self, body):
        if not isinstance(body, dict):
            return None, None
        data = body.get("data")
        if not isinstance(data, dict):
            return None, None
        products = data.get("products")
        if not isinstance(products, list):
            return None, None

        for product in products:
            if not isinstance(product, dict):
                continue
            product_id = product.get("id")
            variants = product.get("variants")
            if not product_id or not isinstance(variants, list):
                continue
            for variant in variants:
                if not isinstance(variant, dict):
                    continue
                if variant.get("in_stock") is True:
                    variant_id = variant.get("id")
                    if variant_id:
                        return product_id, variant_id
        return None, None

    def _get_catalog(self):
        for attempt in range(2):
            with self.client.get(
                "/v2/catalog",
                name="/v2/catalog",
                catch_response=True,
                allow_redirects=False,
            ) as response:
                if response.status_code == 401 and attempt == 0 and self._expected_expiry(response):
                    response.success()
                    self._recover_session()
                    continue
                if response.status_code != 200:
                    response.failure(f"catalog status {response.status_code}")
                    return None, None

                body = self._json(response)
                self._update_csrf(response)
                product_id, variant_id = self._choose_product(body)
                if not product_id or not variant_id:
                    response.failure("catalog missing in-stock product")
                    return None, None
                response.success()
                return product_id, variant_id
        return None, None

    def _get_grant(self):
        self.grant_id = None
        with self.client.get(
            "/v2/challenge-form",
            name="/v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            if response.status_code == 404:
                response.success()
                return False
            if response.status_code != 200:
                response.failure(f"challenge-form status {response.status_code}")
                return False

            action = _extract_form_action(response.text)
            challenge = _extract_input_value(response.text, "challenge")
            if not action or not challenge:
                response.failure("challenge-form missing action or challenge")
                return False
            response.success()

        action_url = self._absolute_url(action)
        with self.client.post(
            action_url,
            json={"challenge": challenge},
            headers=self._headers(csrf=True),
            name="/v2/challenges/[id]",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("challenge POST missing Location")
                    return False

                with self.client.get(
                    self._absolute_url(location),
                    name="/v2/challenge claim",
                    catch_response=True,
                    allow_redirects=False,
                ) as claim:
                    if claim.status_code != 200:
                        claim.failure(f"challenge claim status {claim.status_code}")
                        response.failure("challenge claim failed")
                        return False

                    self._update_csrf(claim)
                    body = self._json(claim)
                    grant_id = body.get("grant_id") if isinstance(body, dict) else None
                    if not grant_id:
                        claim.failure("challenge claim missing grant_id")
                        response.failure("challenge claim missing grant_id")
                        return False

                    self.grant_id = grant_id
                    claim.success()
                    response.success()
                    return True

            if response.status_code == 200:
                self._update_csrf(response)
                body = self._json(response)
                grant_id = body.get("grant_id") if isinstance(body, dict) else None
                if grant_id:
                    self.grant_id = grant_id
                    response.success()
                    return True
                response.failure("challenge POST missing grant_id")
                return False

            response.failure(f"challenge POST status {response.status_code}")
            return False

    def _create_cart(self, product_id, variant_id):
        payload = {
            "product_id": product_id,
            "variant_id": variant_id,
        }
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        for attempt in range(2):
            with self.client.post(
                "/v2/carts",
                json=payload,
                headers=self._headers(csrf=True),
                name="/v2/carts",
                catch_response=True,
                allow_redirects=False,
            ) as response:
                self._update_csrf(response)

                if response.status_code == 401 and attempt == 0 and self._expected_expiry(response):
                    response.success()
                    self._recover_session()
                    continue

                if response.status_code != 201:
                    response.failure(f"cart status {response.status_code}")
                    return False

                body = self._json(response)
                cart_id = body.get("id") if isinstance(body, dict) else None
                if not cart_id:
                    response.failure("cart missing id")
                    return False

                self.cart_id = cart_id
                etag = response.headers.get("ETag")
                if etag:
                    self.cart_etag = etag
                if isinstance(body, dict) and body.get("csrf"):
                    self.csrf = body["csrf"]

                self.grant_id = None
                response.success()
                return True

        return False

    def _create_order(self):
        if not self.cart_id:
            return False

        payload = {"cart_id": self.cart_id}
        idempotency_key = self.cart_id

        for attempt in range(2):
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=self._headers(
                    csrf=True,
                    etag=self.cart_etag,
                    idempotency_key=idempotency_key,
                ),
                name="/v2/orders",
                catch_response=True,
                allow_redirects=False,
            ) as response:
                self._update_csrf(response)

                if response.status_code == 401 and attempt == 0 and self._expected_expiry(response):
                    response.success()
                    self._recover_session()
                    continue

                if response.status_code not in (200, 201):
                    response.failure(f"order status {response.status_code}")
                    return False

                body = self._json(response)
                accepted = body.get("accepted") if isinstance(body, dict) else None
                if accepted is not True:
                    response.failure("order not accepted")
                    return False

                response.success()
                return True

        return False

    def _recover_session(self):
        renewed = False

        if self.csrf:
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=self._headers(csrf=True),
                name="/v2/session/renew",
                catch_response=True,
                allow_redirects=False,
            ) as response:
                self._update_csrf(response)
                if response.status_code == 200:
                    renewed = True
                    response.success()
                elif response.status_code == 401:
                    response.success()
                else:
                    response.failure(f"session renew status {response.status_code}")

        if not renewed or not self.csrf:
            self.client.cookies.clear()
            self.csrf = ""
            self.login_csrf = ""
            if not self._get_login_form():
                return False
            if not self._login():
                return False

        if self.cart_id:
            self._recover_cart()

        return True

    def _recover_cart(self):
        if not self.cart_id:
            return False

        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=self._headers(csrf=True),
            name="/v2/carts/[id]/recover",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            self._update_csrf(response)
            etag = response.headers.get("ETag")
            if etag:
                self.cart_etag = etag

            if response.status_code in (200, 201, 204):
                response.success()
                return True

            response.failure(f"cart recover status {response.status_code}")
            return False


class ShopShape(LoadTestShape):
    def tick(self):
        if STOPPING[0]:
            return None

        if DONE_ITERATIONS[0] >= USER_COUNT * ITERATIONS_PER_USER:
            STOPPING[0] = True
            return None

        if self.get_run_time() > 120:
            STOPPING[0] = True
            return None

        return (USER_COUNT, USER_COUNT)
