        loc = _norm_url(loc)
        with self.client.get(loc, catch_response=True, allow_redirects=False) as resp2:
            if resp2.status_code != 200:
                resp2.failure(f"challenge redirect status {resp2.status_code}: {resp2.text[:200]}")
