                if resp.status_code == 200:
                    return _json_body(resp)
                if resp.status_code == 401 and self._is_expiry(resp):
                    if retried:
                        resp.failure("catalog 401 after recovery")
                        return None
                    retried = True
                    kind = self._expiry_kind(resp)
                else:
                    label = "catalog page" if page else "catalog"
                    resp.failure(f"{label} status {resp.status_code}: {resp.text[:200]}")
                    return None
            if not self._recover(kind):
                return None

    def _select_product(self):
        payload = self._catalog_payload("/v2/catalog")
