        return None

    def _find_product(self, payload):
        products = []
        if isinstance(payload, dict):
            data = payload.get("data")
            if isinstance(data, dict):
                if isinstance(data.get("products"), list):
                    products = data["products"]
                elif isinstance(data.get("product"), dict):
                    products = [data["product"]]
                elif "id" in data and "variants" in data:
                    products = [data]
            if not products:
                if isinstance(payload.get("products"), list):
                    products = payload["products"]
                elif isinstance(payload.get("product"), dict):
                    products = [payload["product"]]
                elif "id" in payload and "variants" in payload:
                    products = [payload]

        for p in products:
            if not isinstance(p, dict):
                continue
            variants = p.get("variants")
            if not isinstance(variants, list):
                continue
            for v in variants:
                if isinstance(v, dict) and v.get("in_stock") is True:
