        if grant_id:
            body["grant_id"] = grant_id

        def validator(resp):
            data = _json_body(resp)
            cart_id = data.get("id")
            if not cart_id:
                return False, None
            self.cart_id = cart_id
            self.has_cart = True
            csrf = data.get("csrf")
            if csrf:
                self.csrf = csrf
            etag = resp.headers.get("ETag")
            if etag:
                self.etag = etag
            return True, True

