    def _patch_quantity(self, quantity):
        if not self.cart_id:
            return False
        if not self.etag:
            if not self._refresh_cart_etag():
                return False

        payload = {"quantity": int(quantity)}
        retried_401 = False
        retried_412 = False

        while True:
            headers = {"X-CSRF-Token": self.csrf or "", "If-Match": self.etag or ""}
            with self.client.patch(
                f"/v2/carts/{self.cart_id}",
                json=payload,
                headers=headers,
                catch_response=True,
                allow_redirects=False,
            ) as resp:
