                    data = _json_body(resp)
                    csrf = data.get("csrf")
                    if csrf:
                        self.csrf = csrf
                    etag = resp.headers.get("ETag")
                    if etag:
                        self.etag = etag
                    return True
                if resp.status_code == 412:
                    if retried_412:
                        resp.failure("PATCH 412 after retry")
                        return False
                    retried_412 = True
                elif resp.status_code == 401 and self._is_expiry(resp):
                    if retried_401:
                        resp.failure("PATCH 401 after recovery")
                        return False
                    retried_401 = True
                    kind = self._expiry_kind(resp)
                else:
                    resp.failure(f"PATCH status {resp.status_code}: {resp.text[:200]}")
                    return False

            if resp.status_code == 412:
                if not self._refresh_cart_etag():
                    return False
