            if resp.status_code == 401 and self._is_expiry(resp):
                if not self._recover(kind):
                    return False
                if not self.etag:
                    if not self._refresh_cart_etag():
                        return False
                continue

            return False

    def _refresh_cart_etag(self):
        if not self.cart_id:
            return False
        retried = False
        while True:
            with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True, allow_redirects=False) as resp:
                if resp.status_code == 200:
                    etag = resp.headers.get("ETag")
                    if etag:
                        self.etag = etag
                        return True
                    resp.failure("cart GET missing ETag")
                    return False
                if resp.status_code == 401 and self._is_expiry(resp):
                    if retried:
                        resp.failure("cart GET 401 after recovery")
                        return False
                    retried = True
                    kind = self._expiry_kind(resp)
                else:
                    resp.failure(f"cart GET status {resp.status_code}: {resp.text[:200]}")
                    return False
            if not self._recover(kind):
                return False

    def _checkout(self):
        if not self.cart_id:
            return False

        body = {"cart_id": self.cart_id}
        retried = False

        while True:
            headers = {"X-CSRF-Token": self.csrf or "", "Idempotency-Key": str(self.cart_id)}
            if self.etag:
                headers["If-Match"] = self.etag

            with self.client.post(
                "/v2/orders",
                json=body,
                headers=headers,
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code == 201:
                    data = _json_body(resp)
                    if data.get("accepted") is True:
                        csrf = data.get("csrf")
                        if csrf:
                            self.csrf = csrf
                        return True
                    resp.failure("order 201 not accepted")
                    return False

                if resp.status_code == 200:
                    data = _json_body(resp)
                    if data.get("accepted") is False:
                        resp.failure("order business failure accepted:false")
                    else:
                        resp.failure(f"order 200 unexpected: {resp.text[:200]}")
                    return False

                if resp.status_code == 401 and self._is_expiry(resp):
                    if retried:
                        resp.failure("order 401 after recovery")
                        return False
                    retried = True
                    kind = self._expiry_kind(resp)
                else:
                    resp.failure(f"order status {resp.status_code}: {resp.text[:200]}")
                    return False

            if not self._recover(kind):
                return False

    def _authed_json(self, method, path, expected, *, headers=None, json=None, validator=None):
        req_headers = dict(headers or {})
        if method.upper() != "GET":
            req_headers["X-CSRF-Token"] = self.csrf or ""
        retried = False

        while True:
            with self.client.request(
                method,
                path,
                json=json,
                headers=req_headers,
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code in expected:
                    if validator is not None:
                        try:
                            ok, value = validator(resp)
                        except Exception as exc:
                            resp.failure(f"validation error: {exc}")
                            return None
                        if not ok:
                            resp.failure("response validation failed")
                            return None
                        return value
                    return True

                if resp.status_code == 401 and self._is_expiry(resp):
                    if retried:
                        resp.failure("401 after recovery")
                        return None
                    retried = True
                    kind = self._expiry_kind(resp)
                else:
                    resp.failure(f"unexpected status {resp.status_code}: {resp.text[:200]}")
                    return None

            if not self._recover(kind):
                return None
            req_headers["X-CSRF-Token"] = self.csrf or ""

    def _is_expiry(self, resp):
        if resp.status_code != 401:
            return False
        data = _json_body(resp)
        return data.get("error") in ("expired", "session")

    def _expiry_kind(self, resp):
        data = _json_body(resp)
        err = data.get("error")
        if err in ("expired", "session"):
            return err
        return "expired"

    def _recover(self, kind):
        if kind == "expired":
            if self._renew_session():
                if self.has_cart and self.cart_id:
                    return self._recover_cart()
                return True

        if self._fresh_login():
            if self.has_cart and self.cart_id:
                return self._recover_cart()
            return True

        return False

    def _fresh_login(self):
        return self._login(clear_cookies=True)

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = _json_body(resp)
                csrf = data.get("csrf")
                if not csrf:
                    resp.failure("renew missing csrf")
                    return False
                self.csrf = csrf
                return True
            if resp.status_code == 401:
                return False
            resp.failure(f"renew status {resp.status_code}: {resp.text[:200]}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = _json_body(resp)
                csrf = data.get("csrf")
                if csrf:
                    self.csrf = csrf
                return True
            if resp.status_code == 401 and self._is_expiry(resp):
                return False
            resp.failure(f"cart recover status {resp.status_code}: {resp.text[:200]}")
            return False


