import json
import os
import re
import html as html_lib
from locust import HttpUser, task, constant, LoadTestShape, StopUser

FIXTURE_DIR = "/fixtures"
USERS = 2
ITERATIONS = 2


def _load_accounts():
    for name in ("accounts.json", "m04-accounts.json"):
        try:
            with open(os.path.join(FIXTURE_DIR, name), "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, list) and data:
                    return data
        except Exception:
            pass
    return [{"username": "bench-1", "password": "bench", "quantity": 2, "delay": 0}]


ACCOUNTS = _load_accounts()


def _attr_value(tag, key):
    pattern = r'(?:^|\s)' + re.escape(key) + r'\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))'
    m = re.search(pattern, tag, re.I | re.S)
    if not m:
        return None
    val = m.group(1) if m.group(1) is not None else m.group(2) if m.group(2) is not None else m.group(3)
    return html_lib.unescape(val) if val is not None else None


def _extract_input_value(text, name):
    values = []
    for m in re.finditer(r'<input\b[^>]*>', text, re.I | re.S):
        tag = m.group(0)
        n = _attr_value(tag, "name")
        if n == name:
            v = _attr_value(tag, "value")
            if v is not None:
                values.append(v)
    for v in values:
        if v:
            return v
    if values:
        return values[0]
    return None


def _extract_form_action(text):
    for m in re.finditer(r'<form\b[^>]*>.*?</form>', text, re.I | re.S):
        block = m.group(0)
        if _extract_input_value(block, "challenge") is not None:
            opening = block[:block.find(">") + 1]
            action = _attr_value(opening, "action")
            if action:
                return action
    for m in re.finditer(r'<form\b[^>]*>', text, re.I | re.S):
        action = _attr_value(m.group(0), "action")
        if action:
            return action
    return None


def _json_body(resp):
    try:
        return resp.json()
    except Exception:
        return {}


def _norm_url(url):
    if not isinstance(url, str):
        return None
    if url.startswith("http://") or url.startswith("https://"):
        return url
    if url.startswith("/"):
        return url
    return "/" + url


