            return False
        data = _json_body(resp)
        return data.get("error") in ("expired", "session")

    def _expiry_kind(self, resp):
        data = _json_body(resp)
        err = data.get("error")
        if err in ("expired", "session"):
            return err
        return "expired"

    def _recover(self, kind):
        if kind == "expired":
            if self._renew_session():
                if self.has_cart and self.cart_id:
                    return self._recover_cart()
                return True

        if self._fresh_login():
            if self.has_cart and self.cart_id:
                return self._recover_cart()
            return True

        return False

    def _fresh_login(self):
        return self._login(clear_cookies=True)

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = _json_body(resp)
                csrf = data.get("csrf")
                if not csrf:
                    resp.failure("renew missing csrf")
                    return False
                self.csrf = csrf
                return True
            if resp.status_code == 401:
                return False
            resp.failure(f"renew status {resp.status_code}: {resp.text[:200]}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = _json_body(resp)
                csrf = data.get("csrf")
                if csrf:
                    self.csrf = csrf
                return True
            if resp.status_code == 401 and self._is_expiry(resp):
                return False
            resp.failure(f"cart recover status {resp.status_code}: {resp.text[:200]}")
            return False


class ShopShape(LoadTestShape):
    def tick(self):
        global _started_count, _active_count
        if self.get_run_time() > 120:
            return None
        if _started_count < USERS:
            return (USERS, USERS)
        if _active_count <= 0:
            return None
        return (_active_count, 1)
