                .doIf(session -> session.userId() % 4 == 3)
                .then(exec(session -> session).pause(Duration.ofMillis(1500)))
                .forever().on(journey);

        setUp(
                scn.injectClosed(
                        constantConcurrentUsers(4).during(Duration.ofSeconds(38))
                )
        ).protocols(httpProtocol);
    }
}
