import html as html_module
import itertools
import json
import os
import re
import time

from locust import HttpUser, LoadTestShape, constant_pacing, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
RUN_SECONDS = 38.0
_user_seq = itertools.count(1)


def _json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def extract_input_value(html, name):
    if not html:
        return None
    pat = re.compile(
        r"<input(?=[^>]*\bname\s*=\s*[\"']%s[\"'])(?=[^>]*\bvalue\s*=\s*[\"']([^\"']+)[\"'])[^>]*>"
        % re.escape(name),
        re.I,
    )
    m = pat.search(html)
    if m:
        return html_module.unescape(m.group(1))
    pat = re.compile(
        r"<input\b[^>]*\bname\s*=\s*%s\b[^>]*\bvalue\s*=\s*([^\s>]+)[^>]*>"
        % re.escape(name),
        re.I,
    )
    m = pat.search(html)
    if m:
        return html_module.unescape(m.group(1))
    pat = re.compile(
        r"<input\b[^>]*\bvalue\s*=\s*([^\s>]+)[^>]*\bname\s*=\s*%s\b[^>]*>"
        % re.escape(name),
        re.I,
    )
    m = pat.search(html)
    if m:
        return html_module.unescape(m.group(1))
    return None


def extract_form_action(html, must_contain=None):
    if not html:
        return None
    pat = re.compile(
        r"<form\b(?=[^>]*\baction\s*=\s*[\"']([^\"']+)[\"'])[^>]*>",
        re.I,
    )
    for m in pat.finditer(html):
        action = m.group(1)
        if must_contain is None or must_contain in action:
            return html_module.unescape(action)
    pat = re.compile(
        r"<form\b(?=[^>]*\baction\s*=\s*([^\s>]+))[^>]*>",
        re.I,
    )
    for m in pat.finditer(html):
        action = m.group(1)
        if must_contain is None or must_contain in action:
            return html_module.unescape(action)
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant_pacing(2.0)

    def on_start(self):
        self.user_num = next(_user_seq)
        self.username = "bench-%d" % (((self.user_num - 1) % 16) + 1)
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.start_time = time.time()

    def _error(self, resp):
        data = _json(resp)
        if isinstance(data, dict) and data.get("error"):
            return str(data["error"])
        return ""

    def _update_csrf(self, data):
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _do(self, method, path, name, expected, use_csrf=True, recovery=True,
            validate=None, extra_headers=None, **body_kwargs):
        headers = dict(extra_headers or {})
        if use_csrf and method.upper() != "GET" and self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        req_kwargs = dict(body_kwargs)
        req_kwargs["headers"] = headers
        req_kwargs["allow_redirects"] = False

        need_recover = None
        with self.client.request(method, path, catch_response=True, name=name,
                                 **req_kwargs) as response:
            if recovery and response.status_code == 401:
                err = self._error(response)
                if err in ("expired", "session"):
                    response.success()
                    need_recover = err
                elif err == "denied":
                    response.failure("401 denied")
                    return None
                else:
                    response.failure("401 %s" % (err or "unauthorized"))
                    return None
            elif response.status_code not in expected:
                response.failure("unexpected status %s" % response.status_code)
                return None
            else:
                if validate:
                    try:
                        ok, msg = validate(response)
                    except Exception as e:
                        response.failure("validation error: %s" % e)
                        return None
                    if not ok:
                        response.failure(msg or "validation failed")
                        return None
                response.success()
                return response

        if need_recover is not None and self._recover(need_recover):
            return self._do(method, path, name, expected, use_csrf=use_csrf,
                            recovery=False, validate=validate,
                            extra_headers=extra_headers, **body_kwargs)
        return None

    def _recover(self, err):
        if err == "expired":
            resp = self._do(
                "POST", "/v2/session/renew", "POST /v2/session/renew",
                (200, 201, 204), use_csrf=True, recovery=False, json={},
            )
            if not resp:
