                d2 = _json(r2)
                if d2:
                    self._update_csrf(d2)
                if r2.headers.get("ETag"):
                    self.etag = r2.headers.get("ETag")
            return True

        if err == "session":
            if not self._login_flow(reset=False):
                return False
            if self.cart_id:
                r2 = self._do(
                    "POST", "/v2/carts/%s/recover" % self.cart_id,
                    "POST /v2/carts/{id}/recover", (200, 201, 204),
                    use_csrf=True, recovery=False, json={},
                )
                if not r2:
                    return False
                d2 = _json(r2)
                if d2:
                    self._update_csrf(d2)
                if r2.headers.get("ETag"):
                    self.etag = r2.headers.get("ETag")
            return True

        return False

    def _handle_challenge_html(self, html):
        action = extract_form_action(html, "/v2/challenges/")
        challenge = extract_input_value(html, "challenge")
        if not action or not challenge:
            return False

        resp = self._do(
            "POST", action, "POST /v2/challenges/{id}", (302,),
            use_csrf=True, recovery=False, json={"challenge": challenge},
        )
        if not resp:
            return False

        loc = resp.headers.get("Location")
        if not loc:
            return False

        r2 = self._do(
            "GET", loc, "GET challenge redirect", (200,),
            use_csrf=False, recovery=False,
        )
        if not r2:
            return False

        data = _json(r2)
        if data:
            self._update_csrf(data)
            if data.get("grant_id"):
                self.grant_id = data["grant_id"]
            return True
        return False

    def _login_flow(self, reset=False):
        if reset:
            self.cart_id = None
            self.etag = None
            self.grant_id = None
            self.csrf = None

        resp = self._do(
            "GET", "/v2/login-form", "GET /v2/login-form", (200,),
            use_csrf=False, recovery=False,
            validate=lambda r: (extract_input_value(r.text, "csrf") is not None,
                                "missing csrf"),
        )
        if not resp:
            return False

        csrf = extract_input_value(resp.text, "csrf")
        if not csrf:
            return False
        self.csrf = csrf

        body = {"username": self.username, "password": self.password,
                "csrf": self.csrf}
        resp = self._do(
            "POST", "/v2/login", "POST /v2/login", (200, 201, 302),
            use_csrf=True, recovery=False, json=body,
        )
        if not resp:
            return False

        if resp.status_code == 302:
            loc = resp.headers.get("Location")
            if not loc:
                return False
            r2 = self._do(
                "GET", loc, "GET login redirect", (200,),
                use_csrf=False, recovery=False,
            )
            if not r2:
                return False
            data = _json(r2)
            if data:
                self._update_csrf(data)
                if data.get("grant_id"):
                    self.grant_id = data["grant_id"]
            else:
                self._handle_challenge_html(r2.text)
        else:
            data = _json(resp)
            if data:
                self._update_csrf(data)
                if data.get("grant_id"):
                    self.grant_id = data["grant_id"]
            else:
                self._handle_challenge_html(resp.text)

        return self.csrf is not None

    def _extract_product(self, data):
        if not isinstance(data, dict):
            return None, None

        payload = data.get("data", data)
        products = []
        if isinstance(payload, dict):
            if isinstance(payload.get("products"), list):
                products = payload["products"]
            elif isinstance(payload.get("product"), dict):
                products = [payload["product"]]
            elif payload.get("id") and isinstance(payload.get("variants"), list):
                products = [payload]
        elif isinstance(payload, list):
            products = payload

        for prod in products:
            if not isinstance(prod, dict):
                continue
            pid = prod.get("id")
            variants = prod.get("variants") or []
            if not pid or not isinstance(variants, list):
                continue
            for var in variants:
                if isinstance(var, dict) and var.get("in_stock") is True:
                    vid = var.get("id")
                    if vid:
                        return pid, vid
        return None, None

    def _select_product(self):
        resp = self._do(
            "GET", "/v2/catalog", "GET /v2/catalog", (200,),
            use_csrf=False, recovery=True,
        )
        if not resp:
            return None, None

        data = _json(resp)
        pid, vid = self._extract_product(data)
        if pid and vid:
            return pid, vid

        next_url = None
        if isinstance(data, dict):
            next_url = data.get("next")
            if next_url is None and isinstance(data.get("data"), dict):
                next_url = data["data"].get("next")
        if not isinstance(next_url, str):
            next_url = None

        pages = 1
        while next_url and pages < 3:
            resp = self._do(
                "GET", next_url, "GET /v2/catalog/page", (200,),
                use_csrf=False, recovery=True,
            )
            pages += 1
            if not resp:
                break
            data = _json(resp)
            if not isinstance(data, dict):
                break
            pid, vid = self._extract_product(data)
            if pid and vid:
                return pid, vid
            nxt = data.get("next")
            if nxt is None and isinstance(data.get("data"), dict):
                nxt = data["data"].get("next")
            next_url = nxt if isinstance(nxt, str) else None

        return None, None

    def _create_cart(self, product_id, variant_id):
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
            self.grant_id = None

        def validate(resp):
            data = _json(resp)
            if not isinstance(data, dict):
                return False, "invalid cart json"
            cart_id = data.get("id")
