            "POST", "/v2/orders", "POST /v2/orders", (201,),
            use_csrf=True, recovery=True,
            extra_headers=extra, json=body, validate=validate,
        )
        if not resp:
            return False

        data = _json(resp)
        self._update_csrf(data)
        return True

    @task
    def journey(self):
        if time.time() - self.start_time >= RUN_SECONDS:
            raise StopUser()

        if not self._login_flow(reset=True):
            return

