import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    'checks{check:login_csrf}': ['rate==1'],
    'checks{check:cart_created}': ['rate==1'],
    'checks{check:order_accepted}': ['rate==1'],
  },
};

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function errorCode(res) {
  const body = safeJson(res);
  return body && typeof body.error === 'string' ? body.error : null;
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const want = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === want) return res.headers[key];
  }
  return null;
}

function decodeHtml(value) {
  return String(value || '')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function attrValue(tag, attrName) {
  const re = new RegExp('(?:^|\\s)' + attrName + '\\s*=\\s*([^\\s>]+)', 'i');
  const match = tag.match(re);
  if (!match) return null;

  let raw = match[1];
  if (raw.length > 1 && raw.charAt(raw.length - 1) === '/') {
    const prev = raw.charAt(raw.length - 2);
    if (prev === '"' || prev === "'") raw = raw.slice(0, -1);
  }

  if (raw.length >= 2) {
    const first = raw.charAt(0);
    const last = raw.charAt(raw.length - 1);
    if ((first === '"' && last === '"') || (first === "'" && last === "'")) {
      raw = raw.slice(1, -1);
    }
  }

  return decodeHtml(raw);
}

function extractInputValue(html, inputName) {
  if (!html) return null;
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const name = attrValue(tags[i], 'name');
    if (name && name.toLowerCase() === inputName.toLowerCase()) {
      return attrValue(tags[i], 'value');
    }
  }
  return null;
}

function extractFormAction(html) {
  if (!html) return null;
  const forms = html.match(/<form\b[^>]*>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const action = attrValue(forms[i], 'action');
    if (action) return action;
  }
  return null;
}

function resolveLocation(location) {
  if (!location) return null;
  if (/^https?:\/\//i.test(location)) {
    return location.indexOf(BASE_URL) === 0 ? location : null;
  }
  return BASE_URL + (location.charAt(0) === '/' ? location : '/' + location);
}

function productsFromBody(body) {
  if (!body || !body.data) return [];
  if (Array.isArray(body.data.products)) return body.data.products;
  if (body.data.product) return [body.data.product];
  if (Array.isArray(body.data.items)) return body.data.items;
  return [];
}

function findProductVariant(body) {
  const products = productsFromBody(body);
  for (let i = 0; i < products.length; i++) {
    const product = products[i];
    if (!product || !Array.isArray(product.variants)) continue;

    for (let j = 0; j < product.variants.length; j++) {
      const variant = product.variants[j];
      if (
        variant &&
        variant.in_stock === true &&
        product.id !== undefined &&
        product.id !== null &&
        variant.id !== undefined &&
        variant.id !== null
      ) {
        return { product: product.id, variant: variant.id };
      }
    }
  }
  return null;
}

function getNext(body) {
  return body && typeof body.next === 'string' && body.next ? body.next : null;
}

function doLogin(state) {
  let loginFormCsrfOk = false;
  let loginAuthOk = false;

  const formRes = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    timeout: '3s',
    tags: { transaction: 'login-form' },
  });

  const formHtml = formRes.body || '';
  const formCsrf = extractInputValue(formHtml, 'csrf');
  loginFormCsrfOk = formRes.status === 200 && !!formCsrf;

  if (!loginFormCsrfOk) {
    return { loginFormCsrfOk: false, loginAuthOk: false };
  }

  state.csrf = formCsrf;

  const loginRes = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({
      username: state.username,
      password: 'bench',
      csrf: state.csrf,
    }),
    {
      redirects: 0,
      timeout: '3s',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      tags: { transaction: 'login' },
    }
  );

  const loginBody = safeJson(loginRes);
  const loginLocation = getHeader(loginRes, 'Location');

  if (loginRes.status === 200 && loginBody && typeof loginBody.csrf === 'string') {
    state.csrf = loginBody.csrf || state.csrf;
    loginAuthOk = true;
  } else if (loginRes.status === 302 && loginLocation) {
    const locationUrl = resolveLocation(loginLocation);

    if (locationUrl) {
      const locationRes = http.get(locationUrl, {
        redirects: 0,
        timeout: '3s',
        tags: { transaction: 'login-redirect' },
      });

      const locationBody = safeJson(locationRes);

      if (locationRes.status === 200 && locationBody && typeof locationBody.csrf === 'string') {
        state.csrf = locationBody.csrf;
        if (typeof locationBody.grant_id === 'string') state.grant = locationBody.grant_id;
        loginAuthOk = true;
      } else {
        const html = locationRes.body || '';
        const locationCsrf = extractInputValue(html, 'csrf');
        if (locationCsrf) state.csrf = locationCsrf;

        const action = extractFormAction(html);
        const challenge = extractInputValue(html, 'challenge');

        if (action && challenge && state.csrf) {
          const actionUrl = resolveLocation(action);

          if (actionUrl) {
            const challengeRes = http.post(
              actionUrl,
              JSON.stringify({ challenge: challenge }),
              {
                redirects: 0,
                timeout: '3s',
                headers: {
                  'Content-Type': 'application/json',
                  'X-CSRF-Token': state.csrf,
                },
                tags: { transaction: 'challenge' },
              }
            );

            const challengeBody = safeJson(challengeRes);
            if (challengeBody && typeof challengeBody.csrf === 'string') {
              state.csrf = challengeBody.csrf;
            }

            const challengeLocation = getHeader(challengeRes, 'Location');

            if (challengeRes.status === 302 && challengeLocation) {
              const grantUrl = resolveLocation(challengeLocation);

              if (grantUrl) {
                const grantRes = http.get(grantUrl, {
                  redirects: 0,
                  timeout: '3s',
                  tags: { transaction: 'challenge-grant' },
                });

                const grantBody = safeJson(grantRes);
                if (grantBody && typeof grantBody.csrf === 'string') {
                  state.csrf = grantBody.csrf;
                }
                if (grantBody && typeof grantBody.grant_id === 'string') {
                  state.grant = grantBody.grant_id;
                }

                loginAuthOk = grantRes.status === 200 && !!state.csrf && !!state.grant;
              }
            }
          }
        }
      }
    }
  }

  return { loginFormCsrfOk: loginFormCsrfOk, loginAuthOk: loginAuthOk };
}

function recoverSession(state, operation) {
  if (!state.recovery) state.recovery = {};
  if ((state.recovery[operation] || 0) >= 1) return false;
  state.recovery[operation] = (state.recovery[operation] || 0) + 1;

  let renewed = false;

  if (state.csrf) {
    const renewRes = http.post(BASE_URL + '/v2/session/renew', '{}', {
      redirects: 0,
      timeout: '3s',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      tags: { transaction: 'session-renew' },
    });

    if (renewRes.status === 401 && errorCode(renewRes) === 'denied') {
      return false;
    }

    const renewBody = safeJson(renewRes);
    if (
      renewRes.status >= 200 &&
      renewRes.status < 300 &&
      renewBody &&
      typeof renewBody.csrf === 'string'
    ) {
      state.csrf = renewBody.csrf;
      renewed = true;
    }
  }

  if (!renewed) {
    try {
      http.cookieJar().clear(BASE_URL);
    } catch (e) {}

    state.grant = null;
    const login = doLogin(state);
    if (!login.loginAuthOk) return false;
    renewed = true;
  }

  if (state.cartId && state.csrf) {
    const recoverRes = http.post(
      BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover',
      '{}',
      {
        redirects: 0,
        timeout: '3s',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
        },
        tags: { transaction: 'cart-recover' },
      }
    );

    const recoverBody = safeJson(recoverRes);
    if (recoverBody && typeof recoverBody.csrf === 'string') {
      state.csrf = recoverBody.csrf;
    }

    const etag = getHeader(recoverRes, 'ETag');
    if (etag) state.etag = etag;
  }

  return true;
}

function getCatalogProduct(state) {
  let res = http.get(BASE_URL + '/v2/catalog', {
    redirects: 0,
    timeout: '3s',
    tags: { transaction: 'catalog' },
  });

  if (res.status === 401) {
    const error = errorCode(res);
    if (error === 'expired' || error === 'session') {
      if (recoverSession(state, 'catalog')) {
        res = http.get(BASE_URL + '/v2/catalog', {
          redirects: 0,
          timeout: '3s',
          tags: { transaction: 'catalog' },
        });
      }
    }
  }

  let body = safeJson(res);
  let found = res.status === 200 ? findProductVariant(body) : null;
  let next = getNext(body);
  let pages = 0;

  while (!found && next && pages < 3) {
    const nextUrl = resolveLocation(next);
    if (!nextUrl) break;

    let pageRes = http.get(nextUrl, {
      redirects: 0,
      timeout: '3s',
      tags: { transaction: 'catalog-page' },
    });

    if (pageRes.status === 401) {
      const error = errorCode(pageRes);
      if (error === 'expired' || error === 'session') {
        if (recoverSession(state, 'catalog-page')) {
          pageRes = http.get(nextUrl, {
            redirects: 0,
            timeout: '3s',
            tags: { transaction: 'catalog-page' },
          });
        }
      }
    }

    const pageBody = safeJson(pageRes);
    found = pageRes.status === 200 ? findProductVariant(pageBody) : null;
    next = getNext(pageBody);
    pages++;
  }

  if (found) {
    state.productId = found.product;
    state.variantId = found.variant;
    return true;
  }

  return false;
}

function createCart(state) {
  if (state.productId === null || state.variantId === null) return false;

  function buildPayload() {
    const payload = {
      product_id: state.productId,
      variant_id: state.variantId,
    };
    if (state.grant) payload.grant_id = state.grant;
    return JSON.stringify(payload);
  }

  function buildHeaders() {
    return {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    };
  }

  let payload = buildPayload();
  let res = http.post(BASE_URL + '/v2/carts', payload, {
    redirects: 0,
    timeout: '3s',
    headers: buildHeaders(),
    tags: { transaction: 'cart' },
  });

