import http from 'k6/http';
import { check } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

let csrf = '';
let cartId = '';
let etag = '';

function jsonBody(res) {
  try {
    return res.json() || {};
  } catch (_) {
    return {};
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) return undefined;
  const wanted = String(name).toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === wanted) return res.headers[key];
  }
  return undefined;
}

function accountForVu() {
  const idx = ((__VU - 1) % 16) + 1;
  return { username: 'bench-' + idx, password: 'bench' };
}

function extractLoginCsrf(res) {
  let token = '';

  try {
    const doc = res.html();
    let el = doc.find('form[action*="/v2/login"] input[name="csrf"]').first();
    if (!el || !el.attr('value')) {
      el = doc.find('input[name="csrf"]').first();
    }
    if (el) token = el.attr('value') || '';
  } catch (_) {}

  if (token) return token;

  const html = res.body || '';
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    if (/\bname\s*=\s*(?:"csrf"|'csrf'|csrf)(?=\s|\/?>|$)/i.test(tag)) {
      const v = /\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag);
      if (v) {
        token = v[1] || v[2] || v[3] || '';
        if (token) break;
      }
    }
  }

  return token;
}

function call(path, method, data, opts) {
  method = (method || 'GET').toUpperCase();
  opts = opts || {};

  const url = /^https?:\/\//i.test(path) ? path : BASE + path;
  const headers = Object.assign({}, opts.headers || {});

  if (data !== null && data !== undefined) {
    headers['Content-Type'] = 'application/json';
  }
  if (!opts.omitCsrfHeader && csrf && method !== 'GET' && method !== 'HEAD') {
    headers['X-CSRF-Token'] = csrf;
  }

  const params = {
    headers: headers,
    redirects: 0,
    timeout: opts.timeout || '3s',
  };
  if (opts.tags) params.tags = opts.tags;

  const res = http.request(
    method,
    url,
    data === null || data === undefined ? null : JSON.stringify(data),
    params
  );

  const b = jsonBody(res);
  if (b && typeof b.csrf === 'string' && b.csrf) {
    csrf = b.csrf;
  }

  return res;
}

function login() {
  csrf = '';

  const formRes = call('/v2/login-form', 'GET');
  check(formRes, { 'login form loaded': r => r.status === 200 });

  const loginToken = extractLoginCsrf(formRes);
  check(loginToken, { 'login csrf parsed': t => !!t });
  if (!loginToken) return formRes;

  const acct = accountForVu();
  let res = call('/v2/login', 'POST', {
    username: acct.username,
    password: acct.password,
    csrf: loginToken,
  }, { omitCsrfHeader: true });

  if (res.status >= 300 && res.status < 400) {
    const loc = getHeader(res, 'Location');
    if (loc) {
      res = call(loc, 'GET');
    }
  }

  check(res, {
    'login succeeded': r => r.status === 200 && !!jsonBody(r).user,
  });

  return res;
}

function request(path, method, data, opts) {
  method = (method || 'GET').toUpperCase();
  opts = opts || {};

  let res = call(path, method, data, opts);
  if (res.status !== 401) return res;

  const err = jsonBody(res).error;
  if (err !== 'expired' && err !== 'session') return res;

  let renewed = false;
  if (err === 'expired') {
    const renewRes = call('/v2/session/renew', 'POST', {});
    renewed = renewRes.status === 200;
  }

  if (!renewed) {
    login();
  }

  if (cartId) {
    call('/v2/carts/' + cartId + '/recover', 'POST', {});
    const readRes = call('/v2/carts/' + cartId, 'GET');
    const fresh = getHeader(readRes, 'ETag');
    if (fresh) {
      etag = fresh;
      if (opts.headers && opts.headers['If-Match']) {
        opts.headers['If-Match'] = etag;
      }
    }
  }

  return call(path, method, data, opts);
}

function pickProduct() {
  let page = '/v2/catalog';

  for (let n = 0; n < 3 && page; n++) {
    const res = request(page, 'GET');
    check(res, { 'catalog loaded': r => r.status === 200 });

    const b = jsonBody(res);
    const products = (b.data && b.data.products) || [];

    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      if (!p || !Array.isArray(p.variants)) continue;

      for (let j = 0; j < p.variants.length; j++) {
        const v = p.variants[j];
        if (v && v.in_stock) {
          return { product: p, variant: v };
        }
      }
    }

    const next = b.next;
    page = (typeof next === 'string' && next && next !== 'null') ? next : null;
  }

  return null;
}

export default function () {
  csrf = '';
  cartId = '';
  etag = '';

  const loginRes = login();
  if (!jsonBody(loginRes).user) {
    return;
  }

  const selected = pickProduct();
  if (!selected) {
    check(false, { 'eligible product': () => false });
    return;
  }

  const cartRes = request('/v2/carts', 'POST', {
    product_id: selected.product.id,
    variant_id: selected.variant.id,
  });
  check(cartRes, { 'cart created': r => r.status === 201 });

  cartId = jsonBody(cartRes).id || '';
  if (!cartId) {
    check(false, { 'cart id parsed': () => false });
    return;
  }

  etag = getHeader(cartRes, 'ETag') || '';
  if (!etag) {
    const readRes = request('/v2/carts/' + cartId, 'GET');
    etag = getHeader(readRes, 'ETag') || '';
  }

  const orderHeaders = { 'Idempotency-Key': cartId };
  if (etag) orderHeaders['If-Match'] = etag;

  const orderRes = request('/v2/orders', 'POST', { cart_id: cartId }, { headers: orderHeaders });
  check(orderRes, {
    'order accepted': r => {
      const b = jsonBody(r);
      return r.status === 201 && b.accepted === true;
    },
  });
}

import os
from html.parser import HTMLParser

from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'flow'}
TOTAL_ITERATIONS = CFG['users'] * CFG['iterations']

_USER_LOCK = Semaphore()
_USER_NUM = {'n': 0}

_DONE = Event()
_COMP_LOCK = Semaphore()
_COMPLETED = {'n': 0}


class _CSRFExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.values = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != 'input':
            return
        d = {k.lower(): v for k, v in attrs}
        if d.get('name') == 'csrf' and d.get('value'):
            self.values.append((d.get('type', '').lower(), d['value']))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def get_value(self):
        if not self.values:
            return None
        for kind, value in self.values:
            if kind == 'hidden':
                return value
        return self.values[0][1]


def extract_csrf(html):
    parser = _CSRFExtractor()
    try:
        parser.feed(html or '')
    except Exception:
        pass
    return parser.get_value()


def extract_products(body):
    if not isinstance(body, dict):
        return []
    data = body.get('data')
    if isinstance(data, dict):
        products = data.get('products')
        if isinstance(products, list):
            return products
        product = data.get('product')
        if isinstance(product, dict):
            return [product]
    product = body.get('product')
    if isinstance(product, dict):
        return [product]
    if body.get('id') and isinstance(body.get('variants'), list):
        return [body]
    return []


class MatrixUser(HttpUser):
    host = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
    wait_time = lambda self: 0

    def on_start(self):
        with _USER_LOCK:
            _USER_NUM['n'] += 1
            number = _USER_NUM['n']
        self.username = 'bench-' + str((number - 1) % 16 + 1)
        self.password = 'bench'
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def _headers(self, method, extra=None):
        headers = {'Content-Type': 'application/json'}
        if self.csrf and method.upper() != 'GET':
            headers['X-CSRF-Token'] = self.csrf
        if extra:
            headers.update(extra)
        return headers

    def raw(self, method, path, json_body=None, headers=None, name=None,
            allow_auth_error=True, allow_412=True):
        request_headers = self._headers(method, headers)
        with self.client.request(
            method,
            path,
            json=json_body,
            headers=request_headers,
            name=name or path,
            catch_response=True,
            allow_redirects=False,
            timeout=5,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            status = response.status_code
            error = body.get('error')
            ok = status < 400

            if status == 401 and allow_auth_error and error in ('expired', 'session'):
                ok = True
            if status == 412 and allow_412:
                ok = True

            if method.upper() == 'POST' and str(path).split('?', 1)[0].endswith('/orders'):
                if status < 400 and body.get('accepted') is not True:
                    ok = False

            if ok:
                response.success()
            else:
                response.failure('HTTP %s %s' % (status, error or ''))

            if body.get('csrf'):
                self.csrf = body['csrf']

            return response, body

    def request(self, method, path, json_body=None, headers=None, name=None,
                allow_412=True):
        response, body = self.raw(
            method, path, json_body, headers, name, allow_412=allow_412
        )
        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            self.recover()
            retry_headers = dict(headers or {})
            if 'If-Match' in retry_headers and self.etag:
                retry_headers['If-Match'] = self.etag
            response, body = self.raw(
                method,
                path,
                json_body,
                retry_headers,
                name,
                allow_auth_error=False,
                allow_412=allow_412,
            )
        return response, body

    def login(self):
        self.csrf = ''
        form_response, _ = self.raw('GET', '/v2/login-form', name='login-form')
        if form_response.status_code != 200:
            return False

        token = extract_csrf(form_response.text)
        if not token:
            return False

        login_response, login_body = self.raw(
            'POST',
            '/v2/login',
            json_body={
                'username': self.username,
                'password': self.password,
                'csrf': token,
            },
            name='login',
        )

        if login_response.status_code in (301, 302, 303, 307, 308):
            location = login_response.headers.get('Location')
            if not location:
                return False
            _, login_body = self.raw('GET', location, name='login-redirect')

        if login_body.get('csrf'):
            self.csrf = login_body['csrf']

        return bool(self.csrf)

    def recover(self):
        renewed = False
        if self.csrf:
            response, body = self.raw(
                'POST', '/v2/session/renew', json_body={}, name='session-renew'
            )
            if response.status_code == 200:
                renewed = True
                if body.get('csrf'):
                    self.csrf = body['csrf']
                if self.cart:
                    cart_response, _ = self.raw(
                        'POST',
                        '/v2/carts/' + self.cart + '/recover',
                        json_body={},
                        name='cart-recover',
                    )
                    self.etag = cart_response.headers.get('ETag', self.etag)

        if not renewed:
            self.login()
            if self.cart:
                cart_response, _ = self.raw(
                    'POST',
                    '/v2/carts/' + self.cart + '/recover',
                    json_body={},
                    name='cart-recover',
                )
                self.etag = cart_response.headers.get('ETag', self.etag)

    def find_product(self):
        page = '/v2/catalog'
        seen = set()
        for _ in range(3):
            if not page or page in seen:
                break
            seen.add(page)
            response, body = self.request('GET', page, name='catalog')
            if response.status_code != 200:
                return None, None

            for product in extract_products(body):
                if not isinstance(product, dict):
                    continue
                for variant in product.get('variants', []):
                    if isinstance(variant, dict) and variant.get('in_stock'):
                        return product, variant

            next_page = body.get('next') if isinstance(body, dict) else None
            if not next_page:
                break
            page = next_page

        return None, None

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''

        if not self.login():
            return

        product, variant = self.find_product()
        if not product or not variant:
            return

        cart_payload = {
            'product_id': product.get('id'),
            'variant_id': variant.get('id'),
        }
        if self.grant:
            cart_payload['grant_id'] = self.grant

        cart_response, cart_body = self.request(
            'POST', '/v2/carts', json_body=cart_payload, name='create-cart'
        )
        if cart_response.status_code != 201:
            return

        self.cart = cart_body.get('id', '')
        self.etag = cart_response.headers.get('ETag', '')
        if not self.cart:
            return

        order_body = {'cart_id': self.cart}
        order_headers = {'Idempotency-Key': self.cart}
        if self.etag:
            order_headers['If-Match'] = self.etag

        order_response, _ = self.request(
            'POST',
            '/v2/orders',
            json_body=order_body,
            headers=order_headers,
            name='checkout',
        )

        if order_response.status_code == 412:
            read_response, _ = self.request(
                'GET', '/v2/carts/' + self.cart, name='cart-read'
            )
            self.etag = read_response.headers.get('ETag', self.etag)
            retry_headers = {'Idempotency-Key': self.cart}
            if self.etag:
                retry_headers['If-Match'] = self.etag
            self.request(
                'POST',
                '/v2/orders',
                json_body=order_body,
                headers=retry_headers,
                name='checkout',
                allow_412=False,
            )

    @task
    def run_scenario(self):
        try:
            self.flow()
        finally:
            self.iteration += 1
            with _COMP_LOCK:
                _COMPLETED['n'] += 1
                if _COMPLETED['n'] >= TOTAL_ITERATIONS:
                    _DONE.set()

            if self.iteration >= CFG['iterations']:
                _DONE.wait(timeout=15)
                raise StopUser()


class MatrixShape(LoadTestShape):
    def tick(self):
        if _DONE.is_set():
            return None
        return CFG['users'], CFG['users']

