function header(r, name) {
  if (!r || !r.headers) return null;
  const lname = name.toLowerCase();
  if (r.headers[name] !== undefined) return r.headers[name];
  if (r.headers[lname] !== undefined) return r.headers[lname];
  for (const k in r.headers) {
    if (k.toLowerCase() === lname) return r.headers[k];
  }
  return null;
}

function body(r) {
  if (!r || !r.body) return {};
  try {
    const v = r.json();
    if (v && typeof v === 'object') return v;
  } catch (e) {}
  return {};
}

function absolute(path) {
  if (!path) return base;
  const p = String(path);
  if (/^https?:\/\//i.test(p)) return p;
  if (p.charAt(0) === '/') return base + p;
  return base + '/' + p;
