function raw(st, path, method, data, extra) {
  const m = method || 'GET';
  const headers = {'Content-Type': 'application/json'};
  if (st.csrf) headers['X-CSRF-Token'] = st.csrf;
  if (extra) {
    for (const k in extra) {
