function attrFromTag(tag, name) {
  const re = new RegExp("(?:^|\\s)" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i");
  const m = re.exec(tag);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  return m[3];
}

function inputValues(html, name) {
  const out = [];
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html || '')) !== null) {
    const tag = m[0];
    const n = attrFromTag(tag, 'name');
    if (n && n.toLowerCase() === name.toLowerCase()) {
      const v = attrFromTag(tag, 'value');
      if (v !== null && out.indexOf(v) === -1) out.push(v);
