}

function login(st, fresh) {
  if (fresh) resetCookies();
  st.csrf = '';
  const form = raw(st, '/v2/login-form', 'GET', null, {});
  const candidates = csrfCandidates(form);
  if (!candidates.length) {
    check(false, {'login': function () { return false; }});
    return false;
  }
  let last = null;
  for (let i = 0; i < candidates.length; i++) {
    st.csrf = '';
    let r = raw(st, '/v2/login', 'POST', {
      username: st.user.username,
      password: st.user.password,
      csrf: candidates[i]
    }, {});
