import os
import re
import html
from urllib.parse import urlparse

from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {"users": 2, "iterations": 2}
ITERATIONS = CFG["iterations"]
BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

_account_lock = Semaphore()
_next_account = 0


def _claim_username():
    global _next_account
    with _account_lock:
        n = _next_account
        _next_account += 1
    return "bench-%d" % ((n % 16) + 1)


def _attrs(tag):
    attrs = {}
    pattern = r'([A-Za-z_:][A-Za-z0-9_:\.-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))'
    for m in re.finditer(pattern, tag):
        name = m.group(1).lower()
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
        attrs[name] = html.unescape(val)
    return attrs


def _find_input_value(html_text, wanted_name):
    candidates = []
    for m in re.finditer(r'<input\b[^>]*>', html_text, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r'\bdisabled\b', tag, re.IGNORECASE):
            continue
        attrs = _attrs(tag)
        if attrs.get("name", "").lower() == wanted_name.lower() and "value" in attrs:
            candidates.append(attrs)
    if not candidates:
        return None
    for attrs in candidates:
        if attrs.get("type", "").lower() in ("", "hidden"):
            return attrs["value"]
    return candidates[0]["value"]


def _path_only(location):
    parsed = urlparse(location)
    if parsed.scheme:
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        return path
    return location


class FlowUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        self.username = _claim_username()
        self.password = "bench"
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.grant = ""
        self.iterations_done = 0

    def _reset_journey(self):
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.grant = ""
        try:
            self.client.cookies.clear()
        except Exception:
            pass

    def _raw(self, method, path, data=None, headers=None, name=None, allow_auth_errors=False):
        req_headers = {"Content-Type": "application/json"}
        if self.csrf:
            req_headers["X-CSRF-Token"] = self.csrf
        if headers:
            req_headers.update(headers)
        with self.client.request(
            method,
            path,
            json=data,
            headers=req_headers,
            name=name or path,
            catch_response=True,
            allow_redirects=False,
            timeout=10,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            status = response.status_code
            err = body.get("error") if isinstance(body, dict) else None
            is_work = path.split("?", 1)[0] == "/v2/work"
            expected_401 = allow_auth_errors and status == 401 and err in ("expired", "session")
            expected_412 = method == "PATCH" and status == 412 and err in ("etag", "etag_conflict")
            expected_429 = is_work and status == 429
