                headers["If-Match"] = self.etag
            resp, body = self._raw(method, path, data, headers, name, allow_auth_errors=False)
        return resp, body

    def _recover(self):
        renewed = False
        if self.csrf:
            resp, _ = self._raw("POST", "/v2/session/renew", {}, name="renew", allow_auth_errors=True)
            if resp.status_code < 400:
                renewed = True
