            page = _path_only(nxt)
        return None, None

    def _create_cart(self, product, variant):
        payload = {"product_id": product["id"], "variant_id": variant["id"]}
        if self.grant:
            payload["grant_id"] = self.grant
        resp, body = self._request("POST", "/v2/carts", payload, name="create-cart")
        if resp.status_code == 201 and isinstance(body, dict) and body.get("id"):
            self.cart = body["id"]
            self.etag = resp.headers.get("ETag", "")
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return True
