        return False

    def _flow(self):
        self._reset_journey()
        if not self._login():
            return False
        product, variant = self._fetch_product()
        if not product or not variant:
            self.environment.process_exit_code = 99
            return False
        if not self._create_cart(product, variant):
            return False
        if not self._place_order():
            return False
        return True

    @task
    def run_journey(self):
        self._flow()
        self.iterations_done += 1
        if self.iterations_done >= ITERATIONS:
            raise StopUser()


class TwoUserTwoIterationShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            return CFG["users"], CFG["users"]
        current = self.runner.user_count
        if current == 0:
            return None
        return current, max(1, current)

