import os
import re

from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {"users": 2, "iterations": 2, "mode": "denial"}
USERS = CFG.get("users", 2)
ITERATIONS = CFG.get("iterations", 2)

USER_SEQ = 0
USER_LOCK = Semaphore()
FINISHED = 0
FINISH_LOCK = Semaphore()
ALL_DONE = Event()


def input_value(html, name):
    if not html:
        return None
    escaped = re.escape(name)
    name_pat = r'(?:\s)name\s*=\s*(?:"%s"|\'%s\'|%s)(?=[\s>/])' % (
        escaped, escaped, escaped)
    value_pat = r'(?:\s)value\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+?))(?=[\s>]|/>)'
    for tag in re.findall(r'<input\b[^>]*>', html, re.I | re.S):
        if re.search(name_pat, tag, re.I):
            match = re.search(value_pat, tag, re.I)
            if match:
                for group in match.groups():
                    if group is not None:
                        return group
    return None


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = lambda self: 0

    def on_start(self):
        global USER_SEQ
        with USER_LOCK:
            USER_SEQ += 1
            self.user_number = USER_SEQ
        self.username = "bench-%d" % (((self.user_number - 1) % 16) + 1)
        self.password = "bench"
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.iteration = 0

    def _headers(self, method, data, headers):
        hdrs = {"Accept": "application/json"}
        if data is not None:
            hdrs["Content-Type"] = "application/json"
        if self.csrf and method not in ("GET", "HEAD"):
            hdrs["X-CSRF-Token"] = self.csrf
        hdrs.update(headers or {})
        return hdrs

    def _once(self, path, method="GET", data=None, headers=None, name=None, allow_412=False):
        hdrs = self._headers(method, data, headers)
        with self.client.request(method, path, json=data, headers=hdrs, name=name,
                                 catch_response=True, allow_redirects=False, timeout=5) as response:
            try:
                body = response.json()
            except Exception:
                body = {}
            status = response.status_code
            error = body.get("error") if isinstance(body, dict) else None
            ok = True
            reason = ""
            if status == 401:
                if error in ("expired", "session"):
                    ok = True
                else:
                    ok = False
                    reason = "401 %s is not expiry" % (error or "denied")
            elif status == 412 and allow_412:
                ok = True
            elif status == 429:
                if path.split("?", 1)[0] in ("/v2/work", "/v2/browse"):
                    ok = True
                else:
                    ok = False
                    reason = "unexpected 429"
            elif status >= 400:
                ok = False
                reason = "unexpected HTTP %s" % status
            elif method == "POST" and path.split("?", 1)[0] == "/v2/orders":
                accepted = body.get("accepted") if isinstance(body, dict) else None
                if status not in (200, 201) or accepted is not True:
                    ok = False
                    reason = "order assertion failed"
            if ok:
                response.success()
            else:
                response.failure(reason or "request assertion failed")
                self.environment.process_exit_code = 99
            if isinstance(body, dict) and body.get("csrf"):
                self.csrf = body["csrf"]
            return response, body

    def _recover_cart(self):
        if not self.cart:
            return True
        response, body = self._once("/v2/carts/" + self.cart + "/recover",
                                    "POST", {}, name="cart-recover")
        if response.status_code < 400:
            etag = response.headers.get("ETag")
            if etag:
                self.etag = etag
            if isinstance(body, dict) and body.get("csrf"):
                self.csrf = body["csrf"]
            return True
        return False

    def _recover_session(self, force_login=False):
        if not force_login:
            response, body = self._once("/v2/session/renew", "POST", {}, name="renew")
            if response.status_code == 200:
                if isinstance(body, dict) and body.get("csrf"):
                    self.csrf = body["csrf"]
                if self._recover_cart():
                    return True
        self.client.cookies.clear()
        self.csrf = ""
        if not self.login():
            return False
        return self._recover_cart()

    def request(self, path, method="GET", data=None, headers=None, name=None, allow_412=False):
        recoveries = 0
        while True:
            hdrs = dict(headers or {})
            for key in list(hdrs):
                if key.lower() == "if-match":
                    hdrs[key] = self.etag
            response, body = self._once(path, method, data, hdrs, name, allow_412=allow_412)
            status = response.status_code
            error = body.get("error") if isinstance(body, dict) else None
            if status == 401 and error in ("expired", "session") and recoveries < 2:
                recoveries += 1
                self._recover_session(force_login=(error == "session"))
                continue
            return response, body

    def login(self):
        self.csrf = ""
        response, body = self._once("/v2/login-form", "GET", name="login-form")
        if response.status_code >= 400:
            return False
        token = input_value(response.text, "csrf")
        if not token:
            self.environment.process_exit_code = 99
            return False
        response, body = self._once(
            "/v2/login", "POST",
            {"username": self.username, "password": self.password, "csrf": token},
            name="login")
        if response.status_code == 302:
            location = response.headers.get("Location")
            if location:
                response, body = self._once(location, "GET", name="login-redirect")
        if isinstance(body, dict) and body.get("csrf"):
            self.csrf = body["csrf"]
        return response.status_code < 400 or response.status_code == 302

    def _pick_product(self, products):
        for product in products or []:
            for variant in product.get("variants") or []:
                if variant.get("in_stock"):
                    return product, variant
        return None, None

    def _find_product(self):
        response, body = self.request("/v2/catalog", name="catalog")
        if response.status_code >= 400:
            return None, None
        products = body.get("data", {}).get("products", []) if isinstance(body, dict) else []
        product, variant = self._pick_product(products)
        if product:
            return product, variant
        next_path = body.get("next") if isinstance(body, dict) else None
        pages = 0
        while next_path and pages < 3:
            pages += 1
            response, body = self.request(next_path, name="catalog-page")
            if response.status_code >= 400:
                break
            products = body.get("data", {}).get("products", []) if isinstance(body, dict) else []
            product, variant = self._pick_product(products)
            if product:
                return product, variant
            next_path = body.get("next") if isinstance(body, dict) else None
        return None, None

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        if not self.login():
            return False
        product, variant = self._find_product()
        if not product or not variant:
            self.environment.process_exit_code = 99
            return False
        cart_data = {"product_id": product["id"], "variant_id": variant["id"]}
        response, body = self.request("/v2/carts", "POST", cart_data, name="cart-create")
        if response.status_code not in (200, 201):
            return False
        self.cart = body.get("id", "") if isinstance(body, dict) else ""
        if not self.cart:
            self.environment.process_exit_code = 99
            return False
        etag = response.headers.get("ETag")
        if etag:
            self.etag = etag
        if isinstance(body, dict) and body.get("csrf"):
            self.csrf = body["csrf"]
        order_data = {"cart_id": self.cart}
        order_headers = {"Idempotency-Key": self.cart}
        if self.etag:
            order_headers["If-Match"] = self.etag
        response, body = self.request("/v2/orders", "POST", order_data,
                                      order_headers, name="checkout")
        if response.status_code not in (200, 201):
            return False
        if not isinstance(body, dict) or body.get("accepted") is not True:
            self.environment.process_exit_code = 99
            return False
        if body.get("csrf"):
            self.csrf = body["csrf"]
        return True

    @task
    def run_scenario(self):
        try:
            self.flow()
        except Exception:
            self.environment.process_exit_code = 99
        finally:
            self.iteration += 1
            if self.iteration >= ITERATIONS:
                self._finish_user()

    def _finish_user(self):
        global FINISHED
        with FINISH_LOCK:
            FINISHED += 1
            if FINISHED >= USERS:
                ALL_DONE.set()
        ALL_DONE.wait(timeout=10)
        raise StopUser()


class MatrixShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() > 180:
            return None
        if FINISHED >= USERS:
            return None
        return USERS, max(1, USERS)
