import os
import re
import time

from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {"users": 2, "iterations": 2, "mode": "decline"}
USERS = CFG["users"]
ITERATIONS = CFG["iterations"]

SLOT_LOCK = Semaphore()
NEXT_SLOT = 0
DONE_LOCK = Semaphore()
COMPLETED = 0

ATTR_RE = re.compile(
    r"""([^\s=/>]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))""",
    re.I | re.S,
)


def input_value(html, wanted):
    matches = []
    fallback = None
    for tag in re.findall(r"<input\b[^>]*>", html or "", re.I | re.S):
        attrs = {}
        for match in ATTR_RE.finditer(tag):
            name = match.group(1).lower()
            if match.group(2) is not None:
                value = match.group(2)
            elif match.group(3) is not None:
                value = match.group(3)
            else:
                value = match.group(4)
            attrs[name] = value
        if attrs.get("name", "").lower() == wanted.lower():
            value = attrs.get("value", "")
            if value:
                matches.append((attrs, value))
            elif fallback is None:
                fallback = value
    for attrs, value in matches:
        if attrs.get("type", "").lower() == "hidden":
            return value
    if matches:
        return matches[0][1]
    return fallback


def norm_path(path):
    if not path:
        return path
    if path.startswith("http://") or path.startswith("https://") or path.startswith("/"):
        return path
    return "/" + path


class DeclineUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = lambda self: 0

    def on_start(self):
        global NEXT_SLOT
        with SLOT_LOCK:
            slot = NEXT_SLOT
            NEXT_SLOT += 1
        if slot >= USERS:
            raise StopUser()
        self.username = "bench-" + str(slot + 1)
        self.password = "bench"
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.iteration = 0

    def _json(self, response):
        try:
            body = response.json()
        except Exception:
            return {}
        return body if isinstance(body, dict) else {}

    def _headers(self, extra=None):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if extra:
            headers.update(extra)
        return headers

    def _default_ok(self, response, body, method, path):
        path_only = path.split("?", 1)[0] if path else ""
        if method == "POST" and path_only == "/v2/orders":
            accepted = body.get("accepted")
            if (
                response.status_code in (200, 201)
                and accepted is True
                and body.get("id")
            ):
                return True, ""
            reason = body.get("error")
            if accepted is False:
                reason = reason or "accepted=false"
            elif accepted is True:
                reason = reason or "missing id"
            return False, "order assertion failed: " + str(reason or "not accepted")
        if method == "POST" and path_only == "/v2/carts":
            if response.status_code == 201 and body.get("id"):
                return True, ""
            return False, "cart creation assertion failed"
        if response.status_code < 400:
            return True, ""
        return False, "unexpected HTTP %s" % response.status_code

    def _request(
        self,
        method,
        path,
        json=None,
        headers=None,
        name=None,
        validator=None,
        recover=True,
    ):
        path = norm_path(path)
        last_response = None
        last_body = {}
        for attempt in range(2):
            do_recover = False
            with self.client.request(
                method,
                path,
                json=json,
                headers=self._headers(headers),
                name=name,
                catch_response=True,
                allow_redirects=False,
                timeout=5,
            ) as response:
                body = self._json(response)
                last_response = response
                last_body = body
                if (
                    recover
                    and attempt == 0
                    and response.status_code == 401
                    and body.get("error") in ("expired", "session")
                ):
                    response.success()
                    do_recover = True
                else:
                    if validator is not None:
                        ok, message = validator(response, body)
                    else:
                        ok, message = self._default_ok(response, body, method, path)
                    if ok:
                        response.success()
                    else:
                        response.failure(message)
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                    return response, body
            if do_recover:
                self.recover()
                continue
        if last_body.get("csrf"):
            self.csrf = last_body["csrf"]
        return last_response, last_body

    def login(self, clear_cookies=True):
        if clear_cookies:
            self.client.cookies.clear()
        self.csrf = ""

        def form_validator(response, body):
            token = input_value(response.text, "csrf")
            return (
                response.status_code < 400 and bool(token),
                "login form missing csrf",
            )

        response, _ = self._request(
            "GET",
            "/v2/login-form",
            name="login-form",
            validator=form_validator,
            recover=False,
        )
        token = input_value(response.text, "csrf") if response is not None else None
        if not token:
            raise StopUser()

        def login_validator(response, body):
            if response.status_code == 302:
                return bool(response.headers.get("Location")), "login redirect missing Location"
            if response.status_code < 400 and body.get("csrf"):
                return True, ""
            return False, "login assertion failed"

        response, body = self._request(
            "POST",
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": token},
            name="login",
            validator=login_validator,
            recover=False,
        )
        if response is not None and response.status_code == 302:
            location = response.headers.get("Location")
            if location:
                def redirect_validator(resp, redirect_body):
                    return (
                        resp.status_code < 400 and bool(redirect_body.get("csrf")),
                        "login redirect missing csrf",
                    )

                response, body = self._request(
                    "GET",
                    norm_path(location),
                    name="login-redirect",
                    validator=redirect_validator,
                    recover=False,
                )
        if body.get("csrf"):
            self.csrf = body["csrf"]
        if not self.csrf:
            raise StopUser()

    def recover(self):
        renew_failed = False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            catch_response=True,
            allow_redirects=False,
            timeout=5,
        ) as response:
            body = self._json(response)
            if response.status_code == 200:
                response.success()
                if body.get("csrf"):
                    self.csrf = body["csrf"]
            else:
                response.failure("session renew failed")
                renew_failed = True
        if renew_failed or not self.csrf:
            self.login(clear_cookies=True)
        if self.cart:
            with self.client.post(
                "/v2/carts/" + self.cart + "/recover",
                json={},
                headers=self._headers(),
                catch_response=True,
                allow_redirects=False,
                timeout=5,
            ) as response:
                body = self._json(response)
                if response.status_code < 400:
                    response.success()
                    self.etag = response.headers.get("ETag", self.etag)
                    if body.get("csrf"):
                        self.csrf = body["csrf"]
                else:
                    response.failure("cart recover failed")

    def _products(self, body):
        data = body.get("data")
        if isinstance(data, dict):
            products = data.get("products")
            if isinstance(products, list):
                return products
        return []

    def _find_in_stock(self, products):
        for product in products or []:
            if not isinstance(product, dict):
                continue
            for variant in product.get("variants") or []:
                if isinstance(variant, dict) and variant.get("in_stock"):
                    return product, variant
        return None, None

    def _catalog_product(self):
        response, body = self._request("GET", "/v2/catalog", name="catalog")
        product, variant = self._find_in_stock(self._products(body))
        if product:
            return product, variant

        page = "/v2/catalog/page"
        seen = set()
        for _ in range(3):
            if not page or page in seen:
                break
            seen.add(page)
            response, body = self._request("GET", page, name="catalog-page")
            products = self._products(body)
            if not products:
                if isinstance(body.get("product"), dict):
                    products = [body["product"]]
                elif "id" in body and "variants" in body:
                    products = [body]
            product, variant = self._find_in_stock(products)
            if product:
                return product, variant
            next_page = body.get("next")
            page = norm_path(next_page) if next_page else None
        return None, None

    def flow(self):
        self.cart = ""
        self.etag = ""
        self.login(clear_cookies=True)

        product, variant = self._catalog_product()
        if (
            not product
            or not variant
            or "id" not in product
            or "id" not in variant
        ):
            raise StopUser()

        response, body = self._request(
            "POST",
            "/v2/carts",
            json={"product_id": product["id"], "variant_id": variant["id"]},
            name="cart-create",
        )
        self.cart = body.get("id", "")
        self.etag = response.headers.get("ETag", "") if response is not None else ""
        if not self.cart:
            raise StopUser()

        order_headers = {"Idempotency-Key": self.cart}
        if self.etag:
            order_headers["If-Match"] = self.etag
        self._request(
            "POST",
            "/v2/orders",
            json={"cart_id": self.cart},
            headers=order_headers,
            name="checkout",
        )

    def _mark_done(self):
        global COMPLETED
        with DONE_LOCK:
            COMPLETED += 1

    @task
    def run_scenario(self):
        try:
            self.flow()
        except StopUser:
            self._mark_done()
            raise
        except Exception:
            pass
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            self._mark_done()
            raise StopUser()


class IterationShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started_at = None
        self.first_tick = True

    def tick(self):
        if self.first_tick:
            self.first_tick = False
            self.started_at = time.monotonic()
            return USERS, USERS
        if COMPLETED >= USERS:
            return None
        if self.started_at is not None and time.monotonic() - self.started_at > 30:
            return None
        return USERS, USERS

