function safeJson(r) {
  try {
    return r.json();
  } catch (e) {
    return {};
  }
}

function absorbCsrf(r) {
  const b = safeJson(r);
  if (b && typeof b.csrf === 'string' && b.csrf.length > 0) {
    csrf = b.csrf;
  }
}

function attrValue(tag, attr) {
  const re = new RegExp('(?:^|\\s)' + attr + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  return m[3];
}

function regexInputValue(html, name) {
  if (!html) return '';
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    const n = attrValue(tag, 'name');
    if (n && n.toLowerCase() === name.toLowerCase()) {
      const v = attrValue(tag, 'value');
      if (v !== null) return v;
    }
  }
  return '';
}

function inputValue(r, name) {
  try {
    const v = r.html().find('input[name="' + name + '"]').first().attr('value');
    if (v) return v;
  } catch (e) {}
  return regexInputValue(r.body, name);
}

function isWorkUnexpected(r) {
  const b = safeJson(r);
  if (r.status === 429) return false;
  if (r.status === 401 && b.error === 'expired') return false;
  if (r.status >= 400) return true;
  if (r.status === 200) return b.ok !== true;
  return true;
}

function requestUrl(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return baseUrl + path;
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = Object.assign({}, extra);
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;
  const r = http.request(method, requestUrl(path), data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '5s',
  });
  absorbCsrf(r);
  if (method === 'POST' && path.split('?')[0] === '/v2/work') {
    failure.add(isWorkUnexpected(r));
  }
  return r;
}

