            if self.started is None:
                self.started = time.monotonic()
            if self.number >= MAX_ARRIVALS:
                return False
            number = self.number
            self.number += 1
            started = self.started
        slot = number / TARGET_RATE
        sleep(max(0.0, started + slot - time.monotonic()))
        return True


ARRIVALS = ArrivalPlan()
USER_LOCK = Semaphore()
USER_SEQ = 0


class MatrixUser(HttpUser):
    host = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')

    def wait_time(self):
        return 0

    def on_start(self):
        global USER_SEQ
        with USER_LOCK:
            USER_SEQ += 1
            index = (USER_SEQ - 1) % 16 + 1
        self.username = 'bench-' + str(index)
        self.password = 'bench'
        self.csrf = ''
        self.login()

    def _setup(self, method, path, data=None, name=None, allowed=(200,)):
        headers = {}
        if method != 'GET':
            headers['Content-Type'] = 'application/json'
        if self.csrf:
            headers['X-CSRF-Token'] = self.csrf
        with self.client.request(
            method, path, json=data, headers=headers, name=name or path,
            catch_response=True, allow_redirects=False, timeout=5
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if isinstance(body, dict) and body.get('csrf'):
                self.csrf = body['csrf']
            if response.status_code in allowed:
                response.success()
            else:
                response.failure('%s status %s' % (name or path, response.status_code))
            return response, body

    def login(self):
        self.csrf = ''
        self.client.cookies.clear()
        form, _ = self._setup('GET', '/v2/login-form', name='login-form')
        if form.status_code >= 400:
            return False
        token = extract_input_value(form.text, 'csrf')
        if not token:
            return False
        response, body = self._setup(
            'POST', '/v2/login',
            data={'username': self.username, 'password': self.password, 'csrf': token},
            name='login', allowed=(200, 302)
        )
        if response.status_code == 302:
            location = response.headers.get('Location')
            if location:
                response, body = self._setup('GET', location, name='login-redirect')
        if isinstance(body, dict) and body.get('csrf'):
            self.csrf = body['csrf']
        return bool(self.csrf)

    def renew(self):
        headers = {'Content-Type': 'application/json'}
        if self.csrf:
            headers['X-CSRF-Token'] = self.csrf
        with self.client.request(
            'POST', '/v2/session/renew', json={}, headers=headers, name='renew',
            catch_response=True, allow_redirects=False, timeout=5
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if isinstance(body, dict) and body.get('csrf'):
                self.csrf = body['csrf']
            ok = response.status_code < 400
            if ok:
                response.success()
            else:
                response.failure('renew status %s' % response.status_code)
        if not ok:
            self.login()

    def work_once(self):
        headers = {'Content-Type': 'application/json'}
        if self.csrf:
            headers['X-CSRF-Token'] = self.csrf
        with self.client.request(
            'POST', '/v2/work', json={}, headers=headers, name='/v2/work',
            catch_response=True, allow_redirects=False, timeout=5
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if isinstance(body, dict) and body.get('csrf'):
                self.csrf = body['csrf']
            status = response.status_code
            error = body.get('error') if isinstance(body, dict) else None
            if status == 429:
                response.success()
            elif status == 401 and error in ('expired', 'session'):
                response.success()
            elif status < 400 and isinstance(body, dict) and body.get('ok') is True:
                response.success()
            else:
                response.failure('work status %s' % status)
            return response, body

    def work(self):
        if not self.csrf and not self.login():
            return
        auth_retry = False
        retries_429 = 0
        while True:
            response, body = self.work_once()
            status = response.status_code
            error = body.get('error') if isinstance(body, dict) else None
            if status == 401 and error in ('expired', 'session'):
                if auth_retry:
                    return
                auth_retry = True
                if error == 'expired':
                    self.renew()
                else:
                    self.login()
                if not self.csrf:
                    return
                continue
            if status == 429:
                if retries_429 >= 4:
                    return
                retries_429 += 1
                try:
                    delay = float(response.headers.get('Retry-After', '1'))
                except (TypeError, ValueError):
                    delay = 1.0
                sleep(max(0.0, delay) + 0.01)
                continue
            return

    @task
    def run_work(self):
        if not self.csrf and not self.login():
            raise StopUser()
        if not ARRIVALS.next():
            end = STOP_AFTER_START + 1.0
            while (ARRIVALS.started is not None and
                   time.monotonic() - ARRIVALS.started < end):
                sleep(0.25)
            raise StopUser()
        self.work()


class MatrixShape(LoadTestShape):
    def tick(self):
        if ARRIVALS.started is None:
            if self.get_run_time() > 15.0:
                return None
            return (USERS, USERS)
        if time.monotonic() - ARRIVALS.started >= STOP_AFTER_START:
            return None
        return (USERS, USERS)

