import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class ModelSimulation extends Simulation {
    private static final String CONFIG_JSON = "{\"users\": 2, \"iterations\": 2, \"mode\": \"partition\"}";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = readConfig();
    private static final int USERS = CFG.path("users").asInt(2);
    private static final int ITERATIONS = CFG.path("iterations").asInt(2);
    private static final String MODE = CFG.path("mode").asText("partition");
    private static final List<Account> ACCOUNTS = loadAccounts();
    private static final String CSRF_INPUT =
        "(?is)<input\\b(?=[^>]*\\bname\\s*=\\s*(?:['\"]?)csrf(?:['\"]?)(?=[\\s>]))"
        + "(?=[^>]*\\bvalue\\s*=\\s*(?:['\"]?)([^'\"\\s>]+))[^>]*>";
    private static final HttpProtocolBuilder HTTP = http.baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static final class Account {
        final String username;
        final String password;
        final int quantity;

        Account(String username, String password, int quantity) {
            this.username = username;
            this.password = password;
            this.quantity = quantity;
        }
    }

    private static JsonNode readConfig() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static int parseInt(String value, int fallback) {
        try {
            return Integer.parseInt(value.trim());
        } catch (RuntimeException error) {
            return fallback;
        }
    }

    private static List<Account> loadAccounts() {
        List<Account> rows = new ArrayList<>();
        try {
            String text = Files.readString(Path.of("/fixtures/accounts.json"));
            JsonNode array = JSON.readTree(text);
            if (array.isArray()) {
                for (JsonNode row : array) {
                    String username = row.path("username").asText("");
                    if (!username.isEmpty()) {
                        rows.add(new Account(username,
                            row.path("password").asText("bench"),
                            row.path("quantity").asInt(2)));
                    }
                }
            }
        } catch (IOException | RuntimeException ignored) {
            // Fall through to CSV aliases.
        }
        if (!rows.isEmpty()) return List.copyOf(rows);

        for (int i = 1; i <= 16; i++) {
            try {
                Path path = Path.of("/fixtures/account-" + i + ".csv");
                if (!Files.exists(path)) continue;
                List<String> lines = Files.readAllLines(path);
                for (int lineNo = 0; lineNo < lines.size(); lineNo++) {
                    String line = lines.get(lineNo).trim();
                    if (line.isEmpty()) continue;
                    if (lineNo == 0 && line.toLowerCase(Locale.ROOT).startsWith("username")) continue;
                    String[] parts = line.split(",", -1);
                    if (parts.length >= 2 && !parts[0].trim().isEmpty()) {
                        rows.add(new Account(parts[0].trim(), parts[1].trim(),
                            parts.length >= 3 ? parseInt(parts[2], 2) : 2));
                    }
                }
            } catch (IOException | RuntimeException ignored) {
                // Try next alias.
            }
        }
        if (!rows.isEmpty()) return List.copyOf(rows);

        for (int i = 1; i <= 16; i++) {
            rows.add(new Account("bench-" + i, "bench", 2));
        }
        return List.copyOf(rows);
    }

    private static boolean has(Session session, String key) {
        return session.contains(key)
            && session.getString(key) != null
            && !session.getString(key).isEmpty();
    }

    private static int journey(Session session) {
        return session.contains("journey") ? session.getInt("journey") : 0;
    }

    private static int accountIndex(Session session) {
        int userIndex = (int) (session.userId() - 1L);
        if (userIndex < 0) userIndex = 0;
        int iter = journey(session);
        int index;
        if (ACCOUNTS.size() >= USERS * ITERATIONS) {
            index = userIndex * ITERATIONS + iter;
        } else {
            index = userIndex;
        }
        return Math.floorMod(index, ACCOUNTS.size());
    }

    private static Account account(Session session) {
        return ACCOUNTS.get(accountIndex(session));
    }

    private static String jsonEscape(String value) {
        if (value == null) return "";
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static boolean hasLocation(Session session) {
        return has(session, "location");
    }

    private static ChainBuilder parseLoginBody() {
        return exec(session -> {
            String body = session.contains("loginBody") ? session.getString("loginBody") : null;
            if (body == null || body.isBlank()) return session;
            try {
                JsonNode node = JSON.readTree(body);
                Session out = session;
                if (node.hasNonNull("csrf")) out = out.set("csrf", node.get("csrf").asText());
                if (node.hasNonNull("grant_id")) out = out.set("grant", node.get("grant_id").asText());
                return out;
            } catch (IOException error) {
                return session;
            }
        });
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .set("csrf", "")
                .set("grant", "")
                .set("formCsrf", "")
                .remove("location")
                .remove("loginBody")
                .remove("loginStatus")
                .remove("product")
                .remove("variant")
                .remove("nextPage")
                .remove("cart")
                .remove("etag")
                .remove("catalogBody"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), regex(CSRF_INPUT).saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> {
                    Account row = account(session);
                    return "{\"username\":\"" + jsonEscape(row.username)
                        + "\",\"password\":\"" + jsonEscape(row.password)
                        + "\",\"csrf\":\"" + jsonEscape(session.getString("formCsrf")) + "\"}";
                }))
                .check(status().in(200, 302),
                    status().saveAs("loginStatus"),
                    bodyString().saveAs("loginBody"),
                    header("Location").optional().saveAs("location")))
            .exec(parseLoginBody())
            .exec(doIf(session -> session.getInt("loginStatus") == 302 && hasLocation(session)).then(
                exec(http("login redirect").get("#{location}")
                    .disableFollowRedirect()
                    .check(status().is(200), bodyString().saveAs("loginBody")))
                .exec(parseLoginBody())));
    }

    private static Session selectProduct(Session session) {
        String body = session.contains("catalogBody") ? session.getString("catalogBody") : null;
        if (body == null || body.isBlank()) return session;
        try {
            JsonNode root = JSON.readTree(body);
            Session out = session;
            JsonNode next = root.path("next");
            if (next != null && !next.isNull() && !next.asText().isEmpty()) {
                out = out.set("nextPage", next.asText());
            } else {
                out = out.remove("nextPage");
            }
            if (out.contains("product")) return out;
            JsonNode products = root.path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        return out.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
            return out;
        } catch (IOException error) {
            return session;
        }
    }

    private static boolean hasNext(Session session) {
        return has(session, "nextPage") && !"null".equals(session.getString("nextPage"));
    }

    private static ChainBuilder catalog() {
        return exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> selectProduct(session))
            .exec(doIf(session -> !session.contains("product") && hasNext(session)).then(
                exec(http("catalog page 2").get("#{nextPage}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200),
                        bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(session -> selectProduct(session))))
            .exec(doIf(session -> !session.contains("product") && hasNext(session)).then(
                exec(http("catalog page 3").get("#{nextPage}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200),
                        bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(session -> selectProduct(session))));
    }

    private static ChainBuilder cart() {
        return doIf(session -> session.contains("product") && session.contains("variant")).then(
            exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> {
                    StringBuilder body = new StringBuilder("{\"product_id\":\"")
                        .append(jsonEscape(session.getString("product")))
                        .append("\",\"variant_id\":\"")
                        .append(jsonEscape(session.getString("variant")))
                        .append("\"");
                    if (has(session, "grant")) {
                        body.append(",\"grant_id\":\"")
                            .append(jsonEscape(session.getString("grant")))
                            .append("\"");
                    }
                    return body.append("}").toString();
                }))
                .check(status().in(200, 201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> !has(session, "etag")).then(
                exec(http("cart read").get("/v2/carts/#{cart}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200),
                        header("ETag").saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf"))))));
    }

    private static ChainBuilder order() {
        return doIf(session -> session.contains("cart") && has(session, "etag")).then(
            exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":\"" + jsonEscape(session.getString("cart")) + "\"}"))
                .check(status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf"))));
    }

    private static ChainBuilder flow() {
        return exec(session -> session.set("journey",
                session.contains("journey") ? session.getInt("journey") + 1 : 0))
            .exec(flushCookieJar())
            .exec(login())
            .exec(pause(Duration.ofMillis(100)))
            .exec(catalog())
            .exec(cart())
            .exec(order());
    }

    public ModelSimulation() {
        setUp(scenario("partition")
            .exec(repeat(ITERATIONS).on(flow()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(MODE.equals("threshold")
                ? details("commit").responseTime().percentile3().lt(250)
                : global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}

