```js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = {
  users: Number(__ENV.USERS || 2),
  iterations: Number(__ENV.ITERATIONS || 2),
  mode: __ENV.MODE || 'partition',
  workload: __ENV.WORKLOAD,
  operation: __ENV.OPERATION,
  completion: __ENV.COMPLETION,
  path: __ENV.PATH,
  quantity: __ENV.QUANTITY ? Number(__ENV.QUANTITY) : undefined
};

const fixture = JSON.parse(open('/fixtures/accounts.json'));
const accounts = Array.isArray(fixture) ? fixture : (fixture.accounts || []);
if (!accounts.length) throw new Error('No accounts in fixture');

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '2m'
    }
  },
  thresholds: {
    checks: ['rate==1']
  }
};

const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';
let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function header(r, name) {
  const lower = String(name).toLowerCase();
  for (const k in r.headers) {
    if (String(k).toLowerCase() === lower) return r.headers[k];
  }
  return '';
}

function absolute(path) {
  const p = String(path);
  if (/^https?:\/\//i.test(p)) return p;
  return base + p;
}

function raw(path, method, data, extra) {
  method = method || 'GET';
  extra = extra || {};
  const headers = Object.assign({ 'Content-Type': 'application/json' }, extra);
  if (csrf && method !== 'GET') headers['X-CSRF-Token'] = csrf;

  const r = http.request(
    method,
    absolute(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    { headers: headers, redirects: 0, timeout: '10s' }
  );

  const b = body(r);
  if (b.csrf) csrf = b.csrf;

  const p = String(path);
  if (p === '/v2/work' || p.indexOf('/v2/work?') === 0) {
    const expected = (r.status === 401 && b.error === 'expired') || r.status === 429;
    failure.add(!(r.status === 200 && b.ok === true) && !expected);
  }

  return r;
}

function extractLoginCsrf(r) {
  const doc = r.html();
  let token = doc.find('form input[name="csrf"]').first().attr('value');
  if (!token) token = doc.find('input[name="csrf"]').first().attr('value');
  return token;
}

function accountForVu() {
  const idx = (typeof __VU === 'number' ? __VU : 1) - 1;
  if (idx < 0) return accounts[0];
  if (idx >= accounts.length) throw new Error('Insufficient exclusive accounts for VU ' + __VU);
  return accounts[idx];
}

function login() {
  csrf = '';

