function request(path, method, data, extra) {
  method = method || 'GET';
  extra = extra || {};

  let r = raw(path, method, data, extra);

  if (r.status === 401) {
    const b = body(r);
    if (b.error === 'expired' || b.error === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) {
        if (!login()) return r;
      }
      if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
      r = raw(path, method, data, extra);
    }
  }

  return r;
}

