  const products = b && b.data && b.data.products;
  if (!products) return null;

  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || !p.variants) continue;
    for (let j = 0; j < p.variants.length; j++) {
      const v = p.variants[j];
      if (v && v.in_stock) return { product: p, variant: v };
    }
  }

  return null;
}

