  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (grant) cartPayload.grant_id = grant;

  let r = request('/v2/carts', 'POST', cartPayload);
  let b = body(r);
  cart = b.id;
  let etag = header(r, 'ETag');

  if (!check(r, { 'cart': x => x.status === 201 && !!body(x).id })) return;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const acct = accountForVu();
    const qty = cfg.mode === 'data' ? (Number(acct.quantity) || 1) : (cfg.quantity || 2);
    const patch = { quantity: qty };

    r = request('/v2/carts/' + cart, 'PATCH', patch, { 'If-Match': etag });
