  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart });
    b = body(r);
    const statusUrl = b.status_url;

    if (!check(r, { 'reservation created': x => x.status === 202 && !!body(x).status_url })) return;

    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(statusUrl);
      b = body(r);
