import java.io.IOException;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final Duration PACE = Duration.ofSeconds(1);
    private static final Duration RUN = Duration.ofSeconds(40);
    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp();

    private static String username(Session session) {
        long n = Math.floorMod(session.userId() - 1, 16L) + 1;
        return "bench-" + n;
    }

    private static ChainBuilder login() {
        return exec(flushCookieJar())
            .exec(session -> session
                .set("csrf", "")
                .remove("formCsrf")
                .remove("location")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("etag")
                .remove("catalogBody")
                .remove("catalogStatus")
                .remove("renewStatus"))
            .exec(http("login form")
                .get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> {
                String html = session.getString("loginHtml");
                Matcher inputs = Pattern.compile("(?i)<input\\b[^>]*>").matcher(html);
                while (inputs.find()) {
                    String tag = inputs.group();
                    if (Pattern.compile("(?i)\\bname\\s*=\\s*['\"]?csrf['\"]?").matcher(tag).find()) {
                        Matcher value = Pattern.compile("(?i)\\bvalue\\s*=\\s*['\"]?([^'\"\\s>]+)").matcher(tag);
                        if (value.find()) {
                            return session.set("formCsrf", value.group(1));
                        }
                    }
                }
                return session;
            })
            .exec(http("login")
                .post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect")
                    .get("#{location}")
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        return session
                            .set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder catalog() {
        return exec(http("catalog")
                .get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().in(200, 401),
                    status().saveAs("catalogStatus"),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("catalogStatus") == 401).then(
                exec(http("renew")
                    .post("/v2/session/renew")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
