                .exec(http("catalog retry")
                    .get("/v2/catalog")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200),
                        bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))))
            .exec(session -> selectProduct(session));
    }

    private static ChainBuilder flow() {
        return exec(login())
            .exec(catalog())
            .exec(http("cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> "{\"product_id\":\"" + session.getString("product")
                    + "\",\"variant_id\":\"" + session.getString("variant") + "\"}"))
                .check(status().in(200, 201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("commit")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        setUp(
            scenario("journey")
                .exec(flow())
                .exec(pace(PACE))
                .injectOpen(constantUsersPerSec(1.0).during(RUN))
        ).protocols(HTTP);
    }
}
