let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function hdr(r, name) {
  const lower = name.toLowerCase();
  for (const k in r.headers) {
    if (k.toLowerCase() === lower) {
      return r.headers[k];
    }
  }
  return null;
}

function resolve(path) {
  if (!path) return path;
  if (path.indexOf('http://') === 0 || path.indexOf('https://') === 0) return path;
  if (path.charAt(0) === '/') return base + path;
  return base + '/' + path;
}

function raw(path, method, data, extra) {
  method = method || 'GET';
  const headers = { 'Content-Type': 'application/json' };
  if (csrf) headers['X-CSRF-Token'] = csrf;
  if (extra) {
    for (const k in extra) {
      headers[k] = extra[k];
    }
  }
  const r = http.request(
    method,
    resolve(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    {
      headers: headers,
      redirects: 0,
      timeout: '3s'
    }
  );
  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;
  return r;
}

function getLoginCsrf(res) {
  const html = res.html();
  if (!html) return null;

  let token = null;
  html.find('form').each(function (_, form) {
    const action = form.attr('action') || '';
    if (action.indexOf('/v2/login') >= 0) {
      const input = form.find('input[name="csrf"]').first();
      const value = input.attr('value');
      if (value) token = value;
    }
  });

  if (token) return token;
  return html.find('input[name="csrf"]').first().attr('value') || null;
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = getLoginCsrf(r);
  check(r, { 'login form': r => r.status === 200 && !!token });
