  });

  if (r.status === 302) {
    const loc = hdr(r, 'Location');
    if (loc) r = raw(loc);
  }

  check(r, { 'login': r => r.status === 200 });
}

function nextUrl(next, current) {
  if (!next) return null;
  if (next.indexOf('http://') === 0 || next.indexOf('https://') === 0) return next;
  if (next.charAt(0) === '/') return next;
  if (next.charAt(0) === '?') return current.split('?')[0] + next;

  const noQuery = current.split('?')[0];
  const dir = noQuery.substring(0, noQuery.lastIndexOf('/') + 1);
  return dir + next;
}

function request(path, method, data, extra) {
  let r = raw(path, method, data, extra);
