        self.total = max(1, int(DURATION * RATE))
        self.lock = Semaphore()

    def exhausted(self):
        with self.lock:
            return self.claimed >= self.total

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            if self.claimed >= self.total:
                return False
            slot = self.claimed / RATE
            self.claimed += 1
            deadline = self.started + slot
        sleep(max(0.0, deadline - time.monotonic()))
        return True


ARRIVALS = ArrivalPlan()
FIRST_ORDER_START = None
ACTIVE_USERS = 0
USER_COUNTER = 0
ACTIVE_LOCK = Semaphore()
USER_COUNTER_LOCK = Semaphore()


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = lambda self: 1

    def on_start(self):
