            number = USER_COUNTER
        with ACTIVE_LOCK:
            ACTIVE_USERS += 1
        self.username = "bench-%d" % (((number - 1) % 16) + 1)
        self.password = "bench"
        self.csrf = ""
        self.cart = ""
        self.etag = ""

    def on_stop(self):
        global ACTIVE_USERS
        with ACTIVE_LOCK:
            ACTIVE_USERS -= 1

    def raw(self, method, path, data=None, headers=None, name=None):
        request_headers = {"Content-Type": "application/json"}
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf
        if headers:
            request_headers.update(headers)

        kwargs = {
            "headers": request_headers,
            "name": name or path,
            "catch_response": True,
            "allow_redirects": False,
            "timeout": 3,
        }
        if data is not None:
            kwargs["json"] = data

        with self.client.request(method, path, **kwargs) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}

            error = body.get("error") if isinstance(body, dict) else None
            allowed = response.status_code < 400

            if response.status_code == 401 and error in ("expired", "session"):
                allowed = True
            if response.status_code == 412 and error in ("etag", "etag_conflict"):
                allowed = True
            if response.status_code == 429 and path.split("?", 1)[0] == "/v2/work":
                allowed = True

            if (
                method == "POST"
                and path.split("?", 1)[0] == "/v2/orders"
                and response.status_code < 400
            ):
                if not isinstance(body, dict) or body.get("accepted") is not True:
                    allowed = False

            if allowed:
                response.success()
            else:
                response.failure("%s %s -> %s" % (method, path, response.status_code))

            if isinstance(body, dict) and body.get("csrf"):
                self.csrf = body["csrf"]

            return response, body

    def request(self, method, path, data=None, headers=None, name=None):
        response = None
        body = {}
        for _ in range(2):
            current_headers = headers
            if method == "POST" and path.split("?", 1)[0] == "/v2/orders":
                current_headers = dict(headers or {})
                current_headers["Idempotency-Key"] = self.cart
                if self.etag:
                    current_headers["If-Match"] = self.etag
                else:
                    current_headers.pop("If-Match", None)

            response, body = self.raw(method, path, data, current_headers, name)

            if response.status_code == 401:
                error = body.get("error") if isinstance(body, dict) else None
                if error == "expired":
                    self.recover_expired()
                    continue
                if error == "session":
                    self.recover_session()
                    continue
            return response, body
        return response, body

    def recover_expired(self):
        renewed, body = self.raw("POST", "/v2/session/renew", {})
        if renewed.status_code == 200:
            if isinstance(body, dict) and body.get("csrf"):
                self.csrf = body["csrf"]
        else:
            self.login()
        self.recover_cart()

    def recover_session(self):
        self.login()
        self.recover_cart()

    def recover_cart(self):
        if self.cart:
            response, _ = self.raw("POST", "/v2/carts/%s/recover" % self.cart, {})
            if response.headers.get("ETag"):
                self.etag = response.headers["ETag"]

    def login(self):
        self.csrf = ""
        form, _ = self.raw("GET", "/v2/login-form")
        token = re.search(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            form.text,
            re.IGNORECASE,
        )
        if not token:
            return

        response, body = self.raw(
            "POST",
            "/v2/login",
            {
                "username": self.username,
                "password": self.password,
                "csrf": token.group(1),
            },
        )
        if response.status_code == 302:
            location = response.headers.get("Location")
            if location:
                _, body = self.raw("GET", location)

        if isinstance(body, dict) and body.get("csrf"):
            self.csrf = body["csrf"]

    def resolve_next(self, current, next_url):
        if next_url.startswith("http://") or next_url.startswith("https://"):
            parsed = urlparse(next_url)
            path = parsed.path or "/"
            if parsed.query:
                path += "?" + parsed.query
            return path
        if next_url.startswith("/"):
            return next_url
        return urljoin(current, next_url)

    def select_product(self):
        page = "/v2/catalog"
        for _ in range(3):
            response, body = self.request("GET", page)
            if response.status_code >= 400:
                return None, None

            data = body.get("data") if isinstance(body, dict) else None
            products = data.get("products", []) if isinstance(data, dict) else []

            for item in products:
                variants = item.get("variants", []) if isinstance(item, dict) else []
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if isinstance(variant, dict) and variant.get("in_stock"):
                        return item, variant

            next_url = body.get("next") if isinstance(body, dict) else None
            if not next_url:
                break
            page = self.resolve_next(page, next_url)

        return None, None

    def create_cart(self, product, variant):
        payload = {
            "product_id": product["id"],
            "variant_id": variant["id"],
        }
        response, body = self.request("POST", "/v2/carts", payload)
        self.cart = body.get("id", "") if isinstance(body, dict) else ""
        self.etag = response.headers.get("ETag", "")
        if not self.etag and isinstance(body, dict):
            self.etag = body.get("etag", "")

    def place_order(self):
        global FIRST_ORDER_START
        if not self.cart:
            return

        headers = {"Idempotency-Key": self.cart}
        if self.etag:
            headers["If-Match"] = self.etag

        start = time.monotonic()
        response, body = self.request(
            "POST",
            "/v2/orders",
            {"cart_id": self.cart},
            headers,
            name="/v2/orders",
        )

        if (
            response.status_code < 400
            and isinstance(body, dict)
            and body.get("accepted") is True
        ):
            if FIRST_ORDER_START is None:
                FIRST_ORDER_START = start

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""

        self.login()
        if not self.csrf:
            return

        product, variant = self.select_product()
        if not product:
            return

        self.create_cart(product, variant)
        if not self.cart:
            return

        self.place_order()

    @task
    def run_journey(self):
        if not ARRIVALS.next():
            raise StopUser()
        self.flow()


class ShopShape(LoadTestShape):
    def tick(self):
        now = time.monotonic()

        if FIRST_ORDER_START is None:
            if self.get_run_time() >= 15.0:
                return None
            return (MAX_VUS, MAX_VUS)

        if now >= FIRST_ORDER_START + DURATION + 5.0:
            return None

        if ARRIVALS.exhausted():
            active = ACTIVE_USERS
            if active <= 0:
                return None
            return (min(MAX_VUS, active), MAX_VUS)

        return (MAX_VUS, MAX_VUS)
