import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final HttpProtocolBuilder HTTP = http.baseUrl(System.getenv("BASE_URL"))
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String username(Session session) {
        return "bench-" + (((session.userId() - 1) % 16) + 1);
    }

    private static ChainBuilder resetSession() {
        return exec(session -> session
            .set("csrf", "")
            .set("grant", "")
            .remove("location")
            .remove("formCsrf")
            .remove("workStatus")
            .remove("workError")
            .remove("retryAfter"));
    }

    private static ChainBuilder login() {
        return resetSession()
            .exec(http("login form").get("/v2/login-form")
                .check(regex("<input(?=[^>]*(?:\\s|^)name\\s*=\\s*[\"']csrf[\"'])(?=[^>]*(?:\\s|^)value\\s*=\\s*[\"']([^\"']+)[\"'])[^>]*>")
                    .saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .disableFollowRedirect()
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().in(200, 302),
                        jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder workCall(String name) {
        return exec(http(name).post("/v2/work")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().saveAs("workStatus"),
                status().in(200, 401, 429),
                header("Retry-After").optional().saveAs("retryAfter"),
                jsonPath("$.error").optional().saveAs("workError"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder renew() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder recoverExpiry(String retryName) {
        return renew().exec(workCall(retryName));
    }

    private static ChainBuilder workOperation() {
        ChainBuilder chain = workCall("work");
        chain = chain.exec(doIf(session -> session.getInt("workStatus") == 401).then(
            recoverExpiry("work expiry retry")));

        for (int retry = 1; retry <= 4; retry++) {
            final String retryName = "work 429 retry " + retry;
            final String expiryRetryName = "work 429 expiry retry " + retry;
            chain = chain.exec(doIf(session -> session.getInt("workStatus") == 429).then(
                pause(Duration.ofSeconds(1))
                    .exec(workCall(retryName))
                    .exec(doIf(session -> session.getInt("workStatus") == 401).then(
                        recoverExpiry(expiryRetryName)))));
        }
        return chain;
    }

    public ModelSimulation() {
        setUp(scenario("matrix")
            .exec(repeat(2).on(
                exec(flushCookieJar())
                    .exec(login())
                    .exec(repeat(4).on(workOperation()))))
            .injectOpen(atOnceUsers(2)))
            .protocols(HTTP);
    }
}
