  }
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function url(path) {
  if (/^https?:\/\//.test(path)) return path;
  if (path.charAt(0) === '/') return base + path;
  return base + '/' + path;
}

function header(r, name) {
  const h = r.headers || {};
  const lower = name.toLowerCase();
  for (const k in h) {
    if (k.toLowerCase() === lower) return h[k];
  }
  return undefined;
}

function findInputValue(r, name) {
  let val = '';
  try {
    const el = r.html().find('input[name=' + name + ']').first();
    if (el) val = el.attr('value') || '';
  } catch (_) {}
  if (val) return val;
  const s = r.body || '';
  const tags = s.match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    const nameRe = new RegExp("name\\s*=\\s*(?:\"" + name + "\"|'" + name + "'|" + name + ")(?:\\s|/?>)", 'i');
    if (nameRe.test(tag)) {
      const v = tag.match(/value\s*=\s*["']([^"']*)["']/i) || tag.match(/value\s*=\s*([^\s>]+)/i);
      if (v) {
        val = v[1];
        break;
      }
    }
  }
  return val;
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = {'Content-Type': 'application/json'};
  if (csrf) headers['X-CSRF-Token'] = csrf;
  Object.assign(headers, extra);
  const r = http.request(method, url(path), data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s'
  });
  const b = body(r);
  if (b.csrf) csrf = b.csrf;
  if (method === 'POST' && path === '/v2/work') {
    let unexpected = true;
    if (r.status === 429) {
      unexpected = false;
    } else if (r.status === 401 && b.error === 'expired') {
      unexpected = false;
    } else if (r.status === 200 && b.ok === true) {
      unexpected = false;
    }
    businessFailure.add(unexpected);
  }
  return r;
}

function login() {
  csrf = '';
  grant = '';
  let r = raw('/v2/login-form');
  const token = findInputValue(r, 'csrf');
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {username: row.username, password: row.password, csrf: token});
  if (r.status === 302) {
    const loc = header(r, 'Location');
    if (loc) {
      r = raw(loc);
      const b = body(r);
      if (b.grant_id) grant = b.grant_id;
    }
  }
  check(r, {'login': r => r.status === 200});
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) {
