      }
      if (cart) {
        raw('/v2/carts/' + cart + '/recover', 'POST', {});
      }
      r = raw(path, method, data, extra);
    }
  }
  return r;
}

function work() {
  let r = request('/v2/work', 'POST', {});
  let retries = 0;
  while (r.status === 429 && retries < 4) {
    const ra = Number(header(r, 'Retry-After') || 1);
    sleep((isNaN(ra) ? 1 : ra) + 0.01);
    r = request('/v2/work', 'POST', {});
    retries++;
  }
  check(r, {'work': r => r.status === 200 && body(r).ok === true});
}

export default function () {
  csrf = '';
  cart = '';
  grant = '';
  login();
  for (let n = 0; n < 4; n++) {
    work();
  }
