import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(System.getenv("BASE_URL") == null ? "http://127.0.0.1:8000" : System.getenv("BASE_URL"))
            .disableAutoRedirect()
            .acceptHeader("application/json, text/plain, */*")
            .userAgentHeader("Gatling/ModelSimulation");

    private ChainBuilder loginChain() {
        return exec(session -> session.remove("loginStatus").remove("loginLocation"))
                .exec(http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(css("input[name=csrf]", "value").saveAs("csrf")))
                .exec(http("POST /v2/login")
                        .post("/v2/login")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{csrf}\"}"))
                        .check(status().saveAs("loginStatus"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf")))
                .doIf(session -> session.contains("loginStatus") && session.getInt("loginStatus") == 302)
                .then(
                        exec(http("GET login redirect")
                                .get("#{loginLocation}")
                                .check(status().is(200))
                                .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                                .check(css("input[name=csrf]", "value").optional().saveAs("csrf")))
                )
                .exec(session -> {
                    if (!session.contains("csrf")) {
                        return session.markAsFailed("missing csrf after login");
                    }
                    return session.set("retryCount", 0);
                });
    }

    private ChainBuilder renewChain() {
        return exec(http("POST /v2/session/renew")
                .post("/v2/session/renew")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{}"))
                .check(status().is(200))
                .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf")));
    }

    private ChainBuilder workRequest() {
        return exec(session -> session
                .remove("workStatus")
                .remove("workOk")
                .remove("workError"))
                .exec(http("POST /v2/work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{}"))
                        .check(status().saveAs("workStatus"))
                        .check(status().in(200, 401, 429))
                        .check(regex("\"ok\"\\s*:\\s*true").optional().saveAs("workOk"))
                        .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                        .check(regex("\"error\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("workError")));
    }

    private final ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> {
                long userId = session.userId();
                int idx = (int) (userId % 16);
                if (idx < 0) {
                    idx += 16;
                }
                String username = "bench-" + (idx + 1);
                return session
                        .set("username", username)
                        .set("password", "bench");
            })
            .exec(loginChain())
            .repeat(35).on(
                    pace(Duration.ofSeconds(1))
                            .exec(session -> session
                                    .set("retryCount", 0)
                                    .set("recovered", false))
                            .exec(workRequest())
                            .doWhile(session -> session.contains("workStatus")
                                    && session.getInt("workStatus") == 429
                                    && session.getInt("retryCount") < 4)
                            .on(
                                    pause(Duration.ofSeconds(1))
                                            .exec(session -> session.set("retryCount", session.getInt("retryCount") + 1))
                                            .exec(workRequest())
                            )
                            .doIf(session -> session.contains("workStatus")
                                    && session.getInt("workStatus") == 401
                                    && session.contains("workError")
                                    && "expired".equals(session.getString("workError"))
                                    && !session.getBoolean("recovered"))
                            .then(
                                    exec(session -> session.set("recovered", true))
                                            .exec(renewChain())
                                            .exec(workRequest())
                            )
                            .doIf(session -> session.contains("workStatus")
                                    && session.getInt("workStatus") == 401
                                    && session.contains("workError")
                                    && "session".equals(session.getString("workError"))
                                    && !session.getBoolean("recovered"))
                            .then(
                                    exec(session -> session.set("recovered", true))
                                            .exec(loginChain())
                                            .exec(workRequest())
                            )
                            .exec(session -> {
                                int status = session.contains("workStatus") ? session.getInt("workStatus") : -1;
                                String error = session.contains("workError") ? session.getString("workError") : null;

                                if (status == -1) {
                                    return session.markAsFailed("missing work status");
                                }
                                if (status == 200 && !session.contains("workOk")) {
                                    return session.markAsFailed("work business failure");
                                }
                                if (status == 401) {
                                    return session.markAsFailed("work unauthorized after recovery: " + error);
                                }
                                if (status == 429) {
                                    return session.markAsFailed("work 429 retries exhausted");
                                }
                                if (status >= 400) {
                                    return session.markAsFailed("unexpected work status " + status);
                                }
                                return session;
                            })
            );

    {
        setUp(scn.injectOpen(atOnceUsers(5))).protocols(httpProtocol);
    }
}
