                            .exec(workRequest())
                            .doWhile(session -> session.contains("workStatus")
                                    && session.getInt("workStatus") == 429
                                    && session.getInt("retryCount") < 4)
                            .on(
                                    pause(Duration.ofSeconds(1))
                                            .exec(session -> session.set("retryCount", session.getInt("retryCount") + 1))
                                            .exec(workRequest())
                            )
                            .doIf(session -> session.contains("workStatus")
                                    && session.getInt("workStatus") == 401
                                    && session.contains("workError")
                                    && "expired".equals(session.getString("workError"))
                                    && !session.getBoolean("recovered"))
                            .then(
