import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '35s',
      preAllocatedVUs: 2,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
  thresholds: {},
};

function extractCookies(res) {
  const cookies = [];
  if (res && res.cookies) {
    for (const name in res.cookies) {
      const arr = res.cookies[name];
      for (const c of arr) {
        if (c.value !== undefined && c.value !== null) {
          cookies.push({ name: name, value: c.value });
        }
      }
    }
  }
  return cookies;
}

function applyCookies(cookies) {
  const jar = http.cookieJar();
  for (const c of cookies) {
    jar.set(BASE_URL, c.name, c.value);
  }
}

function extractCsrf(html) {
  if (!html) return null;
  const inputRegex = /<input\b[^>]*>/gi;
  let match;
  while ((match = inputRegex.exec(html)) !== null) {
    const tag = match[0];
    const nameMatch = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (nameMatch) {
      const name = nameMatch[2] || nameMatch[3] || nameMatch[4];
      if (name === 'csrf') {
        const valueMatch = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
        if (valueMatch) {
          const val = valueMatch[2] || valueMatch[3] || valueMatch[4];
          if (val) return val;
        }
      }
    }
  }
  const fallback = html.match(/name\s*=\s*["']?csrf["']?[^>]*value\s*=\s*["']([^"']+)["']/i) ||
                   html.match(/value\s*=\s*["']([^"']+)["'][^>]*name\s*=\s*["']?csrf["']?/i);
  if (fallback) return fallback[1];
  return null;
}

function login(username, password) {
  const jar = http.cookieJar();
  jar.clear(BASE_URL);

  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'GET /v2/login-form' },
  });
  if (formRes.status >= 400) return null;

  const csrf = extractCsrf(formRes.body);
  if (!csrf) return null;

  const formCookies = extractCookies(formRes);
  applyCookies(formCookies);

  const loginPayload = JSON.stringify({ username, password, csrf });
  const loginRes = http.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'POST /v2/login' },
  });

  let allCookies = formCookies.concat(extractCookies(loginRes));
  applyCookies(extractCookies(loginRes));

  let finalRes = loginRes;
  if (loginRes.status === 302) {
    let location = loginRes.headers['Location'] || loginRes.headers['location'];
    if (location) {
      if (location.startsWith('/')) {
        location = BASE_URL + location;
      }
      const locRes = http.get(location, {
        redirects: 0,
        tags: { name: 'GET login redirect' },
      });
      allCookies = allCookies.concat(extractCookies(locRes));
      finalRes = locRes;
    }
  }

  applyCookies(allCookies);

  let csrfOut = csrf;
  try {
    const json = finalRes.json();
    if (json.csrf) csrfOut = json.csrf;
  } catch (e) {
    try {
      const json2 = loginRes.json();
      if (json2.csrf) csrfOut = json2.csrf;
    } catch (e2) {}
  }

  return { csrf: csrfOut, cookies: allCookies, user: username };
}

export function setup() {
  const data = login('bench-1', 'bench');
  if (!data) {
    throw new Error('Login failed');
  }
  return data;
}

let initialized = false;
let currentCsrf = null;

function doWorkRequest() {
  return http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf,
    },
    redirects: 0,
    tags: { name: 'POST /v2/work' },
  });
}

function updateCsrfFromResponse(res) {
  if (res && res.status < 400) {
    try {
      const j = res.json();
      if (j.csrf) currentCsrf = j.csrf;
    } catch (e) {}
  }
}

export default function (data) {
  if (!initialized) {
    applyCookies(data.cookies);
    currentCsrf = data.csrf;
    initialized = true;
  }

  let res = null;
  let retries = 0;

  while (retries <= 4) {
    res = doWorkRequest();

    if (res.status === 429) {
      const retryAfter = parseInt(
        res.headers['Retry-After'] || res.headers['retry-after'] || '1',
        10
      );
      sleep(retryAfter);
      retries++;
      continue;
    }
    break;
  }

  if (res.status === 401) {
    let errorType = null;
    try {
      const j = res.json();
      errorType = j.error;
    } catch (e) {}

    if (errorType === 'denied') {
      check(res, { 'work denied should not happen': (r) => r.status < 400 });
      return;
    }

    if (errorType === 'expired') {
      const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': currentCsrf,
        },
        redirects: 0,
        tags: { name: 'POST /v2/session/renew' },
      });

      if (renewRes.status < 400) {
        try {
          const j = renewRes.json();
          if (j.csrf) currentCsrf = j.csrf;
        } catch (e) {}
        applyCookies(extractCookies(renewRes));
        res = doWorkRequest();
      } else {
        const loginData = login(data.username, data.password);
        if (loginData) {
          currentCsrf = loginData.csrf;
          applyCookies(loginData.cookies);
          res = doWorkRequest();
        }
      }
    } else {
      const loginData = login(data.username, data.password);
      if (loginData) {
        currentCsrf = loginData.csrf;
        applyCookies(loginData.cookies);
        res = doWorkRequest();
      }
    }
  }

  updateCsrfFromResponse(res);

  check(res, {
    'work status < 400': (r) => r.status < 400,
    'work ok': (r) => {
      try {
        return r.json().ok === true;
      } catch (e) {
        return false;
      }
    },
  });
}
