import os
import re
import time
import html as html_module

from gevent import sleep as gsleep
from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

_next_user = 0
FIRST_WORK_TIME = None


def extract_csrf(html):
    if not html:
        return None
    html = re.sub(r"<!--.*?-->", "", html, flags=re.S)
    html = re.sub(r"<script\b[^>]*>.*?</script>", "", html, flags=re.S | re.I)
    html = re.sub(r"<style\b[^>]*>.*?</style>", "", html, flags=re.S | re.I)

    candidates = []
    for tag in re.finditer(r"<input\b[^>]*>", html, flags=re.I | re.S):
        attrs = {}
        for m in re.finditer(
            r"([^\s=/>]+)\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))",
            tag.group(0),
            flags=re.I | re.S,
        ):
            name = m.group(1).lower()
            val = m.group(2)
            if val is None:
                val = m.group(3)
            if val is None:
                val = m.group(4)
            attrs[name] = val

        if attrs.get("name", "").lower() == "csrf":
            val = attrs.get("value")
            if val is not None:
                val = html_module.unescape(val.strip())
            candidates.append((attrs, val))

    if not candidates:
        return None

    for attrs, val in candidates:
        if attrs.get("type", "").lower() == "hidden":
            return val
    return candidates[0][1]


def extract_error(resp):
    try:
        j = resp.json()
    except Exception:
        j = None

    if isinstance(j, dict):
        err = j.get("error")
        if isinstance(err, dict):
            err = err.get("code") or err.get("message")
        if isinstance(err, str):
            return err.lower()
        code = j.get("code")
        if isinstance(code, str):
            return code.lower()

    text = (resp.text or "").lower()
    for e in ("expired", "session", "denied"):
        if e in text:
            return e
    return None


class WorkUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        global _next_user
        self.account_index = _next_user
        _next_user += 1
        self.username = f"bench-{self.account_index % 16 + 1}"
        self.csrf = None
        self.logged_in = False
        self.iterations = 0

        for _ in range(3):
            if self.login():
                break
            gsleep(0.2)
        else:
            raise StopUser()

    def _extract_csrf_from_response(self, resp):
        try:
            j = resp.json()
        except Exception:
            j = None

        if isinstance(j, dict):
            csrf = j.get("csrf")
            if csrf:
                return csrf

        m = re.search(r'"csrf"\s*:\s*"([^"]+)"', resp.text or "")
        if m:
            return m.group(1)
        return None

    def login(self):
        self.logged_in = False

        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
            name="/v2/login-form",
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False
            csrf = extract_csrf(resp.text)
            if not csrf:
                resp.failure("login-form csrf not found")
                return False

        payload = {"username": self.username, "password": "bench", "csrf": csrf}
        status = None
        loc = None

        with self.client.post(
            "/v2/login",
            json=payload,
            catch_response=True,
            allow_redirects=False,
            name="/v2/login",
        ) as resp:
            status = resp.status_code
            if status == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("login 302 missing Location")
                    return False
            elif status >= 400:
                resp.failure(f"login status {status}")
                return False
            else:
                new_csrf = self._extract_csrf_from_response(resp)
                if not new_csrf:
                    resp.failure("login no csrf")
                    return False
                self.csrf = new_csrf
                self.logged_in = True
                return True

        if status == 302 and loc:
            with self.client.get(
                loc,
                catch_response=True,
                allow_redirects=False,
                name="/v2/login-location",
            ) as resp2:
                if resp2.status_code >= 400:
                    resp2.failure(f"login-location status {resp2.status_code}")
                    return False
                new_csrf = self._extract_csrf_from_response(resp2)
                if not new_csrf:
                    resp2.failure("login-location no csrf")
                    return False
                self.csrf = new_csrf
                self.logged_in = True
                return True

        return False

    def renew(self):
        if not self.csrf:
            return self.login()

        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
            name="/v2/session/renew",
        ) as resp:
            if resp.status_code == 401:
                return False
            if resp.status_code >= 400:
                resp.failure(f"renew status {resp.status_code}")
                return False

            new_csrf = self._extract_csrf_from_response(resp)
            if not new_csrf:
                resp.failure("renew no csrf")
                return False
            self.csrf = new_csrf
            return True

    def do_work(self):
        global FIRST_WORK_TIME
        retries_429 = 0
        recovered = False

        while True:
            if not self.csrf or not self.logged_in:
                if not self.login():
                    return False

            headers = {"X-CSRF-Token": self.csrf}
            req_start = time.monotonic()
            status = None
            err = None
            retry_after = 1.0

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                catch_response=True,
                allow_redirects=False,
                name="/v2/work",
            ) as resp:
                status = resp.status_code

                if status == 401:
                    err = extract_error(resp)
                    if err == "denied":
                        resp.failure("401 denied")
                        return False
                    elif err in ("expired", "session") and not recovered:
                        resp.success()
                    else:
                        resp.failure(f"401 {err}")
                        return False

                elif status == 429:
                    resp.success()
                    h = resp.headers.get("Retry-After")
                    if h:
                        try:
                            retry_after = float(h)
                        except Exception:
                            pass

                elif status >= 400:
                    resp.failure(f"work status {status}")
                    return False

                else:
                    try:
                        j = resp.json()
                    except Exception:
                        resp.failure("work invalid json")
                        return False

                    if not (isinstance(j, dict) and j.get("ok") is True):
                        resp.failure("work ok not true")
                        return False

                    new_csrf = j.get("csrf")
                    if new_csrf:
                        self.csrf = new_csrf

                    if FIRST_WORK_TIME is None:
                        FIRST_WORK_TIME = req_start

                    resp.success()
                    return True

            if status == 401:
                if err == "expired" and not recovered:
                    if self.renew():
                        recovered = True
                        continue
                    if self.login():
                        recovered = True
                        continue
                    return False

                elif err == "session" and not recovered:
                    if self.login():
                        recovered = True
                        continue
                    return False

                return False

            if status == 429:
                if retries_429 < 4:
                    gsleep(max(0.0, retry_after))
                    retries_429 += 1
                    continue
                return False

            return False

    @task
    def work_loop(self):
        phase = (self.account_index % 5) * 0.2
        next_time = time.monotonic() + phase

        while True:
            now = time.monotonic()
            if next_time > now:
                gsleep(next_time - now)

            if self.iterations >= 100:
                raise StopUser()

            self.do_work()
            self.iterations += 1
            next_time += 1.0

            now = time.monotonic()
            if next_time <= now:
                next_time = now + 0.1


class WorkShape(LoadTestShape):
    def tick(self):
        now = time.monotonic()

        if FIRST_WORK_TIME is None:
            if self.get_run_time() > 60:
                return None
            return (5, 10)

        if now - FIRST_WORK_TIME >= 36:
            return None

        return (5, 10)
