                                .check(status().is(200))
                                .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                                .check(css("input[name='csrf']", "value").optional().saveAs("csrf"))
                        )
                );
    }

    private ChainBuilder workRequest() {
        return exec(http("work")
                .post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}")).asJson()
                .check(status().in(200, 401, 429).saveAs("workStatus"))
                .check(jsonPath("$.ok").optional().is(true))
                .check(regex("\"error\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("workError"))
                .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
        );
    }

    private final ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> {
                long id = (session.userId() % 16L) + 1L;
                return session
                        .set("username", "bench-" + id)
                        .set("password", "bench");
            })
            .exec(loginChain())
            .exitHereIfFailed()
            .exec(session -> session
                    .set("workAttempt", 0)
                    .set("workDone", false)
                    .set("workFailed", false)
                    .remove("workStatus")
                    .remove("workError")
            )
            .asLongAs(
                    session -> !session.getBoolean("workDone")
                            && !session.getBoolean("workFailed")
                            && session.getInt("workAttempt") < 5,
                    "workLoop"
            ).on(
                    exec(session -> session.set("workAttempt", session.getInt("workAttempt") + 1)),
                    exec(workRequest()),
                    exitHereIfFailed(),
                    doIf(session -> session.getInt("workStatus") == 200).then(
                            exec(session -> session.set("workDone", true))
                    ),
                    doIf(session -> session.getInt("workStatus") == 429).then(
                            pause(1)
                    ),
                    doIf(session -> session.getInt("workStatus") == 401
                            && "expired".equals(session.getString("workError"))).then(
                            exec(http("renew")
                                    .post("/v2/session/renew")
                                    .header("Content-Type", "application/json")
                                    .header("X-CSRF-Token", "#{csrf}")
                                    .body(StringBody("{}")).asJson()
                                    .check(status().is(200))
                                    .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                            ),
                            exitHereIfFailed()
                    ),
                    doIf(session -> session.getInt("workStatus") == 401
                            && !"expired".equals(session.getString("workError"))).then(
                            exec(loginChain()),
                            exitHereIfFailed()
                    )
            )
            .doIf(session -> !session.getBoolean("workDone")).then(
                    exec(session -> {
                        throw new RuntimeException("work not completed");
                    })
            );

    public ModelSimulation() {
        setUp(
                scn.injectOpen(constantUsersPerSec(5).during(40))
        ).protocols(httpProtocol);
    }
}
