import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

const workStarts = new Counter('work_starts');
const workSuccess = new Rate('work_success');
const businessFailure = new Rate('business_failure_rate');

const state = {
  loggedIn: false,
  csrf: '',
  username: ''
};

export const options = {
  scenarios: {
    workload: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: 10,
      maxVUs: 24,
      gracefulStop: '5s',
      tags: { scenario: 'workload' }
    }
  },
  discardResponseBodies: false
};

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  const lower = name.toLowerCase();
  for (const k in res.headers) {
    if (k.toLowerCase() === lower) return res.headers[k];
  }
  return null;
}

function resolveUrl(loc) {
  if (loc.startsWith('//')) {
    const slash = loc.indexOf('/', 2);
    return BASE_URL + (slash >= 0 ? loc.slice(slash) : '/');
  }
  if (loc.startsWith('http://') || loc.startsWith('https://')) {
    const doubleSlash = loc.indexOf('//');
    const pathStart = loc.indexOf('/', doubleSlash + 2);
    return BASE_URL + (pathStart >= 0 ? loc.slice(pathStart) : '/');
  }
  if (loc.startsWith('/')) return BASE_URL + loc;
  return BASE_URL + '/' + loc;
}

function getAttr(tag, attr) {
  const re = new RegExp('\\b' + attr + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  if (m[3] !== undefined) return m[3];
  return null;
}

function extractCsrf(html) {
  if (!html) return null;
  const s = html
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '');

  const inputRe = /<input\b[^>]*>/gi;
  let fallback = null;
  let m;
  while ((m = inputRe.exec(s)) !== null) {
    const tag = m[0];
    const name = getAttr(tag, 'name');
    if (name && name.toLowerCase() === 'csrf') {
      const val = getAttr(tag, 'value');
      if (val !== null) {
        const type = getAttr(tag, 'type');
        if (type && type.toLowerCase() === 'hidden') return val;
        if (fallback === null) fallback = val;
      }
    }
  }
  return fallback;
}

function login() {
  state.loggedIn = false;

  const formRes = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  check(formRes, {
    'login form status is 200': (r) => r.status === 200
  });

  if (formRes.status !== 200) return false;

  const formCsrf = extractCsrf(formRes.body);
  if (!formCsrf) {
    check(false, {
      'login form contains csrf': (v) => v
    });
    return false;
  }

  const payload = JSON.stringify({
    username: state.username,
    password: 'bench',
    csrf: formCsrf
  });

  let loginRes = http.post(BASE_URL + '/v2/login', payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  let finalRes = loginRes;

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loginRes, {
      'login redirect has location': () => !!loc
    });

    if (!loc) return false;

    finalRes = http.get(resolveUrl(loc), {
      redirects: 0,
      tags: { name: 'login_location' }
    });
  }

  check(finalRes, {
    'login final status < 400': (r) => r.status < 400
  });

  if (finalRes.status >= 400) return false;

  const data = safeJson(finalRes) || safeJson(loginRes);
  let csrf = data && data.csrf ? data.csrf : null;

  if (!csrf) {
    csrf = extractCsrf(finalRes.body) || extractCsrf(loginRes.body);
  }

  if (!csrf) {
    check(false, {
      'login returned csrf': (v) => v
    });
    return false;
  }

  state.csrf = csrf;
  state.loggedIn = true;
  return true;
}

function renewSession() {
  const res = http.post(BASE_URL + '/v2/session/renew', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    tags: { name: 'renew' }
  });

  if (res.status < 400) {
    const data = safeJson(res);
    if (data && data.csrf) state.csrf = data.csrf;
    return true;
  }

  return false;
}

function recordRawWork(res, data) {
  let unexpected = false;

  if (res.status >= 500) {
    unexpected = true;
  } else if (res.status === 429) {
    unexpected = false;
  } else if (res.status === 401) {
    const err = data && data.error;
    if (err !== 'expired') unexpected = true;
  } else if (res.status >= 400) {
    unexpected = true;
  }

  businessFailure.add(unexpected);

  if (data && data.csrf) {
    state.csrf = data.csrf;
  }
}

function finalizeWork(res, data) {
  if (data && data.csrf) {
    state.csrf = data.csrf;
  }

  const success = res.status === 200 && data && data.ok === true;

  workSuccess.add(success);
  if (success) workStarts.add(1);

  check(res, {
    'work status is 200': (r) => r.status === 200,
    'work ok true': () => !!(data && data.ok === true)
  });
}

function doWork() {
  if (!state.username) {
    state.username = 'bench-' + (((__VU - 1) % 16) + 1);
  }

  if (!state.loggedIn) {
    if (!login()) {
      if (!login()) return;
    }
  }

  let scheduledRetries = 0;
  let authRetryUsed = false;

  while (true) {
    const res = http.post(BASE_URL + '/v2/work', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf
      },
      tags: { name: 'work' }
    });

    const data = safeJson(res);
    recordRawWork(res, data);

    if (res.status === 401) {
      const err = data && data.error;

      if (err === 'denied') {
        check(res, {
          'work 401 denied is not expiry': () => false
        });
        finalizeWork(res, data);
        return;
      }

      if (!authRetryUsed) {
        authRetryUsed = true;

        if (err === 'expired') {
          const renewed = renewSession();
          if (renewed) {
            continue;
          }
        }

        state.loggedIn = false;
        if (!login()) {
          finalizeWork(res, data);
          return;
        }
        continue;
      }

      check(res, {
        'work auth after retry': () => false
      });
      finalizeWork(res, data);
      return;
    }

    if (res.status === 429) {
      if (scheduledRetries < 4) {
        let retryAfter = getHeader(res, 'Retry-After');
        let seconds = parseFloat(retryAfter);
        if (!isFinite(seconds) || seconds < 0) seconds = 1;
        sleep(seconds * 1000);
        scheduledRetries++;
        continue;
      }

      check(res, {
        'work scheduled retries exhausted': () => false
      });
      finalizeWork(res, data);
      return;
    }

    finalizeWork(res, data);
    return;
  }
}

export default function () {
  doWork();
}
