import os
import re
import time
import itertools
from urllib.parse import urlsplit

import gevent
from gevent.lock import Semaphore

from locust import HttpUser, task, constant, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
TARGET_RATE = 5.0
WORK_INTERVAL = 1.0 / TARGET_RATE
MAX_429_RETRIES = 4
USER_COUNT = 8

FIRST_WORK_MONOTONIC = None
_rate_lock = Semaphore(1)
_next_slot = None
_account_seq = itertools.count(1)
_shape_start = None

_INPUT_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
_ATTR_RE = re.compile(
    r'([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))',
    re.S,
)


def next_username():
    n = next(_account_seq) - 1
    idx = n % 17
    if idx == 16:
        return "bench"
    return "bench-%d" % (idx + 1)


def normalize_location(loc):
    if not loc:
        return loc
    parts = urlsplit(loc)
    if parts.scheme or parts.netloc:
        path = parts.path or "/"
        if parts.query:
            path += "?" + parts.query
        return path
    return loc


def extract_csrf(html):
    if not html:
        return None
    for tag in _INPUT_RE.findall(html):
        attrs = {}
        for m in _ATTR_RE.finditer(tag):
            name = m.group(1).lower()
            if m.group(2) is not None:
                value = m.group(2)
            elif m.group(3) is not None:
                value = m.group(3)
            else:
                value = m.group(4)
                if value.endswith("/") and tag.rstrip().endswith("/>"):
                    value = value[:-1]
            attrs[name] = value
        if attrs.get("name") == "csrf":
            return attrs.get("value")
    return None


def rate_wait():
    global _next_slot
    with _rate_lock:
        now = time.monotonic()
        if _next_slot is None:
            _next_slot = now
        target = max(now, _next_slot)
        _next_slot = target + WORK_INTERVAL
    if target > now:
        gevent.sleep(target - now)


def mark_first_work():
    global FIRST_WORK_MONOTONIC
    if FIRST_WORK_MONOTONIC is None:
        FIRST_WORK_MONOTONIC = time.monotonic()


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = next_username()
        self.csrf = None

    @task
    def work_loop(self):
        if not self.csrf:
            if not self.ensure_login(attempts=5):
                raise StopUser()
        rate_wait()
        self.do_work()

    def _csrf_from_response(self, resp):
        try:
            data = resp.json()
        except Exception:
            return None
        if isinstance(data, dict):
            token = data.get("csrf")
            if isinstance(token, str) and token:
                return token
        return None

    def ensure_login(self, attempts=5):
        for _ in range(attempts):
            self.csrf = None
            if self._try_login():
                return True
            gevent.sleep(0.2)
        return False

    def _try_login(self):
        resp = self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
            allow_redirects=False,
        )
        if resp.status_code != 200:
            resp.failure("login form status %s" % resp.status_code)
            return False
        csrf = extract_csrf(resp.text)
        if not csrf:
            resp.failure("csrf not found in login form")
            return False
        resp.success()

        payload = {
            "username": self.username,
            "password": "bench",
            "csrf": csrf,
        }
        post = self.client.post(
            "/v2/login",
            json=payload,
            catch_response=True,
            name="/v2/login",
            allow_redirects=False,
        )

        if 300 <= post.status_code < 400:
            location = post.headers.get("Location")
            post_text = post.text
            if not location:
                post.failure("login redirect missing Location")
                return False
            post.success()

            loc_path = normalize_location(location)
            redirect_resp = self.client.get(
                loc_path,
                catch_response=True,
                name="/v2/login-redirect",
                allow_redirects=False,
            )
            if redirect_resp.status_code >= 400:
                redirect_resp.failure(
                    "login redirect status %s" % redirect_resp.status_code
                )
                return False

            token = self._csrf_from_response(redirect_resp)
            if not token:
                token = extract_csrf(redirect_resp.text)
            if not token:
                token = extract_csrf(post_text)
            if not token:
                try:
                    data = post.json()
                except Exception:
                    data = None
                if isinstance(data, dict) and isinstance(data.get("csrf"), str):
                    token = data["csrf"]

            if token:
                self.csrf = token
                redirect_resp.success()
                return True

            redirect_resp.failure("login redirect missing csrf")
            return False

        if post.status_code >= 400:
            post.failure("login status %s" % post.status_code)
            return False

        token = self._csrf_from_response(post)
        if not token:
            token = extract_csrf(post.text)
        if not token:
            post.failure("login response missing csrf")
            return False

        self.csrf = token
        post.success()
        return True

    def recover(self, error):
        if error == "expired" and self.csrf:
            renew = self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                name="/v2/session/renew",
                allow_redirects=False,
            )
            if renew.status_code < 400:
                token = self._csrf_from_response(renew)
                if token:
                    self.csrf = token
                renew.success()
                return True
            if renew.status_code == 401:
                renew.success()
            else:
                renew.failure("renew status %s" % renew.status_code)

        return self.ensure_login(attempts=5)

    def do_work(self):
        retries_429 = 0
        retried_401 = False

        while True:
            mark_first_work()
            headers = {"X-CSRF-Token": self.csrf}
            action = None
            recover_error = None
            sleep_delay = 0.0

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                catch_response=True,
                name="/v2/work",
                allow_redirects=False,
            ) as resp:
                if resp.status_code == 429:
                    try:
                        sleep_delay = float(resp.headers.get("Retry-After", "1"))
                    except Exception:
                        sleep_delay = 1.0
                    resp.success()
                    if retries_429 >= MAX_429_RETRIES:
                        return False
                    retries_429 += 1
                    action = "retry429"

                elif resp.status_code == 401:
                    try:
                        error = resp.json().get("error", "")
                    except Exception:
                        error = ""
                    if error in ("expired", "session"):
                        resp.success()
                        if retried_401:
                            resp.failure("401 after recovery retry")
                            return False
                        retried_401 = True
                        recover_error = error
                        action = "retry401"
                    else:
                        resp.failure("401 %s" % error)
                        return False

                elif resp.status_code == 500:
                    resp.failure("unexpected 500")
                    return False

                elif resp.status_code >= 400:
                    resp.failure("unexpected status %s" % resp.status_code)
                    return False

                elif resp.status_code == 200:
                    try:
                        data = resp.json()
                    except Exception:
                        resp.failure("invalid JSON")
                        return False
                    if data.get("ok") is True:
                        resp.success()
                        token = data.get("csrf")
                        if isinstance(token, str) and token:
                            self.csrf = token
                        return True
                    resp.failure("work response ok is not true")
                    return False

                else:
                    resp.failure("unexpected status %s" % resp.status_code)
                    return False

            if action == "retry429":
                gevent.sleep(max(0.05, sleep_delay))
                continue

            if action == "retry401":
                if not self.recover(recover_error):
                    return False
                continue

            return False


class WorkloadShape(LoadTestShape):
    def tick(self):
        global _shape_start
        now = time.monotonic()
        if _shape_start is None:
            _shape_start = now

        if FIRST_WORK_MONOTONIC is None:
            if now - _shape_start > 15.0:
                return None
            return (USER_COUNT, USER_COUNT)

        if now - FIRST_WORK_MONOTONIC >= 39.5:
            return None

        return (USER_COUNT, USER_COUNT)

