import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
    public ModelSimulation() {
        String baseUrl = System.getenv("BASE_URL");
        if (baseUrl == null) {
            baseUrl = "http://127.0.0.1:8000";
        }

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableFollowRedirect()
            .acceptHeader("application/json,text/html")
            .contentTypeHeader("application/json");

        ScenarioBuilder scn = scenario("ModelSimulation")
            .exec(session -> {
                int id = (session.userId().hashCode() & Integer.MAX_VALUE) % 17;
                String username = id == 16 ? "bench" : "bench-" + (id + 1);
                return session.set("username", username);
            })
            .exec(http("login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name='csrf']", "value").saveAs("csrf"))
            )
            .exec(http("login")
                .post("/v2/login")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}")).asJson()
                .check(status().saveAs("loginStatus"))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(checkIf(session -> session.getInt("loginStatus") == 200).then(
                    jsonPath("$.csrf").saveAs("csrf")
                ))
            )
            .doIf(session -> session.contains("loginLocation")).then(
                exec(http("login-redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200))
                )
            )
            .exec(session -> session.set("workRetry", true).set("workAttempts", 0))
            .asLongAs(session -> session.getBoolean("workRetry") && session.getInt("workAttempts") < 5).on(
                exec(session -> session.set("workAttempts", session.getInt("workAttempts") + 1))
                .exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}")).asJson()
                    .check(status().saveAs("workStatus"))
                    .check(status().in(200, 401, 429))
                    .check(checkIf(session -> session.getInt("workStatus") == 200).then(
                        jsonPath("$.ok").is(true)
                    ))
                    .check(checkIf(session -> session.getInt("workStatus") == 401).then(
                        jsonPath("$.error").saveAs("workError")
                    ))
                    .check(checkIf(session -> session.getInt("workStatus") == 401).then(
                        jsonPath("$.error").is("expired")
                    ))
                )
                .exec(session -> {
                    int status = session.getInt("workStatus");
                    boolean needRetry = false;
                    if (status == 429) {
                        needRetry = true;
                    } else if (status == 401 && "expired".equals(session.getString("workError"))) {
                        needRetry = true;
                    }
                    return session.set("workRetry", needRetry);
                })
                .doIf(session -> session.getInt("workStatus") == 429).then(
                    pause(Duration.ofSeconds(1))
                )
                .doIf(session -> session.getInt("workStatus") == 401 && "expired".equals(session.getString("workError"))).then(
                    exec(http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}")).asJson()
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").saveAs("csrf"))
                    )
                )
            );

        setUp(
            scn.injectOpen(constantUsersPerSec(8).during(Duration.ofSeconds(40)))
        ).protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(60));
    }
}
