                .check(css("input[name='csrf']", "value").find(0).saveAs("csrf"))
            )
            .exec(http("login")
                .post("/v2/login")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}")).asJson()
                .check(status().saveAs("loginStatus"))
                .check(status().in(200, 302))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            )
            .doIf(session -> session.getString("loginLocation") != null).then(
                exec(http("login-redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").saveAs("csrf"))
                )
            )
            .exec(session -> session
                .set("workRetry", true)
                .set("workAttempts", 0)
                .set("renewCount", 0)
                .set("needRenew", false)
            )
            .asLongAs(session -> session.getBoolean("workRetry") && session.getInt("workAttempts") < 5).on(
                exec(session -> session.set("workAttempts", session.getInt("workAttempts") + 1))
                .exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}")).asJson()
                    .check(status().saveAs("workStatus"))
                    .check(status().in(200, 401, 429))
                    .check(jsonPath("$.error").optional().saveAs("workError"))
                    .check(jsonPath("$.ok").optional().saveAs("workOk"))
                )
                .exec(session -> {
                    int status = session.getInt("workStatus");
                    String error = session.getString("workError");
                    int attempts = session.getInt("workAttempts");
                    int renews = session.getInt("renewCount");
                    boolean retry = false;
                    boolean needRenew = false;

                    if (status == 200) {
                        Object ok = session.get("workOk");
                        if (!Boolean.TRUE.equals(ok)) {
                            return session.markAsFailed().set("workRetry", false).set("needRenew", false);
                        }
                        retry = false;
                    } else if (status == 429) {
                        retry = attempts < 5;
                    } else if (status == 401 && "expired".equals(error)) {
                        if (renews == 0 && attempts < 5) {
                            retry = true;
                            needRenew = true;
                        } else {
                            retry = false;
                        }
                    } else if (status == 401) {
                        return session.markAsFailed().set("workRetry", false).set("needRenew", false);
                    } else if (status >= 500) {
                        return session.markAsFailed().set("workRetry", false).set("needRenew", false);
                    } else {
                        return session.markAsFailed().set("workRetry", false).set("needRenew", false);
                    }

                    return session.set("workRetry", retry).set("needRenew", needRenew);
                })
                .doIf(session -> session.getBoolean("needRenew")).then(
                    exec(http("renew")
                        .post("/v2/session/renew")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}")).asJson()
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").saveAs("csrf"))
                    )
                    .exec(session -> session
                        .set("renewCount", session.getInt("renewCount") + 1)
                        .set("needRenew", false)
                    )
                )
                .doIf(session -> session.getInt("workStatus") == 429).then(
                    pause(Duration.ofSeconds(1))
                )
            );

        setUp(
            scn.injectOpen(constantUsersPerSec(8).during(Duration.ofSeconds(36)))
        ).protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(45));
    }
}
