import http from 'k6/http';
import { sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 8,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 17,
      maxVUs: 32,
      gracefulStop: '0s',
      tags: { scenario: 'work' },
    },
  },
};

let sessionReady = false;
let csrfToken = null;

function getAccount() {
  const accounts = [];
  for (let i = 1; i <= 16; i++) accounts.push(`bench-${i}`);
  accounts.push('bench');
  const idx = (__VU - 1) % accounts.length;
  return accounts[idx];
}

function getAttr(tag, name) {
  const re = new RegExp(`\\b${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const m = tag.match(re);
  if (!m) return null;
  return m[1] !== undefined ? m[1] : m[2] !== undefined ? m[2] : m[3];
}

function extractCsrf(html) {
  if (!html) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  const candidates = [];
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const name = getAttr(tag, 'name');
    if (name && name.toLowerCase() === 'csrf') {
      const value = getAttr(tag, 'value');
      if (value) {
        const type = getAttr(tag, 'type');
        candidates.push({ value, type: (type || '').toLowerCase() });
      }
    }
  }
  if (candidates.length > 0) {
    const hidden = candidates.find(c => c.type === 'hidden');
    if (hidden) return hidden.value;
    return candidates[0].value;
  }
  let re = /name\s*=\s*["']?csrf["']?[^>]*value\s*=\s*["']?([^"'>\s]+)/i;
  let mm = html.match(re);
  if (mm) return mm[1];
  re = /value\s*=\s*["']?([^"'>\s]+)["']?[^>]*name\s*=\s*["']?csrf["']?/i;
  mm = html.match(re);
  if (mm) return mm[1];
  return null;
}

function login() {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  const formCsrf = extractCsrf(formRes.body);
  if (!formCsrf) {
    throw new Error('No CSRF token in login form');
  }
  const account = getAccount();
  const payload = JSON.stringify({ username: account, password: 'bench', csrf: formCsrf });
  let loginRes = http.post(`${BASE_URL}/v2/login`, payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  let loginBody = loginRes.body;
  let loginStatus = loginRes.status;
  if (loginStatus >= 300 && loginStatus < 400) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (loc) {
      const url = loc.startsWith('http') ? loc : `${BASE_URL}${loc.startsWith('/') ? '' : '/'}${loc}`;
      const getRes = http.get(url, {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      loginBody = getRes.body;
      loginStatus = getRes.status;
    }
  }
  let data = null;
  try {
    data = JSON.parse(loginBody);
  } catch (e) {}
  let newCsrf = data && data.csrf;
  if (!newCsrf) {
    newCsrf = extractCsrf(loginBody);
  }
  if (!newCsrf) {
    throw new Error(`Login failed to return CSRF, status=${loginStatus}`);
  }
  csrfToken = newCsrf;
  sessionReady = true;
  return true;
}

function safeLogin() {
  for (let i = 0; i < 3; i++) {
    try {
      login();
      return true;
    } catch (e) {
      sleep(0.1);
    }
  }
  return false;
}

function renewSession() {
  if (!csrfToken) return false;
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrfToken,
    },
    tags: { name: 'renew' },
  });
  let data = null;
  try {
    data = JSON.parse(res.body);
  } catch (e) {}
  if (res.status < 400 && data && data.csrf) {
    csrfToken = data.csrf;
    return true;
  }
  return false;
}

function sendWork() {
  const res = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrfToken,
    },
    tags: { name: 'work' },
  });
  let data = null;
  try {
    data = JSON.parse(res.body);
  } catch (e) {}
  const ok = data && data.ok === true;
  return { res, status: res.status, data, ok };
}

function doWork() {
  if (!sessionReady) {
    if (!safeLogin()) {
      return false;
    }
  }
  let scheduledRetries = 0;
  let expiryRetried = false;
  let revokedRetried = false;

  while (true) {
    const { res, status, data, ok } = sendWork();

    let isExpectedExpiry = false;
    let isScheduled429 = false;
    if (status === 429) {
      isScheduled429 = true;
    } else if (status === 401 && data && data.error === 'expired') {
      isExpectedExpiry = true;
    }
    const isUnexpectedFailure = !(status < 400 && ok) && !isExpectedExpiry && !isScheduled429;
    businessFailure.add(isUnexpectedFailure);

    if (status < 400 && ok) {
      if (data && data.csrf) {
        csrfToken = data.csrf;
      }
      return true;
    }

    if (status === 429 && isScheduled429) {
      if (scheduledRetries >= 4) {
        return false;
      }
      scheduledRetries++;
      sleep(1);
      continue;
    }

    if (status === 401 && data) {
      if (data.error === 'expired') {
        if (expiryRetried) {
          return false;
        }
        expiryRetried = true;
        if (!renewSession()) {
          sessionReady = false;
          if (!safeLogin()) {
            return false;
          }
        }
        continue;
      } else if (data.error === 'session') {
        if (revokedRetried) {
          return false;
        }
        revokedRetried = true;
        sessionReady = false;
        if (!safeLogin()) {
          return false;
        }
        continue;
      } else if (data.error === 'denied') {
        return false;
      }
    }

    return false;
  }
}

export default function () {
  doWork();
}
