import os
import time
from html.parser import HTMLParser

from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tokens = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        d = {}
        for k, v in attrs:
            if k:
                d[k.lower()] = v if v is not None else ""
        if d.get("name", "").lower() == "csrf":
            val = d.get("value", "").strip()
            if val:
                self.tokens.append(val)


def extract_csrf_tokens(html):
    p = CsrfParser()
    try:
        p.feed(html)
    except Exception:
        pass
    return p.tokens


class Pacing:
    rate = 8.0
    start_time = None
    stop_time = None
    next_slot = None
    bootstrap_claimed = False

    @classmethod
    def claim_bootstrap(cls):
        if cls.start_time is not None:
            return False
        if cls.bootstrap_claimed:
            return False
        cls.bootstrap_claimed = True
        return True

    @classmethod
    def release_bootstrap(cls):
        cls.bootstrap_claimed = False

    @classmethod
    def set_start(cls, t):
        if cls.start_time is None:
            cls.start_time = t
            cls.stop_time = t + 35.0
            cls.next_slot = t + 1.0 / cls.rate
            cls.bootstrap_claimed = False

    @classmethod
    def get_slot(cls):
        if cls.start_time is None:
            return None
        if cls.next_slot is None:
            cls.next_slot = cls.start_time + 1.0 / cls.rate
        now = time.time()
        slot = cls.next_slot
        if slot < now - 0.5:
            slot = now
            cls.next_slot = slot + 1.0 / cls.rate
        else:
            cls.next_slot += 1.0 / cls.rate
        if slot >= cls.stop_time:
            return None
        return slot


class UserCounter:
    value = 0

    @classmethod
    def next(cls):
        cls.value += 1
        return cls.value


class WorkUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        if Pacing.stop_time is not None and time.time() > Pacing.stop_time:
            raise StopUser()
        n = UserCounter.next()
        self.username = f"bench-{((n - 1) % 16) + 1}"
        self.csrf = None
        self.last_work_start = None
        if not self.login():
            raise StopUser()

    def login(self):
        for attempt in range(3):
            csrf_tokens = []
            with self.client.get(
                "/v2/login-form",
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                if resp.status_code >= 400:
                    resp.failure(f"login-form status {resp.status_code}")
                    time.sleep(0.1)
                    continue
                csrf_tokens = extract_csrf_tokens(resp.text)
                if not csrf_tokens:
                    resp.failure("no csrf in login-form")
                    time.sleep(0.1)
                    continue
                resp.success()

            csrf = csrf_tokens[0]
            self.csrf = csrf
            location = None
            login_data = None

            with self.client.post(
                "/v2/login",
                json={"username": self.username, "password": "bench", "csrf": csrf},
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                status = resp.status_code
                if status == 302:
                    location = resp.headers.get("Location")
                    resp.success()
                elif status < 400:
                    try:
                        login_data = resp.json()
                    except Exception:
                        resp.failure("login invalid json")
                        time.sleep(0.1)
                        continue
                    resp.success()
                else:
                    resp.failure(f"login status {status}")
                    time.sleep(0.1)
                    continue

            if location:
                with self.client.get(
                    location,
                    allow_redirects=False,
                    catch_response=True,
                ) as resp2:
                    if resp2.status_code >= 400:
                        resp2.failure(f"login location status {resp2.status_code}")
                        time.sleep(0.1)
                        continue
                    try:
                        login_data = resp2.json()
                    except Exception:
                        resp2.failure("login location invalid json")
                        time.sleep(0.1)
                        continue
                    resp2.success()

            if login_data:
                if login_data.get("csrf"):
                    self.csrf = login_data["csrf"]
                if login_data.get("user") is not None or login_data.get("csrf"):
                    return True

            time.sleep(0.1)

        return False

    def renew(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            catch_response=True,
        ) as resp:
            if resp.status_code < 400:
                try:
                    data = resp.json()
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                resp.success()
                return True
            else:
                resp.failure(f"renew status {resp.status_code}")
                return False

    def do_work(self, allow_recovery=True, retries_429=0):
        while True:
            start_ts = time.time()
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf
            action = None
            delay = 0.0

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                catch_response=True,
            ) as resp:
                status = resp.status_code
                if status == 200:
                    try:
                        data = resp.json()
                    except Exception:
                        resp.failure("work invalid json")
                        return False
                    if data.get("ok") is True:
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        self.last_work_start = start_ts
                        resp.success()
                        return True
                    else:
                        resp.failure(f"work not ok: {data}")
                        return False
                elif status == 429:
                    resp.success()
                    if retries_429 < 4:
                        ra = resp.headers.get("Retry-After", "1")
                        try:
                            delay = float(ra)
                        except Exception:
                            delay = 1.0
                        action = "retry_429"
                    else:
                        return False
                elif status == 401:
                    err = None
                    try:
                        err = resp.json().get("error")
                    except Exception:
                        pass
                    if err == "expired":
                        resp.success()
                        action = "renew"
                    elif err == "session":
                        resp.success()
                        action = "relogin"
                    elif err == "denied":
                        resp.failure("401 denied")
                        return False
                    else:
                        resp.failure(f"401 {err}")
                        return False
                elif status < 400:
                    try:
                        data = resp.json()
                    except Exception:
                        resp.failure("work invalid json")
                        return False
                    if data.get("ok") is True:
                        if data.get("csrf"):
                            self.csrf = data["csrf"]
                        self.last_work_start = start_ts
                        resp.success()
                        return True
                    else:
                        resp.failure(f"work not ok: {data}")
                        return False
                else:
                    resp.failure(f"unexpected status {status}")
                    return False

            if action == "retry_429":
                time.sleep(max(0.05, delay))
                retries_429 += 1
                continue
            elif action == "renew":
                if not allow_recovery:
                    return False
                if not self.renew():
                    return False
                allow_recovery = False
                continue
            elif action == "relogin":
                if not allow_recovery:
                    return False
                if not self.login():
                    return False
                allow_recovery = False
                continue
            else:
                return False

    @task
    def work_loop(self):
        while True:
            if Pacing.start_time is None:
                if Pacing.claim_bootstrap():
                    ok = self.do_work()
                    if ok:
                        Pacing.set_start(self.last_work_start or time.time())
                    else:
                        Pacing.release_bootstrap()
                        time.sleep(0.05)
                else:
                    time.sleep(0.01)
                continue

            slot = Pacing.get_slot()
            if slot is None:
                raise StopUser()

            now = time.time()
            if slot > now:
                time.sleep(slot - now)

            if Pacing.stop_time is not None and time.time() > Pacing.stop_time:
                raise StopUser()

            self.do_work()


class WorkLoadShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 55:
            return (16, 16)
        return None
